class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        n, m = len(haystack), len(needle)
        if m == 0:
            return 0
        # Build KMP failure function
        lps = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and needle[i] != needle[j]:
                j = lps[j-1]
            if needle[i] == needle[j]:
                j += 1
            lps[i] = j
        j = 0
        for i in range(n):
            while j > 0 and haystack[i] != needle[j]:
                j = lps[j-1]
            if haystack[i] == needle[j]:
                j += 1
            if j == m:
                return i - m + 1
        return -1

class Solution:
    def findSubstring(self, s, words):
        from collections import Counter
        if not words: return []
        wl,n,m=len(words[0]),len(s),len(words)
        need=Counter(words)
        res=[]
        for i in range(wl):
            l=i; cur=Counter(); cnt=0
            for r in range(i,n-wl+1,wl):
                w=s[r:r+wl]
                if w in need:
                    cur[w]+=1; cnt+=1
                    while cur[w]>need[w]:
                        cur[s[l:l+wl]]-=1; l+=wl; cnt-=1
                    if cnt==m: res.append(l)
                else:
                    cur.clear(); cnt=0; l=r+wl
        return res

