class Solution:
    def isValidSudoku(self, board: list[list[str]]) -> bool:
        rows = [set() for _ in range(9)]
        cols = [set() for _ in range(9)]
        boxes = [set() for _ in range(9)]
        for i in range(9):
            for j in range(9):
                c = board[i][j]
                if c == '.':
                    continue
                box_idx = (i // 3) * 3 + j // 3
                if c in rows[i] or c in cols[j] or c in boxes[box_idx]:
                    return False
                rows[i].add(c)
                cols[j].add(c)
                boxes[box_idx].add(c)
        return True

class Solution:
    def solveSudoku(self, board: list[list[str]]) -> None:
        rows = [set() for _ in range(9)]
        cols = [set() for _ in range(9)]
        boxes = [set() for _ in range(9)]
        empty = []
        for i in range(9):
            for j in range(9):
                if board[i][j] == '.':
                    empty.append((i, j))
                else:
                    d = board[i][j]
                    rows[i].add(d)
                    cols[j].add(d)
                    boxes[(i//3)*3+j//3].add(d)
        def backtrack(idx):
            if idx == len(empty):
                return True
            i, j = empty[idx]
            box_idx = (i//3)*3+j//3
            for d in '123456789':
                if d not in rows[i] and d not in cols[j] and d not in boxes[box_idx]:
                    board[i][j] = d
                    rows[i].add(d)
                    cols[j].add(d)
                    boxes[box_idx].add(d)
                    if backtrack(idx+1):
                        return True
                    board[i][j] = '.'
                    rows[i].remove(d)
                    cols[j].remove(d)
                    boxes[box_idx].remove(d)
            return False
        backtrack(0)

