class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0] == '0':
            return 0
        prev2, prev1 = 1, 1
        for i in range(1, len(s)):
            curr = 0
            if s[i] != '0':
                curr = prev1
            two = int(s[i-1:i+1])
            if 10 <= two <= 26:
                curr += prev2
            prev2, prev1 = prev1, curr
        return prev1

class Solution:
    def reverseBetween(self, head: ListNode, left: int, right: int) -> ListNode:
        dummy = ListNode(0, head)
        prev = dummy
        for _ in range(left - 1):
            prev = prev.next
        cur = prev.next
        for _ in range(right - left):
            nxt = cur.next
            cur.next = nxt.next
            nxt.next = prev.next
            prev.next = nxt
        return dummy.next

class Solution:
    def restoreIpAddresses(self, s: str) -> list[str]:
        res = []
        def backtrack(start, parts):
            if len(parts) == 4:
                if start == len(s):
                    res.append('.'.join(parts))
                return
            for length in range(1, 4):
                if start + length > len(s):
                    break
                seg = s[start:start+length]
                if (len(seg) > 1 and seg[0] == '0') or int(seg) > 255:
                    continue
                backtrack(start+length, parts + [seg])
        backtrack(0, [])
        return res

class Solution:
    def inorderTraversal(self, root: Optional[TreeNode]) -> List[int]:
        res, stack = [], []
        curr = root
        while curr or stack:
            while curr:
                stack.append(curr)
                curr = curr.left
            curr = stack.pop()
            res.append(curr.val)
            curr = curr.right
        return res

class Solution:
    def generateTrees(self, n: int) -> list[TreeNode]:
        def build(lo, hi):
            if lo > hi:
                return [None]
            trees = []
            for i in range(lo, hi+1):
                for left in build(lo, i-1):
                    for right in build(i+1, hi):
                        root = TreeNode(i)
                        root.left = left
                        root.right = right
                        trees.append(root)
            return trees
        return build(1, n)

class Solution:
    def numTrees(self, n: int) -> int:
        dp = [0] * (n + 1)
        dp[0] = dp[1] = 1
        for i in range(2, n + 1):
            for j in range(1, i + 1):
                dp[i] += dp[j-1] * dp[i-j]
        return dp[n]

class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        m, n = len(s1), len(s2)
        if m + n != len(s3):
            return False
        dp = [False] * (n + 1)
        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 and j == 0:
                    dp[j] = True
                elif i == 0:
                    dp[j] = dp[j-1] and s2[j-1] == s3[j-1]
                elif j == 0:
                    dp[j] = dp[j] and s1[i-1] == s3[i-1]
                else:
                    dp[j] = (dp[j] and s1[i-1] == s3[i+j-1]) or (dp[j-1] and s2[j-1] == s3[i+j-1])
        return dp[n]

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def validate(node, lo, hi):
            if not node:
                return True
            if node.val <= lo or node.val >= hi:
                return False
            return validate(node.left, lo, node.val) and validate(node.right, node.val, hi)
        return validate(root, float('-inf'), float('inf'))

class Solution:
    def recoverTree(self, root: TreeNode) -> None:
        first = second = prev = None
        def inorder(node):
            nonlocal first, second, prev
            if not node:
                return
            inorder(node.left)
            if prev and prev.val > node.val:
                if not first:
                    first = prev
                second = node
            prev = node
            inorder(node.right)
        inorder(root)
        first.val, second.val = second.val, first.val

class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        if not p and not q: return True
        if not p or not q: return False
        return p.val == q.val and self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right)

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        def mirror(t1, t2):
            if not t1 and not t2:
                return True
            if not t1 or not t2:
                return False
            return (t1.val == t2.val and
                    mirror(t1.left, t2.right) and
                    mirror(t1.right, t2.left))
        return mirror(root.left, root.right) if root else True

class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        from collections import deque
        queue = deque([root])
        result = []
        while queue:
            level = []
            for _ in range(len(queue)):
                node = queue.popleft()
                level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            result.append(level)
        return result

class Solution:
    def zigzagLevelOrder(self, root: TreeNode) -> list[list[int]]:
        if not root:
            return []
        from collections import deque
        q = deque([root])
        res = []
        left_to_right = True
        while q:
            level = []
            for _ in range(len(q)):
                node = q.popleft()
                level.append(node.val)
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            if not left_to_right:
                level.reverse()
            res.append(level)
            left_to_right = not left_to_right
        return res

class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0
        return 1 + max(self.maxDepth(root.left), self.maxDepth(root.right))

class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        idx_map = {val: i for i, val in enumerate(inorder)}
        self.pre_idx = 0
        def build(lo, hi):
            if lo > hi:
                return None
            root_val = preorder[self.pre_idx]
            self.pre_idx += 1
            root = TreeNode(root_val)
            mid = idx_map[root_val]
            root.left = build(lo, mid - 1)
            root.right = build(mid + 1, hi)
            return root
        return build(0, len(inorder) - 1)

class Solution:
    def buildTree(self, inorder: list[int], postorder: list[int]) -> TreeNode:
        idx_map = {v: i for i, v in enumerate(inorder)}
        def build(in_l, in_r, post_l, post_r):
            if in_l > in_r:
                return None
            root_val = postorder[post_r]
            root = TreeNode(root_val)
            idx = idx_map[root_val]
            left_size = idx - in_l
            root.left = build(in_l, idx-1, post_l, post_l+left_size-1)
            root.right = build(idx+1, in_r, post_l+left_size, post_r-1)
            return root
        return build(0, len(inorder)-1, 0, len(postorder)-1)

class Solution:
    def levelOrderBottom(self, root: TreeNode) -> list[list[int]]:
        if not root:
