class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: list[str]) -> list[list[str]]:
        from collections import defaultdict, deque
        word_set = set(wordList)
        if endWord not in word_set:
            return []
        layer = defaultdict(set)
        # BFS to build layer graph
        q = deque([beginWord])
        visited = {beginWord}
        found = False
        while q and not found:
            current_visited = set()
            for _ in range(len(q)):
                word = q.popleft()
                for i in range(len(word)):
                    for c in 'abcdefghijklmnopqrstuvwxyz':
                        nw = word[:i] + c + word[i+1:]
                        if nw in word_set and nw not in visited:
                            current_visited.add(nw)
                            layer[nw].add(word)
                            if nw == endWord:
                                found = True
            visited |= current_visited
            q = deque(current_visited)
        # DFS backtrack from endWord
        res = []
        def backtrack(word, path):
            if word == beginWord:
                res.append(path[::-1])
                return
            for prev in layer[word]:
                backtrack(prev, path + [prev])
        if found:
            backtrack(endWord, [endWord])
        return res

class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        from collections import deque
        word_set = set(wordList)
        if endWord not in word_set:
            return 0
        queue = deque([(beginWord, 1)])
        visited = {beginWord}
        while queue:
            word, steps = queue.popleft()
            for i in range(len(word)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    next_word = word[:i] + c + word[i+1:]
                    if next_word == endWord:
                        return steps + 1
                    if next_word in word_set and next_word not in visited:
                        visited.add(next_word)
                        queue.append((next_word, steps + 1))
        return 0

