        if not node:
            return None
        cloned = {node: Node(node.val)}
        from collections import deque
        queue = deque([node])
        while queue:
            curr = queue.popleft()
            for nei in curr.neighbors:
                if nei not in cloned:
                    cloned[nei] = Node(nei.val)
                    queue.append(nei)
                cloned[curr].neighbors.append(cloned[nei])
        return cloned[node]

