        word_set = set(wordDict)
        @lru_cache(maxsize=None)
        def backtrack(start):
            if start == len(s):
                return ['']
            res = []
            for end in range(start+1, len(s)+1):
                word = s[start:end]
                if word in word_set:
                    for sub in backtrack(end):
                        res.append(word + (' ' + sub if sub else ''))
            return res
        return backtrack(0)

