class Solution:
    def __init__(self):
        self.buf4 = [''] * 4
        self.buf_ptr = 0
        self.buf_cnt = 0

    def read(self, buf, n):
        total = 0
        while total < n:
            if self.buf_ptr == self.buf_cnt:
                self.buf_cnt = read4(self.buf4)
                self.buf_ptr = 0
            if self.buf_cnt == 0:
                break
            while total < n and self.buf_ptr < self.buf_cnt:
