        self.children = {}
        self.is_end = False

    def addWord(self, word: str) -> None:
        node = self
        for ch in word:
            if ch not in node.children:
                node.children[ch] = WordDictionary()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self
        for i, ch in enumerate(word):
            if ch == '.':
                return any(child.search(word[i+1:]) for child in node.children.values() if child)
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        trie = {}
        for word in words:
            node = trie
            for ch in word:
                node = node.setdefault(ch, {})
            node['#'] = word
        m, n = len(board), len(board[0])
        result = []
        def dfs(i, j, node):
            ch = board[i][j]
            if ch not in node:
                return
            next_node = node[ch]
            if '#' in next_node:
                result.append(next_node.pop('#'))
            board[i][j] = '.'
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and board[ni][nj] != '.':
                    dfs(ni, nj, next_node)
            board[i][j] = ch
            if not next_node:
                del node[ch]
        for i in range(m):
            for j in range(n):
                dfs(i, j, trie)
        return result

class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        def rob_linear(arr):
            prev, curr = 0, 0
            for num in arr:
                prev, curr = curr, max(curr, prev + num)
            return curr
        return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

class Solution:
    def shortestPalindrome(self, s: str) -> str:
        rev = s[::-1]
        t = s + '#' + rev
        lps = [0] * len(t)
        for i in range(1, len(t)):
            j = lps[i-1]
            while j > 0 and t[i] != t[j]:
                j = lps[j-1]
            if t[i] == t[j]:
                j += 1
            lps[i] = j
        return rev[:len(s)-lps[-1]] + s

