import heapq
class Solution:
    def getSkyline(self, buildings: List[List[int]]) -> List[List[int]]:
        events = []
        for l, r, h in buildings:
            events.append((l, -h, r))
            events.append((r, 0, 0))
        events.sort()
        result = [[0, 0]]
        heap = [(0, float('inf'))]  # (-height, end)
        for x, neg_h, end in events:
            if neg_h:
                heapq.heappush(heap, (neg_h, end))
            while heap[0][1] <= x:
                heapq.heappop(heap)
            max_h = -heap[0][0]
            if max_h != result[-1][1]:
                result.append([x, max_h])
        return result[1:]

