        slow = fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        # reverse second half
        prev = None
        while slow:
            nxt = slow.next
            slow.next = prev
            prev = slow
            slow = nxt
        # compare
        while prev:
            if head.val != prev.val:
                return False
            head = head.next
            prev = prev.next
        return True

