        self.count = 0
        def dfs(node):
            if not node:
                return True
            left = dfs(node.left)
            right = dfs(node.right)
            if left and right:
                if node.left and node.left.val != node.val:
                    return False
                if node.right and node.right.val != node.val:
                    return False
                self.count += 1
                return True
            return False
        dfs(root)
        return self.count

class Vector2D:
    def __init__(self, vec: list[list[int]]):
        self.vec = vec
        self.outer = 0
        self.inner = 0

    def _advance(self):
        while self.outer < len(self.vec) and self.inner >= len(self.vec[self.outer]):
            self.outer += 1
            self.inner = 0

    def next(self) -> int:
        self._advance()
        val = self.vec[self.outer][self.inner]
        self.inner += 1
        return val

    def hasNext(self) -> bool:
        self._advance()
        return self.outer < len(self.vec)

