        if not intervals:
            return 0
        intervals.sort()
        heap = []  # end times
        for start, end in intervals:
            if heap and heap[0] <= start:
                heapq.heappop(heap)
            heapq.heappush(heap, end)
        return len(heap)

class Solution:
