        if not costs:
            return 0
        n, k = len(costs), len(costs[0])
        min1 = min2 = 0
        idx1 = -1
        for i in range(n):
            new_min1 = new_min2 = float('inf')
            new_idx1 = -1
            for j in range(k):
                cost = costs[i][j] + (min1 if j != idx1 else min2)
                if cost < new_min1:
                    new_min2 = new_min1
                    new_min1 = cost
                    new_idx1 = j
                elif cost < new_min2:
                    new_min2 = cost
            min1, min2, idx1 = new_min1, new_min2, new_idx1
        return min1

