class Solution:
    def generatePalindromes(self, s: str) -> list[str]:
        from collections import Counter
        count = Counter(s)
        odds = [k for k, v in count.items() if v % 2]
        if len(odds) > 1:
            return []
        mid = odds[0] if odds else ''
        half = []
        for c, v in count.items():
            half.extend([c] * (v // 2))
        res = set()
        from itertools import permutations
        for perm in set(permutations(half)):
            h = ''.join(perm)
            res.add(h + mid + h[::-1])
        return list(res)

