class ValidWordAbbr:
    def __init__(self, dictionary: list[str]):
        self.abbr_map = {}
        for word in set(dictionary):
            a = self._abbr(word)
            if a in self.abbr_map:
                self.abbr_map[a] = ''
            else:
                self.abbr_map[a] = word

    def _abbr(self, word):
        if len(word) <= 2:
            return word
        return word[0] + str(len(word)-2) + word[-1]

    def isUnique(self, word: str) -> bool:
        a = self._abbr(word)
        return a not in self.abbr_map or self.abbr_map[a] == word

class Solution:
    def gameOfLife(self, board: List[List[int]]) -> None:
        m, n = len(board), len(board[0])
        for i in range(m):
            for j in range(n):
                live = 0
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        if di == 0 and dj == 0: continue
                        ni, nj = i+di, j+dj
                        if 0 <= ni < m and 0 <= nj < n and board[ni][nj] in (1, 2):
                            live += 1
                if board[i][j] == 1 and (live < 2 or live > 3):
                    board[i][j] = 2  # live -> dead
                elif board[i][j] == 0 and live == 3:
                    board[i][j] = 3  # dead -> live
        for i in range(m):
            for j in range(n):
                board[i][j] %= 2

class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        words = s.split()
        if len(pattern) != len(words):
            return False
        p2w, w2p = {}, {}
        for p, w in zip(pattern, words):
            if p in p2w and p2w[p] != w:
                return False
            if w in w2p and w2p[w] != p:
                return False
            p2w[p] = w
            w2p[w] = p
        return True

class Solution:
    def wordPatternMatch(self, pattern: str, s: str) -> bool:
        def backtrack(pi, si, p2s, s2p):
            if pi == len(pattern) and si == len(s):
                return True
            if pi == len(pattern) or si == len(s):
                return False
            p = pattern[pi]
            if p in p2s:
                word = p2s[p]
                if not s[si:].startswith(word):
                    return False
                return backtrack(pi+1, si+len(word), p2s, s2p)
            for end in range(si+1, len(s)+1):
                word = s[si:end]
                if word in s2p:
                    continue
                p2s[p] = word
                s2p[word] = p
                if backtrack(pi+1, end, p2s, s2p):
                    return True
                del p2s[p]
                del s2p[word]
            return False
        return backtrack(0, 0, {}, {})

