class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        def is_valid(s):
            count = 0
            for ch in s:
                if ch == '(': count += 1
                elif ch == ')': count -= 1
                if count < 0: return False
            return count == 0
        from collections import deque
        visited = {s}
        queue = deque([s])
        result = []
        found = False
        while queue:
            word = queue.popleft()
            if is_valid(word):
                result.append(word)
                found = True
            if found:
                continue
            for i in range(len(word)):
                if word[i] not in '()':
                    continue
                candidate = word[:i] + word[i+1:]
                if candidate not in visited:
                    visited.add(candidate)
                    queue.append(candidate)
        return result

class Solution:
    def minArea(self, image: list[list[str]], x: int, y: int) -> int:
        m, n = len(image), len(image[0])
        def search_rows(lo, hi, check):
            while lo < hi:
                mid = (lo+hi)//2
                if check(mid): hi = mid
                else: lo = mid+1
            return lo
        def search_cols(lo, hi, check):
            while lo < hi:
                mid = (lo+hi)//2
                if check(mid): hi = mid
                else: lo = mid+1
            return lo
        top = search_rows(0, x, lambda r: '1' in image[r])
        bottom = search_rows(x+1, m, lambda r: '1' not in image[r])
        left = search_cols(0, y, lambda c: any(image[r][c]=='1' for r in range(m)))
        right = search_cols(y+1, n, lambda c: not any(image[r][c]=='1' for r in range(m)))
        return (bottom-top)*(right-left)

