        m, n = len(matrix), len(matrix[0])
        self.p = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                self.p[i+1][j+1] = matrix[i][j] + self.p[i][j+1] + self.p[i+1][j] - self.p[i][j]

    def sumRegion(self, r1: int, c1: int, r2: int, c2: int) -> int:
        return self.p[r2+1][c2+1] - self.p[r1][c2+1] - self.p[r2+1][c1] + self.p[r1][c1]

class Solution:
    def numIslands2(self, m: int, n: int, positions: list[list[int]]) -> list[int]:
        parent = {}
        self.count = 0
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                self.count -= 1
        res = []
        for r, c in positions:
            if (r,c) in parent:
                res.append(self.count)
                continue
            parent[(r,c)] = (r,c)
            self.count += 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if (nr,nc) in parent:
                    union((r,c),(nr,nc))
            res.append(self.count)
        return res

class Solution:
    def isAdditiveNumber(self, num: str) -> bool:
        n = len(num)
        for i in range(1, n):
            for j in range(i+1, n):
                a, b = num[:i], num[i:j]
                if (len(a) > 1 and a[0] == '0') or (len(b) > 1 and b[0] == '0'):
                    continue
                while j < n:
                    c = str(int(a) + int(b))
                    if not num[j:].startswith(c):
                        break
                    j += len(c)
                    a, b = b, c
                if j == n:
                    return True
        return False

class NumArray:
    def __init__(self, nums: list[int]):
        self.n = len(nums)
        self.nums = [0] * self.n
        self.bit = [0] * (self.n + 1)
        for i, v in enumerate(nums):
            self.update(i, v)

    def _add(self, i, delta):
        i += 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & (-i)

    def _prefix(self, i):
        s = 0
        i += 1
        while i > 0:
            s += self.bit[i]
            i -= i & (-i)
        return s

    def update(self, index: int, val: int) -> None:
        delta = val - self.nums[index]
        self.nums[index] = val
        self._add(index, delta)

    def sumRange(self, left: int, right: int) -> int:
        return self._prefix(right) - (self._prefix(left-1) if left > 0 else 0)

class NumMatrix:
    def __init__(self, matrix: list[list[int]]):
        self.m, self.n = len(matrix), len(matrix[0])
        self.mat = [[0]*self.n for _ in range(self.m)]
        self.bit = [[0]*(self.n+1) for _ in range(self.m+1)]
        for i in range(self.m):
            for j in range(self.n):
                self.update(i, j, matrix[i][j])

    def _add(self, r, c, delta):
        i = r + 1
        while i <= self.m:
            j = c + 1
            while j <= self.n:
                self.bit[i][j] += delta
                j += j & (-j)
            i += i & (-i)

    def _query(self, r, c):
        s = 0
        i = r + 1
        while i > 0:
            j = c + 1
            while j > 0:
                s += self.bit[i][j]
                j -= j & (-j)
            i -= i & (-i)
        return s

    def update(self, row, col, val):
        delta = val - self.mat[row][col]
        self.mat[row][col] = val
        self._add(row, col, delta)

    def sumRegion(self, r1, c1, r2, c2):
        return self._query(r2,c2)-self._query(r1-1,c2)-self._query(r2,c1-1)+self._query(r1-1,c1-1)

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        if not prices:
            return 0
        hold, sold, rest = -prices[0], 0, 0
        for price in prices[1:]:
            hold, sold, rest = max(hold, rest - price), hold + price, max(rest, sold)
        return max(sold, rest)

class Solution:
    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        if n <= 2:
            return list(range(n))
        from collections import defaultdict, deque
        adj = defaultdict(set)
        for u, v in edges:
            adj[u].add(v)
            adj[v].add(u)
        leaves = deque(i for i in range(n) if len(adj[i]) == 1)
        remaining = n
        while remaining > 2:
            remaining -= len(leaves)
            new_leaves = deque()
            for leaf in leaves:
                neighbor = adj[leaf].pop()
                adj[neighbor].remove(leaf)
                if len(adj[neighbor]) == 1:
                    new_leaves.append(neighbor)
            leaves = new_leaves
        return list(leaves)

class Solution:
    def multiply(self, mat1: list[list[int]], mat2: list[list[int]]) -> list[list[int]]:
        m, k, n = len(mat1), len(mat1[0]), len(mat2[0])
        res = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(k):
                if mat1[i][j] == 0:
                    continue
                for l in range(n):
                    res[i][l] += mat1[i][j] * mat2[j][l]
        return res

class Solution:
    def maxCoins(self, nums: List[int]) -> int:
        nums = [1] + nums + [1]
        n = len(nums)
        dp = [[0] * n for _ in range(n)]
        for length in range(2, n):
            for i in range(n - length):
                j = i + length
                for k in range(i + 1, j):
                    dp[i][j] = max(dp[i][j],
                        dp[i][k] + dp[k][j] + nums[i] * nums[k] * nums[j])
        return dp[0][n-1]

class Solution:
    def nthSuperUglyNumber(self, n: int, primes: list[int]) -> int:
        dp = [1] * n
        k = len(primes)
        ptrs = [0] * k
        for i in range(1, n):
            candidates = [dp[ptrs[j]] * primes[j] for j in range(k)]
            dp[i] = min(candidates)
            for j in range(k):
                if candidates[j] == dp[i]:
                    ptrs[j] += 1
        return dp[-1]

class Solution:
    def verticalOrder(self, root: TreeNode) -> list[list[int]]:
        if not root:
            return []
        from collections import defaultdict, deque
        col_map = defaultdict(list)
        q = deque([(root, 0)])
        while q:
            node, col = q.popleft()
            col_map[col].append(node.val)
            if node.left:
                q.append((node.left, col-1))
            if node.right:
                q.append((node.right, col+1))
        return [col_map[c] for c in sorted(col_map)]

class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        last = {c: i for i, c in enumerate(s)}
        stack = []
        in_stack = set()
        for i, c in enumerate(s):
            if c in in_stack:
                continue
            while stack and c < stack[-1] and last[stack[-1]] > i:
                in_stack.remove(stack.pop())
            stack.append(c)
            in_stack.add(c)
        return ''.join(stack)

class Solution:
    def shortestDistance(self, grid: list[list[int]]) -> int:
        from collections import deque
        m, n = len(grid), len(grid[0])
        dist = [[0]*n for _ in range(m)]
        reach = [[0]*n for _ in range(m)]
        buildings = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    buildings += 1
                    visited = [[False]*n for _ in range(m)]
                    q = deque([(i,j,0)])
                    visited[i][j] = True
                    while q:
                        x,y,d = q.popleft()
                        for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                            nx,ny = x+dx,y+dy
                            if 0<=nx<m and 0<=ny<n and not visited[nx][ny] and grid[nx][ny]==0:
                                visited[nx][ny] = True
                                dist[nx][ny] += d+1
                                reach[nx][ny] += 1
                                q.append((nx,ny,d+1))
        res = float('inf')
        for i in range(m):
            for j in range(n):
                if grid[i][j]==0 and reach[i][j]==buildings:
                    res = min(res, dist[i][j])
        return res if res != float('inf') else -1

class Solution:
    def maxProduct(self, words: list[str]) -> int:
        masks = [0] * len(words)
        for i, w in enumerate(words):
            for c in w:
                masks[i] |= 1 << (ord(c) - ord('a'))
        res = 0
        for i in range(len(words)):
            for j in range(i+1, len(words)):
                if masks[i] & masks[j] == 0:
                    res = max(res, len(words[i]) * len(words[j]))
        return res

class Solution:
    def bulbSwitch(self, n: int) -> int:
