class Solution:
    def generateAbbreviations(self, word: str) -> list[str]:
        res = []
        def backtrack(i, path, count):
            if i == len(word):
                res.append(path + (str(count) if count else ''))
                return
            backtrack(i+1, path, count+1)
            backtrack(i+1, path + (str(count) if count else '') + word[i], 0)
        backtrack(0, '', 0)
        return res

class Solution:
    def maxNumber(self, nums1: list[int], nums2: list[int], k: int) -> list[int]:
        def max_subseq(nums, length):
            drop = len(nums) - length
            stack = []
            for n in nums:
                while drop and stack and stack[-1] < n:
                    stack.pop()
                    drop -= 1
                stack.append(n)
            return stack[:length]
        def merge(a, b):
            res = []
            while a or b:
                if a >= b:
                    res.append(a[0])
                    a = a[1:]
                else:
                    res.append(b[0])
                    b = b[1:]
            return res
        best = []
        for i in range(max(0,k-len(nums2)), min(k,len(nums1))+1):
            candidate = merge(max_subseq(nums1,i), max_subseq(nums2,k-i))
            best = max(best, candidate)
        return best

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        dp = [0] + [float('inf')] * amount
        for i in range(1, amount + 1):
            for coin in coins:
                if coin <= i:
                    dp[i] = min(dp[i], dp[i - coin] + 1)
        return dp[amount] if dp[amount] != float('inf') else -1

class Solution:
    def countComponents(self, n: int, edges: List[List[int]]) -> int:
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        components = n
        for u, v in edges:
            pu, pv = find(u), find(v)
            if pu != pv:
                parent[pu] = pv
                components -= 1
        return components

class Solution:
    def wiggleSort(self, nums: list[int]) -> None:
        import statistics
        n = len(nums)
        mid = statistics.median(nums)
        sorted_nums = sorted(nums)
        small = sorted_nums[:n//2+n%2][::-1]
        large = sorted_nums[n//2+n%2:][::-1]
        for i in range(len(small)):
            nums[2*i] = small[i]
        for i in range(len(large)):
            nums[2*i+1] = large[i]

class Solution:
    def maxSubArrayLen(self, nums: list[int], k: int) -> int:
        prefix_map = {0: -1}
        prefix = 0
        res = 0
        for i, num in enumerate(nums):
            prefix += num
            if prefix - k in prefix_map:
                res = max(res, i - prefix_map[prefix-k])
            if prefix not in prefix_map:
                prefix_map[prefix] = i
        return res

class Solution:
    def isPowerOfThree(self, n: int) -> bool:
