class Solution:
    def countRangeSum(self, nums: list[int], lower: int, upper: int) -> int:
        prefix = [0]
        for n in nums:
            prefix.append(prefix[-1] + n)
        self.count = 0
        def merge_sort(arr):
            if len(arr) <= 1:
                return arr
            mid = len(arr) // 2
            left = merge_sort(arr[:mid])
            right = merge_sort(arr[mid:])
            j = k = 0
            for l in left:
                while j < len(right) and right[j] - l < lower:
                    j += 1
                while k < len(right) and right[k] - l <= upper:
                    k += 1
                self.count += k - j
            return sorted(left + right)
        merge_sort(prefix)
        return self.count

class Solution:
    def oddEvenList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head:
            return None
        odd, even = head, head.next
        even_head = even
        while even and even.next:
            odd.next = even.next
            odd = odd.next
            even.next = odd.next
            even = even.next
        odd.next = even_head
        return head

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        from functools import lru_cache
        m, n = len(matrix), len(matrix[0])
        @lru_cache(maxsize=None)
        def dfs(i, j):
            best = 1
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > matrix[i][j]:
                    best = max(best, 1 + dfs(ni, nj))
            return best
        return max(dfs(i, j) for i in range(m) for j in range(n))

class Solution:
    def minPatches(self, nums: list[int], n: int) -> int:
        miss = 1
        patches = 0
        i = 0
        while miss <= n:
            if i < len(nums) and nums[i] <= miss:
                miss += nums[i]
                i += 1
            else:
                miss += miss
                patches += 1
        return patches

class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        slots = 1
        for node in preorder.split(','):
            slots -= 1
            if slots < 0:
                return False
            if node != '#':
                slots += 2
        return slots == 0

class Solution:
    def findItinerary(self, tickets: list[list[str]]) -> list[str]:
        from collections import defaultdict
        graph = defaultdict(list)
        for src, dst in sorted(tickets, reverse=True):
            graph[src].append(dst)
        route = []
        def dfs(airport):
            while graph[airport]:
                dfs(graph[airport].pop())
            route.append(airport)
        dfs('JFK')
        return route[::-1]

class Solution:
    def largestBSTSubtree(self, root: TreeNode) -> int:
        self.res = 0
        def dfs(node):
            if not node:
                return (True, 0, float('inf'), float('-inf'))
            l_bst, l_size, l_min, l_max = dfs(node.left)
            r_bst, r_size, r_min, r_max = dfs(node.right)
            if l_bst and r_bst and l_max < node.val < r_min:
                size = l_size + r_size + 1
                self.res = max(self.res, size)
                return (True, size, min(l_min, node.val), max(r_max, node.val))
            return (False, 0, 0, 0)
        dfs(root)
        return self.res

class Solution:
    def increasingTriplet(self, nums: List[int]) -> bool:
        first = second = float('inf')
        for num in nums:
            if num <= first:
                first = num
            elif num <= second:
                second = num
            else:
                return True
        return False

class Solution:
    def isSelfCrossing(self, distance: list[int]) -> bool:
        d = distance
        for i in range(3, len(d)):
            if d[i] >= d[i-2] and d[i-1] <= d[i-3]:
                return True
            if i >= 4 and d[i-1] == d[i-3] and d[i] + d[i-4] >= d[i-2]:
                return True
            if i >= 5 and d[i-2] >= d[i-4] and d[i] + d[i-4] >= d[i-2] and d[i-1] <= d[i-3] and d[i-1] + d[i-5] >= d[i-3]:
                return True
        return False

class Solution:
    def palindromePairs(self, words: list[str]) -> list[list[int]]:
        word_map = {w: i for i, w in enumerate(words)}
        res = []
        for i, word in enumerate(words):
            for j in range(len(word)+1):
                prefix, suffix = word[:j], word[j:]
                if prefix == prefix[::-1]:
                    rev_suffix = suffix[::-1]
                    if rev_suffix in word_map and word_map[rev_suffix] != i:
                        res.append([word_map[rev_suffix], i])
                if j > 0 and suffix == suffix[::-1]:
                    rev_prefix = prefix[::-1]
                    if rev_prefix in word_map and word_map[rev_prefix] != i:
                        res.append([i, word_map[rev_prefix]])
        return res

class Solution:
    def rob(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            if not node:
                return (0, 0)  # (rob, not_rob)
            left = dfs(node.left)
            right = dfs(node.right)
            rob_it = node.val + left[1] + right[1]
            skip_it = max(left) + max(right)
            return (rob_it, skip_it)
        return max(dfs(root))

class Solution:
    def countBits(self, n: int) -> List[int]:
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i >> 1] + (i & 1)
        return dp

class Solution:
    def depthSum(self, nestedList) -> int:
        def dfs(lst, depth):
            total = 0
            for item in lst:
                if item.isInteger():
                    total += item.getInteger() * depth
                else:
                    total += dfs(item.getList(), depth + 1)
            return total
        return dfs(nestedList, 1)

class Solution:
    def lengthOfLongestSubstringKDistinct(self, s: str, k: int) -> int:
        from collections import defaultdict
        count = defaultdict(int)
        left = res = 0
        for right in range(len(s)):
            count[s[right]] += 1
            while len(count) > k:
                count[s[left]] -= 1
                if count[s[left]] == 0:
                    del count[s[left]]
                left += 1
            res = max(res, right - left + 1)
        return res

class NestedIterator:
    def __init__(self, nestedList):
        self.stack = nestedList[::-1]

    def next(self) -> int:
        return self.stack.pop().getInteger()

    def hasNext(self) -> bool:
        while self.stack:
            top = self.stack[-1]
            if top.isInteger():
                return True
            self.stack.pop()
            self.stack.extend(top.getList()[::-1])
        return False

class Solution:
