class Solution:
    def sortTransformedArray(self, nums: list[int], a: int, b: int, c: int) -> list[int]:
        def f(x):
            return a*x*x + b*x + c
        n = len(nums)
        res = [0] * n
        l, r = 0, n - 1
        idx = n-1 if a >= 0 else 0
        while l <= r:
            fl, fr = f(nums[l]), f(nums[r])
            if a >= 0:
                if fl >= fr:
                    res[idx] = fl; l += 1
                else:
                    res[idx] = fr; r -= 1
                idx -= 1
            else:
                if fl <= fr:
                    res[idx] = fl; l += 1
                else:
                    res[idx] = fr; r -= 1
                idx += 1
        return res

