class Solution:
    def getSum(self, a: int, b: int) -> int:
        MASK = 0xFFFFFFFF
        while b & MASK:
            carry = (a & b) << 1
            a = a ^ b
            b = carry
        return a & MASK if b > 0 else a

class Solution:
    def superPow(self, a: int, b: list[int]) -> int:
        MOD = 1337
        def power(base, exp):
            result = 1
            base %= MOD
            while exp:
                if exp & 1:
                    result = result * base % MOD
                base = base * base % MOD
                exp >>= 1
            return result
        result = 1
        for digit in b:
            result = power(result, 10) * power(a, digit) % MOD
        return result

