class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def can_split(max_sum):
            count, curr = 1, 0
            for num in nums:
                if curr + num > max_sum:
                    count += 1
                    curr = num
                else:
                    curr += num
            return count <= k
        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if can_split(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def minAbbreviation(self, target: str, dictionary: list[str]) -> str:
        n = len(target)
        diffs = []
        for word in dictionary:
            if len(word) != n:
                continue
            diff = 0
            for i in range(n):
                if target[i] != word[i]:
                    diff |= 1 << i
            diffs.append(diff)
        if not diffs:
            return str(n)
        def abbr_len(mask):
            length = 0
            i = 0
            while i < n:
                length += 1
                if mask & (1 << i):
                    i += 1
                else:
                    while i < n and not (mask & (1 << i)):
                        i += 1
            return length
        best = (1 << n) - 1
        for mask in range(1, 1 << n):
            if all(mask & d for d in diffs):
                if abbr_len(mask) < abbr_len(best):
                    best = mask
        res = []
        i = 0
        while i < n:
            if best & (1 << i):
                res.append(target[i])
                i += 1
            else:
                j = i
                while i < n and not (best & (1 << i)):
                    i += 1
                res.append(str(i - j))
        return ''.join(res)

class Solution:
    def fizzBuzz(self, n: int) -> List[str]:
        return ['FizzBuzz' if i%15==0 else 'Fizz' if i%3==0 else 'Buzz' if i%5==0 else str(i) for i in range(1, n+1)]

class Solution:
    def numberOfArithmeticSlices(self, nums: list[int]) -> int:
        dp = 0
        total = 0
        for i in range(2, len(nums)):
            if nums[i] - nums[i-1] == nums[i-1] - nums[i-2]:
                dp += 1
                total += dp
            else:
                dp = 0
        return total

class Solution:
    def thirdMax(self, nums: List[int]) -> int:
        top3 = sorted(set(nums), reverse=True)
        return top3[2] if len(top3) >= 3 else top3[0]

class Solution:
    def addStrings(self, num1: str, num2: str) -> str:
        res = []
        carry = 0
        i, j = len(num1)-1, len(num2)-1
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0: s += int(num1[i]); i -= 1
            if j >= 0: s += int(num2[j]); j -= 1
            res.append(str(s % 10))
            carry = s // 10
        return ''.join(reversed(res))

class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2 != 0:
            return False
        target = total // 2
        dp = [False] * (target + 1)
        dp[0] = True
        for num in nums:
            for j in range(target, num - 1, -1):
                dp[j] = dp[j] or dp[j - num]
        return dp[target]

class Solution:
    def pacificAtlantic(self, heights: list[list[int]]) -> list[list[int]]:
        if not heights:
            return []
        m, n = len(heights), len(heights[0])
        pacific = set()
        atlantic = set()
        def dfs(r, c, visited):
            visited.add((r, c))
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and (nr,nc) not in visited and heights[nr][nc] >= heights[r][c]:
                    dfs(nr, nc, visited)
        for i in range(m):
            dfs(i, 0, pacific)
            dfs(i, n-1, atlantic)
        for j in range(n):
            dfs(0, j, pacific)
            dfs(m-1, j, atlantic)
        return [list(x) for x in pacific & atlantic]

class Solution:
    def wordsTyping(self, sentence: list[str], rows: int, cols: int) -> int:
        s = ' '.join(sentence) + ' '
        n = len(s)
        pos = 0
        for _ in range(rows):
            pos += cols
            if s[pos % n] == ' ':
                pos += 1
            else:
                while pos > 0 and s[(pos-1) % n] != ' ':
                    pos -= 1
        return pos // n

class Solution:
    def countBattleships(self, board: list[list[str]]) -> int:
        count = 0
        for i in range(len(board)):
            for j in range(len(board[0])):
                if board[i][j] == 'X':
                    if (i == 0 or board[i-1][j] != 'X') and (j == 0 or board[i][j-1] != 'X'):
                        count += 1
        return count

class Solution:
    def strongPasswordChecker(self, password: str) -> int:
        n = len(password)
        has_lower = any(c.islower() for c in password)
        has_upper = any(c.isupper() for c in password)
        has_digit = any(c.isdigit() for c in password)
        missing = (not has_lower) + (not has_upper) + (not has_digit)
        # Find repeating sequences
        repeats = []
        i = 2
        while i < n:
            if password[i] == password[i-1] == password[i-2]:
                j = i
                while j < n and password[j] == password[i-1]:
                    j += 1
                repeats.append(j - i + 2)
                i = j
            else:
                i += 1
        if n < 6:
            return max(missing, 6 - n)
        elif n <= 20:
            replace = sum(r // 3 for r in repeats)
            return max(missing, replace)
        else:
            delete = n - 20
            replace = sum(r // 3 for r in repeats)
            # Use deletions to reduce replacements
            remaining_delete = delete
            repeats.sort(key=lambda x: x % 3)
            for i in range(len(repeats)):
                if remaining_delete <= 0:
                    break
                need = repeats[i] % 3 + 1
                use = min(remaining_delete, need)
                repeats[i] -= use
                remaining_delete -= use
            for i in range(len(repeats)):
                if remaining_delete <= 0:
                    break
                use = min(remaining_delete, repeats[i] - 2)
                if use > 0:
                    repeats[i] -= use
                    remaining_delete -= use
            replace = sum(r // 3 for r in repeats)
            return delete + max(missing, replace)

class Solution:
    def findMaximumXOR(self, nums: list[int]) -> int:
        max_xor = 0
        mask = 0
        for i in range(31, -1, -1):
            mask |= (1 << i)
            prefixes = {num & mask for num in nums}
            candidate = max_xor | (1 << i)
            for p in prefixes:
                if p ^ candidate in prefixes:
                    max_xor = candidate
                    break
        return max_xor

class Solution:
    def validWordSquare(self, words: list[str]) -> bool:
        for i in range(len(words)):
            for j in range(len(words[i])):
                if j >= len(words) or i >= len(words[j]) or words[i][j] != words[j][i]:
                    return False
        return True

class Solution:
    def originalDigits(self, s: str) -> str:
        from collections import Counter
        c = Counter(s)
        cnt = [0]*10
        cnt[0]=c['z']; cnt[2]=c['w']; cnt[4]=c['u']; cnt[6]=c['x']; cnt[8]=c['g']
        cnt[3]=c['h']-cnt[8]; cnt[5]=c['f']-cnt[4]; cnt[7]=c['s']-cnt[6]
        cnt[1]=c['o']-cnt[0]-cnt[2]-cnt[4]; cnt[9]=c['i']-cnt[5]-cnt[6]-cnt[8]
        return ''.join(str(i)*cnt[i] for i in range(10))

class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        count = {}
        max_freq = left = result = 0
        for right in range(len(s)):
            count[s[right]] = count.get(s[right], 0) + 1
            max_freq = max(max_freq, count[s[right]])
            while (right - left + 1) - max_freq > k:
                count[s[left]] -= 1
                left += 1
            result = max(result, right - left + 1)
        return result

class Solution:
    def wordSquares(self, words: list[str]) -> list[list[str]]:
        from collections import defaultdict
        n = len(words[0])
        pmap = defaultdict(list)
        for w in words:
            for i in range(n+1):
                pmap[w[:i]].append(w)
        res = []
        def bt(sq):
            if len(sq) == n:
                res.append(sq[:])
                return
            idx = len(sq)
            prefix = ''.join(s[idx] for s in sq)
            for cand in pmap[prefix]:
                sq.append(cand)
                bt(sq)
                sq.pop()
        bt([])
        return res

class Solution:
    def construct(self, grid):
        def build(r, c, sz):
            if sz == 1:
                return Node(grid[r][c]==1, True)
            h = sz//2
            tl,tr,bl,br = build(r,c,h),build(r,c+h,h),build(r+h,c,h),build(r+h,c+h,h)
            if all(x.isLeaf for x in [tl,tr,bl,br]) and len(set(x.val for x in [tl,tr,bl,br]))==1:
                return Node(tl.val, True)
            return Node(True, False, tl, tr, bl, br)
        return build(0, 0, len(grid))

class Codec:
    def serialize(self, root):
        if not root: return ''
        tokens = []
        def pre(node):
            tokens.append(f'{node.val},{len(node.children)}')
            for c in node.children: pre(c)
        pre(root)
        return ' '.join(tokens)
    def deserialize(self, data):
        if not data: return None
        it = iter(data.split())
        def build():
            v, n = next(it).split(',')
            node = Node(int(v), [])
            for _ in range(int(n)): node.children.append(build())
            return node
        return build()

class Codec:
    def encode(self, root):
        if not root: return None
        bn = TreeNode(root.val)
        if root.children:
            bn.left = self.encode(root.children[0])
        cur = bn.left
        for i in range(1, len(root.children)):
            cur.right = self.encode(root.children[i])
            cur = cur.right
        return bn
    def decode(self, data):
        if not data: return None
        node = Node(data.val, [])
        cur = data.left
        while cur:
            node.children.append(self.decode(cur))
            cur = cur.right
        return node

class AllOne:
    def __init__(self):
        from collections import defaultdict
        self.key_count = {}
        self.count_keys = defaultdict(set)
    def inc(self, key: str) -> None:
        old = self.key_count.get(key, 0)
        self.key_count[key] = old + 1
        if old: self.count_keys[old].discard(key)
        if old and not self.count_keys[old]: del self.count_keys[old]
        self.count_keys[old+1].add(key)
    def dec(self, key: str) -> None:
        old = self.key_count[key]
        self.count_keys[old].discard(key)
        if not self.count_keys[old]: del self.count_keys[old]
        if old == 1: del self.key_count[key]
        else: self.key_count[key] = old-1; self.count_keys[old-1].add(key)
    def getMaxKey(self) -> str:
        if not self.count_keys: return ''
        return next(iter(self.count_keys[max(self.count_keys)]))
    def getMinKey(self) -> str:
        if not self.count_keys: return ''
        return next(iter(self.count_keys[min(self.count_keys)]))

class Solution:
    def minMutation(self, startGene: str, endGene: str, bank: list[str]) -> int:
        from collections import deque
        bs = set(bank)
        if endGene not in bs: return -1
        q = deque([(startGene, 0)])
        vis = {startGene}
        while q:
            gene, steps = q.popleft()
            if gene == endGene: return steps
            for i in range(8):
                for c in 'ACGT':
                    if c != gene[i]:
                        ng = gene[:i]+c+gene[i+1:]
                        if ng in bs and ng not in vis:
                            vis.add(ng); q.append((ng, steps+1))
        return -1

class Solution:
    def countSegments(self, s: str) -> int:
        return len(s.split())

class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        intervals.sort(key=lambda x: x[1])
        count = 0
        end = float('-inf')
        for s, e in intervals:
            if s >= end:
                end = e
            else:
                count += 1
        return count

class Solution:
    def findRightInterval(self, intervals: list[list[int]]) -> list[int]:
        import bisect
        ss = sorted((iv[0], i) for i, iv in enumerate(intervals))
        starts = [s for s, _ in ss]
        res = []
        for _, end in intervals:
            idx = bisect.bisect_left(starts, end)
            res.append(ss[idx][1] if idx < len(ss) else -1)
        return res

class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        from collections import Counter
        if len(s) < len(p):
            return []
        p_count = Counter(p)
        s_count = Counter(s[:len(p)])
        res = []
        if s_count == p_count:
            res.append(0)
        for i in range(len(p), len(s)):
            s_count[s[i]] += 1
            left_char = s[i - len(p)]
            s_count[left_char] -= 1
            if s_count[left_char] == 0:
                del s_count[left_char]
            if s_count == p_count:
                res.append(i - len(p) + 1)
        return res

class Solution:
    def parseTernary(self, expression: str) -> str:
        stack = []
        i = len(expression) - 1
        while i >= 0:
            if expression[i] == '?':
                first = stack.pop()
                second = stack.pop()
                stack.append(first if expression[i-1] == 'T' else second)
                i -= 2
            elif expression[i] != ':':
                stack.append(expression[i])
                i -= 1
            else:
                i -= 1
        return stack[0]

class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
        def count_steps(prefix, n):
            steps = 0
            first, last = prefix, prefix
            while first <= n:
                steps += min(n + 1, last + 1) - first
                first *= 10; last = last * 10 + 9
            return steps
        curr = 1; k -= 1
        while k > 0:
            steps = count_steps(curr, n)
            if steps <= k:
                k -= steps; curr += 1
            else:
                k -= 1; curr *= 10
        return curr

class Solution:
    def arrangeCoins(self, n: int) -> int:
        lo, hi = 1, n
        while lo <= hi:
            mid = (lo + hi) // 2
            if mid * (mid + 1) // 2 <= n:
                lo = mid + 1
            else:
                hi = mid - 1
        return hi

class Solution:
    def findDuplicates(self, nums: List[int]) -> List[int]:
        res = []
        for num in nums:
            idx = abs(num) - 1
            if nums[idx] < 0:
                res.append(abs(num))
            else:
                nums[idx] = -nums[idx]
        return res

class Solution:
    def compress(self, chars: list[str]) -> int:
        write = read = 0
        while read < len(chars):
            ch = chars[read]
            count = 0
            while read < len(chars) and chars[read] == ch:
                read += 1; count += 1
            chars[write] = ch; write += 1
            if count > 1:
                for d in str(count):
                    chars[write] = d; write += 1
        return write

class Solution:
    def sequenceReconstruction(self, org: list[int], sequences: list[list[int]]) -> bool:
        from collections import defaultdict, deque
        n = len(org)
        graph = defaultdict(set)
        indeg = [0] * (n + 1)
        nodes = set()
        for seq in sequences:
            nodes.update(seq)
            for i in range(len(seq)-1):
                if seq[i+1] not in graph[seq[i]]:
                    graph[seq[i]].add(seq[i+1])
                    indeg[seq[i+1]] += 1
        if nodes != set(range(1, n+1)): return False
        q = deque(i for i in range(1, n+1) if indeg[i] == 0)
        idx = 0
        while q:
            if len(q) > 1: return False
            node = q.popleft()
            if idx >= n or node != org[idx]: return False
            idx += 1
            for nb in graph[node]:
                indeg[nb] -= 1
                if indeg[nb] == 0: q.append(nb)
        return idx == n

class Solution:
    def addTwoNumbers(self, l1, l2):
        s1, s2 = [], []
        while l1: s1.append(l1.val); l1 = l1.next
        while l2: s2.append(l2.val); l2 = l2.next
        carry = 0; head = None
        while s1 or s2 or carry:
            total = carry
            if s1: total += s1.pop()
            if s2: total += s2.pop()
            carry, val = divmod(total, 10)
            node = ListNode(val)
            node.next = head; head = node
        return head

class Solution:
    def numberOfArithmeticSlices(self, nums: list[int]) -> int:
        from collections import defaultdict
        n = len(nums)
        dp = [defaultdict(int) for _ in range(n)]
        res = 0
        for i in range(n):
            for j in range(i):
                d = nums[i] - nums[j]
                res += dp[j][d]
                dp[i][d] += dp[j][d] + 1
        return res

class Solution:
    def numberOfBoomerangs(self, points: list[list[int]]) -> int:
        res = 0
        for i in range(len(points)):
            dist_count = {}
            for j in range(len(points)):
                if i == j: continue
                d = (points[i][0]-points[j][0])**2 + (points[i][1]-points[j][1])**2
                dist_count[d] = dist_count.get(d, 0) + 1
            for v in dist_count.values():
                res += v * (v - 1)
        return res

class Solution:
    def findDisappearedNumbers(self, nums: List[int]) -> List[int]:
        for num in nums:
            idx = abs(num) - 1
            nums[idx] = -abs(nums[idx])
        return [i + 1 for i, num in enumerate(nums) if num > 0]

class Codec:
    def serialize(self, root) -> str:
        vals = []
        def pre(node):
            if node:
                vals.append(str(node.val))
                pre(node.left); pre(node.right)
        pre(root)
        return ' '.join(vals)
    def deserialize(self, data: str):
        if not data: return None
        vals = iter(int(x) for x in data.split())
        def build(lo, hi):
            val = next(vals, None)
            if val is None or val < lo or val > hi:
                return None  # need to put back
            # Actually use queue approach
            pass
        # Simpler approach with queue
        from collections import deque
        q = deque(int(x) for x in data.split())
        def helper(lo, hi):
            if not q or q[0] < lo or q[0] > hi: return None
            val = q.popleft()
            node = TreeNode(val)
            node.left = helper(lo, val)
            node.right = helper(val, hi)
            return node
        return helper(float('-inf'), float('inf'))

class Solution:
    def deleteNode(self, root: Optional[TreeNode], key: int) -> Optional[TreeNode]:
        if not root:
            return None
        if key < root.val:
            root.left = self.deleteNode(root.left, key)
        elif key > root.val:
            root.right = self.deleteNode(root.right, key)
        else:
            if not root.left:
                return root.right
            if not root.right:
                return root.left
            # Find inorder successor
            succ = root.right
            while succ.left:
                succ = succ.left
            root.val = succ.val
            root.right = self.deleteNode(root.right, succ.val)
        return root

class Solution:
    def frequencySort(self, s: str) -> str:
        from collections import Counter
        return ''.join(c*f for c, f in Counter(s).most_common())

class Solution:
    def findMinArrowShots(self, points: list[list[int]]) -> int:
        points.sort(key=lambda x: x[1])
        arrows = 1; end = points[0][1]
        for s, e in points[1:]:
            if s > end:
                arrows += 1; end = e
        return arrows

class Solution:
    def minMoves(self, nums: list[int]) -> int:
