class Solution:
    def fourSumCount(self, nums1, nums2, nums3, nums4) -> int:
        from collections import Counter
        ab = Counter(a + b for a in nums1 for b in nums2)
        return sum(ab[-(c + d)] for c in nums3 for d in nums4)

class Solution:
    def findContentChildren(self, g: list[int], s: list[int]) -> int:
        g.sort(); s.sort()
        i = j = 0
        while i < len(g) and j < len(s):
            if s[j] >= g[i]: i += 1
            j += 1
        return i

class Solution:
    def find132pattern(self, nums: list[int]) -> bool:
        stack = []
        third = float('-inf')  # the '2' in 132
        for i in range(len(nums)-1, -1, -1):
            if nums[i] < third: return True
            while stack and stack[-1] < nums[i]:
                third = stack.pop()
            stack.append(nums[i])
        return False

class Solution:
    def circularArrayLoop(self, nums: list[int]) -> bool:
        n = len(nums)
        def nxt(i): return (i + nums[i]) % n
        for i in range(n):
            if nums[i] == 0: continue
            slow = fast = i
            while nums[nxt(slow)] * nums[i] > 0 and nums[nxt(nxt(fast))] * nums[i] > 0 and nums[nxt(fast)] * nums[i] > 0:
                slow = nxt(slow)
                fast = nxt(nxt(fast))
                if slow == fast:
                    if slow == nxt(slow): break
                    return True
            j = i
            while nums[j] * nums[i] > 0:
                tmp = nxt(j); nums[j] = 0; j = tmp
        return False

class Solution:
    def poorPigs(self, buckets: int, minutesToDie: int, minutesToTest: int) -> int:
        import math
        states = minutesToTest // minutesToDie + 1
        return math.ceil(math.log(buckets) / math.log(states))

class Solution:
    def repeatedSubstringPattern(self, s: str) -> bool:
