            parts = queryIP.split('.')
            if len(parts) != 4: return 'Neither'
            for p in parts:
                if not p or not p.isdigit() or (len(p)>1 and p[0]=='0') or int(p)>255:
                    return 'Neither'
            return 'IPv4'
        if ':' in queryIP:
            parts = queryIP.split(':')
            if len(parts) != 8: return 'Neither'
            for p in parts:
                if not p or len(p)>4 or not all(c in '0123456789abcdefABCDEF' for c in p):
                    return 'Neither'
            return 'IPv6'
        return 'Neither'

class Solution:
    def isConvex(self, points: list[list[int]]) -> bool:
        n = len(points)
        sign = 0
        for i in range(n):
            a, b, c = points[i], points[(i+1)%n], points[(i+2)%n]
            cross = (b[0]-a[0])*(c[1]-b[1]) - (b[1]-a[1])*(c[0]-b[0])
            if cross != 0:
                if sign == 0: sign = 1 if cross > 0 else -1
                elif (cross > 0 and sign < 0) or (cross < 0 and sign > 0):
                    return False
        return True

