class Solution:
    def encode(self, s: str) -> str:
        n = len(s)
        dp = [[''] * n for _ in range(n)]
        for l in range(1, n+1):
            for i in range(n-l+1):
                j = i + l - 1
                sub = s[i:j+1]
                dp[i][j] = sub
                if l <= 4: continue
                for k in range(i, j):
                    cand = dp[i][k] + dp[k+1][j]
                    if len(cand) < len(dp[i][j]):
                        dp[i][j] = cand
                for k in range(1, l+1):
                    if l % k == 0 and sub[:k] * (l//k) == sub:
                        cand = f'{l//k}[{dp[i][i+k-1]}]'
                        if len(cand) < len(dp[i][j]):
                            dp[i][j] = cand
        return dp[0][n-1]

class Solution:
    def findAllConcatenatedWordsInADict(self, words: list[str]) -> list[str]:
        word_set = set(words)
        def canForm(word):
            dp = [False] * (len(word)+1)
            dp[0] = True
            for i in range(1, len(word)+1):
                for j in range(i):
                    if dp[j] and word[j:i] in word_set and word[j:i] != word:
                        dp[i] = True; break
            return dp[len(word)]
        return [w for w in words if w and canForm(w)]

class Solution:
    def makesquare(self, matchsticks: list[int]) -> bool:
        total = sum(matchsticks)
        if total % 4 != 0: return False
        side = total // 4
        matchsticks.sort(reverse=True)
        sides = [0] * 4
        def bt(idx):
            if idx == len(matchsticks): return all(s == side for s in sides)
            for i in range(4):
                if sides[i] + matchsticks[idx] <= side:
                    sides[i] += matchsticks[idx]
                    if bt(idx+1): return True
                    sides[i] -= matchsticks[idx]
                if sides[i] == 0: break
            return False
        return bt(0)

class Solution:
    def findMaxForm(self, strs: list[str], m: int, n: int) -> int:
        dp = [[0]*(n+1) for _ in range(m+1)]
        for s in strs:
            zeros = s.count('0'); ones = s.count('1')
            for i in range(m, zeros-1, -1):
                for j in range(n, ones-1, -1):
                    dp[i][j] = max(dp[i][j], dp[i-zeros][j-ones]+1)
        return dp[m][n]

