class Solution:
    def findRotateSteps(self, ring: str, key: str) -> int:
        from functools import lru_cache
        n = len(ring)
        @lru_cache(maxsize=None)
        def dp(ki, ri):
            if ki == len(key): return 0
            res = float('inf')
            for j in range(n):
                if ring[j] == key[ki]:
                    diff = abs(ri - j)
                    step = min(diff, n - diff)
                    res = min(res, step + 1 + dp(ki+1, j))
            return res
        return dp(0, 0)

class Solution:
    def largestValues(self, root) -> list[int]:
        if not root: return []
        from collections import deque
        q = deque([root])
        res = []
        while q:
            max_val = float('-inf')
            for _ in range(len(q)):
                node = q.popleft()
                max_val = max(max_val, node.val)
                if node.left: q.append(node.left)
                if node.right: q.append(node.right)
            res.append(max_val)
        return res

class Solution:
