class Solution:
    def __init__(self, m: int, n: int):
        self.m, self.n = m, n
        self.total = m * n
        self.map = {}
    def flip(self) -> list[int]:
        import random
        self.total -= 1
        r = random.randint(0, self.total)
        val = self.map.get(r, r)
        self.map[r] = self.map.get(self.total, self.total)
        return [val // self.n, val % self.n]
    def reset(self) -> None:
        self.total = self.m * self.n
        self.map = {}

