class Solution:
    def findLUSlength(self, strs: list[str]) -> int:
        def is_sub(s, t):
            i = 0
            for c in t:
                if i < len(s) and s[i] == c: i += 1
            return i == len(s)
        strs.sort(key=len, reverse=True)
        for i, s in enumerate(strs):
            if all(not is_sub(s, strs[j]) for j in range(len(strs)) if i != j):
                return len(s)
        return -1

class Solution:
    def checkSubarraySum(self, nums: list[int], k: int) -> bool:
        mod_map = {0: -1}
        prefix_mod = 0
        for i, n in enumerate(nums):
            prefix_mod = (prefix_mod + n) % k
            if prefix_mod in mod_map:
                if i - mod_map[prefix_mod] >= 2: return True
            else:
                mod_map[prefix_mod] = i
        return False

class Solution:
    def findLongestWord(self, s: str, dictionary: list[str]) -> str:
        def is_sub(word):
            i = 0
            for c in s:
                if i < len(word) and c == word[i]: i += 1
            return i == len(word)
        res = ''
        for w in dictionary:
            if is_sub(w):
                if len(w) > len(res) or (len(w) == len(res) and w < res):
                    res = w
        return res

class Solution:
    def findMaxLength(self, nums: List[int]) -> int:
        count = 0
        max_len = 0
        first_seen = {0: -1}
        for i, num in enumerate(nums):
            count += 1 if num == 1 else -1
            if count in first_seen:
                max_len = max(max_len, i - first_seen[count])
            else:
                first_seen[count] = i
        return max_len

class Solution:
    def countArrangement(self, n: int) -> int:
        self.count = 0
        visited = [False] * (n + 1)
        def bt(pos):
            if pos > n:
                self.count += 1
                return
            for num in range(1, n+1):
                if not visited[num] and (num % pos == 0 or pos % num == 0):
                    visited[num] = True
                    bt(pos + 1)
                    visited[num] = False
        bt(1)
        return self.count

class Solution:
    def wordsAbbreviation(self, words: list[str]) -> list[str]:
        def abbr(word, k):
            if k + 2 >= len(word): return word
            return word[:k+1] + str(len(word)-k-2) + word[-1]
        n = len(words)
        prefix = [0] * n
        res = [abbr(words[i], 0) for i in range(n)]
        while True:
            groups = {}
            for i in range(n):
                groups.setdefault(res[i], []).append(i)
            changed = False
            for key, indices in groups.items():
                if len(indices) <= 1: continue
                changed = True
                for i in indices:
                    prefix[i] += 1
                    res[i] = abbr(words[i], prefix[i])
            if not changed: break
        return res

class Solution:
    def __init__(self, w: list[int]):
