        import random, bisect
        r = random.randint(1, self.total)
        return bisect.bisect_left(self.prefix, r)

class Solution:
    def updateBoard(self, board, click) -> list[list[str]]:
        r, c = click
        if board[r][c] == 'M':
            board[r][c] = 'X'
            return board
        m, n = len(board), len(board[0])
        def dfs(i, j):
            mines = 0
            for di in [-1,0,1]:
                for dj in [-1,0,1]:
                    ni, nj = i+di, j+dj
                    if 0<=ni<m and 0<=nj<n and board[ni][nj]=='M':
                        mines += 1
            if mines:
                board[i][j] = str(mines)
            else:
                board[i][j] = 'B'
                for di in [-1,0,1]:
                    for dj in [-1,0,1]:
                        ni, nj = i+di, j+dj
                        if 0<=ni<m and 0<=nj<n and board[ni][nj]=='E':
                            dfs(ni, nj)
        dfs(r, c)
        return board

class Solution:
    def getMinimumDifference(self, root) -> int:
        self.prev = None
        self.min_diff = float('inf')
        def inorder(node):
            if not node: return
            inorder(node.left)
            if self.prev is not None:
                self.min_diff = min(self.min_diff, node.val - self.prev)
            self.prev = node.val
            inorder(node.right)
        inorder(root)
        return self.min_diff

