class Solution:
    def str2tree(self, s: str):
        if not s: return None
        self.i = 0
        def build():
            start = self.i
            if s[self.i] == '-': self.i += 1
            while self.i < len(s) and s[self.i].isdigit(): self.i += 1
            node = TreeNode(int(s[start:self.i]))
            if self.i < len(s) and s[self.i] == '(':
                self.i += 1
                node.left = build()
                self.i += 1  # skip ')'
            if self.i < len(s) and s[self.i] == '(':
                self.i += 1
                node.right = build()
                self.i += 1  # skip ')'
            return node
        return build()

