class Solution:
    def intersect(self, q1, q2):
        if q1.isLeaf: return q1 if q1.val else q2
        if q2.isLeaf: return q2 if q2.val else q1
        tl=self.intersect(q1.topLeft,q2.topLeft)
        tr=self.intersect(q1.topRight,q2.topRight)
        bl=self.intersect(q1.bottomLeft,q2.bottomLeft)
        br=self.intersect(q1.bottomRight,q2.bottomRight)
        if all(c.isLeaf and c.val for c in [tl,tr,bl,br]):
            return Node(True,True)
        n=Node(False,False)
        n.topLeft,n.topRight,n.bottomLeft,n.bottomRight=tl,tr,bl,br
        return n

