class Solution:
    def nearestPalindromic(self, n: str) -> str:
        l = len(n)
        cands = set([10**l+1, 10**(l-1)-1])
        prefix = int(n[:(l+1)//2])
        for d in [-1,0,1]:
            p = str(prefix+d)
            if l%2: cand=p+p[:-1][::-1]
            else: cand=p+p[::-1]
            cands.add(int(cand))
        cands.discard(int(n))
        return str(min(cands, key=lambda x:(abs(x-int(n)),x)))

