class Solution:
    def findPaths(self, m, n, maxMove, startRow, startColumn) -> int:
        MOD=10**9+7
        dp=[[0]*n for _ in range(m)]
        dp[startRow][startColumn]=1
        ans=0
        for _ in range(maxMove):
            nd=[[0]*n for _ in range(m)]
            for i in range(m):
                for j in range(n):
                    if not dp[i][j]: continue
                    for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ni,nj=i+di,j+dj
                        if 0<=ni<m and 0<=nj<n: nd[ni][nj]=(nd[ni][nj]+dp[i][j])%MOD
                        else: ans=(ans+dp[i][j])%MOD
            dp=nd
        return ans

class Solution:
    def findUnsortedSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        max_val, min_val = float('-inf'), float('inf')
        left, right = -1, -1
        for i in range(n):
            if nums[i] < max_val:
                right = i
            max_val = max(max_val, nums[i])
        for i in range(n-1, -1, -1):
            if nums[i] > min_val:
                left = i
            min_val = min(min_val, nums[i])
        return right - left + 1 if right != -1 else 0

class Solution:
    def killProcess(self, pid, ppid, kill):
        from collections import defaultdict, deque
        ch = defaultdict(list)
        for c,p in zip(pid,ppid): ch[p].append(c)
        res,q = [],[kill]
        while q:
            n = q.pop()
            res.append(n)
            q.extend(ch[n])
        return res

class Solution:
