            s += nums[i] - nums[i-k]
            mx = max(mx, s)
        return mx / k

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        lo, hi = min(nums), max(nums)
        while hi - lo > 1e-5:
            mid = (lo+hi)/2
            s = mn = 0
            prev = 0
            found = False
            for i in range(len(nums)):
                s += nums[i] - mid
                if i >= k-1:
                    if i >= k: prev += nums[i-k]-mid; mn = min(mn, prev)
                    if s - mn >= 0: found = True; break
            if found: lo = mid
            else: hi = mid
        return lo

