class MapSum:
    def __init__(self):
        self.map = {}
        self.trie = {}
    def insert(self, key: str, val: int) -> None:
        delta = val - self.map.get(key, 0)
        self.map[key] = val
        node = self.trie
        for c in key:
            node = node.setdefault(c, {'#':0})
            node['#'] += delta
    def sum(self, prefix: str) -> int:
        node = self.trie
        for c in prefix:
            if c not in node: return 0
            node = node[c]
        return node['#']

class Solution:
