            if c == '(':
                lo += 1; hi += 1
            elif c == ')':
                lo -= 1; hi -= 1
            else:
                lo -= 1; hi += 1
            if hi < 0: return False
            lo = max(lo, 0)
        return lo == 0

class Solution:
    def judgePoint24(self, cards: List[int]) -> bool:
        if len(cards) == 1:
            return abs(cards[0] - 24) < 1e-6
        for i in range(len(cards)):
            for j in range(len(cards)):
                if i == j: continue
                rest = [cards[k] for k in range(len(cards)) if k!=i and k!=j]
                for op in range(4):
                    if op == 0: rest.append(cards[i]+cards[j])
                    elif op == 1: rest.append(cards[i]-cards[j])
                    elif op == 2: rest.append(cards[i]*cards[j])
                    else:
                        if cards[j] == 0: continue
                        rest.append(cards[i]/cards[j])
                    if self.judgePoint24(rest): return True
                    rest.pop()
        return False

class Solution:
    def validPalindrome(self, s: str) -> bool:
        def isPalin(l, r):
            while l < r:
                if s[l] != s[r]: return False
                l += 1; r -= 1
            return True
        l, r = 0, len(s)-1
        while l < r:
            if s[l] != s[r]:
                return isPalin(l+1, r) or isPalin(l, r-1)
            l += 1; r -= 1
        return True

class Solution:
    def nextClosestTime(self, time: str) -> str:
        digits = {time[0], time[1], time[3], time[4]}
        cur = int(time[:2]) * 60 + int(time[3:])
        for i in range(1, 1441):
            nxt = (cur + i) % 1440
            h, m = nxt // 60, nxt % 60
            t = f'{h:02d}{m:02d}'
            if all(c in digits for c in t):
                return t[:2] + ':' + t[2:]

