class Solution:
    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        parent = list(range(len(edges) + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for u, v in edges:
            pu, pv = find(u), find(v)
            if pu == pv:
                return [u, v]
            parent[pu] = pv

class Solution:
    def findRedundantDirectedConnection(self, edges: List[List[int]]) -> List[int]:
        n = len(edges)
        parent = [0]*(n+1)
        cand1 = cand2 = None
        for u, v in edges:
            if parent[v]:
                cand1 = [parent[v], v]
                cand2 = [u, v]
                break
            parent[v] = u
        root = list(range(n+1))
        def find(x):
            while root[x] != x:
                root[x] = root[root[x]]
                x = root[x]
            return x
        for u, v in edges:
            if [u,v] == cand2: continue
            pu, pv = find(u), find(v)
            if pu == pv:
                return cand1 if cand1 else [u,v]
            root[pu] = pv
        return cand2

