        self.ans = 0
        def dfs(node):
            if not node: return 0
            l, r = dfs(node.left), dfs(node.right)
            al = l+1 if node.left and node.left.val == node.val else 0
            ar = r+1 if node.right and node.right.val == node.val else 0
            self.ans = max(self.ans, al+ar)
            return max(al, ar)
        dfs(root)
        return self.ans

class Solution:
    def knightProbability(self, n: int, k: int, row: int, column: int) -> float:
        dp = [[0]*n for _ in range(n)]
        dp[row][column] = 1
        dirs = [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]
        for _ in range(k):
            ndp = [[0]*n for _ in range(n)]
            for r in range(n):
                for c in range(n):
                    if dp[r][c] > 0:
                        for dr, dc in dirs:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<n and 0<=nc<n:
                                ndp[nr][nc] += dp[r][c]/8
            dp = ndp
        return sum(dp[r][c] for r in range(n) for c in range(n))

