        maxH = 0
        for left, size in positions:
            right = left + size
            h = size
            for l2, r2, h2 in intervals:
                if l2 < right and left < r2:
                    h = max(h, h2 + size)
            intervals.append((left, right, h))
            maxH = max(maxH, h)
            ans.append(maxH)
        return ans

