class Solution:
    def numDistinctIslands2(self, grid) -> int:
        from collections import deque
        m,n=len(grid),len(grid[0])
        def bfs(i,j):
            q=deque([(i,j)]); grid[i][j]=0; cells=[(i,j)]
            while q:
                r,c=q.popleft()
                for nr,nc in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                    if 0<=nr<m and 0<=nc<n and grid[nr][nc]:
                        grid[nr][nc]=0; q.append((nr,nc)); cells.append((nr,nc))
            return cells
        def normalize(cells):
            shapes=[]
            for fn in [lambda r,c:(r,c),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(-r,-c),lambda r,c:(c,r),lambda r,c:(c,-r),lambda r,c:(-c,r),lambda r,c:(-c,-r)]:
                t=sorted(fn(r,c) for r,c in cells)
                t=[(r-t[0][0],c-t[0][1]) for r,c in t]
                shapes.append(tuple(t))
            return min(shapes)
        seen=set()
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    cells=bfs(i,j)
                    seen.add(normalize(cells))
        return len(seen)

class Solution:
    def minimumDeleteSum(self, s1, s2):
        m, n = len(s1), len(s2)
        dp = [[0]*(n+1) for _ in range(m+1)]
        for i in range(1, m+1): dp[i][0] = dp[i-1][0] + ord(s1[i-1])
        for j in range(1, n+1): dp[0][j] = dp[0][j-1] + ord(s2[j-1])
        for i in range(1, m+1):
            for j in range(1, n+1):
                if s1[i-1] == s2[j-1]: dp[i][j] = dp[i-1][j-1]
                else: dp[i][j] = min(dp[i-1][j]+ord(s1[i-1]), dp[i][j-1]+ord(s2[j-1]))
        return dp[m][n]

class Solution:
    def numSubarrayProductLessThanK(self, nums: List[int], k: int) -> int:
        if k <= 1:
            return 0
        prod = 1
        left = count = 0
        for right in range(len(nums)):
            prod *= nums[right]
            while prod >= k:
                prod //= nums[left]
                left += 1
            count += right - left + 1
        return count

