class RangeModule:
    def __init__(self):
        self.intervals = []
    def addRange(self, left, right):
        new = []
        placed = False
        for l, r in self.intervals:
            if r < left: new.append((l,r))
            elif l > right:
                if not placed: new.append((left,right)); placed=True
                new.append((l,r))
            else:
                left, right = min(left,l), max(right,r)
        if not placed: new.append((left,right))
        self.intervals = new
    def queryRange(self, left, right):
        for l, r in self.intervals:
            if l <= left and r >= right: return True
        return False
    def removeRange(self, left, right):
        new = []
        for l, r in self.intervals:
            if r <= left or l >= right: new.append((l,r))
            else:
                if l < left: new.append((l,left))
                if r > right: new.append((right,r))
        self.intervals = new

