class MaxStack:
    def __init__(self):
        self.stack = []
        self.sl = SortedList()
        self.id = 0
        self.removed = set()
    def push(self, x):
        self.stack.append((x, self.id))
        self.sl.add((x, self.id))
        self.id += 1
    def pop(self):
        while self.stack[-1][1] in self.removed: self.stack.pop()
        x, i = self.stack.pop()
        self.sl.remove((x, i))
        return x
    def top(self):
        while self.stack[-1][1] in self.removed: self.stack.pop()
        return self.stack[-1][0]
    def peekMax(self):
        while self.sl[-1][1] in self.removed: self.sl.pop()
        return self.sl[-1][0]
    def popMax(self):
        while self.sl[-1][1] in self.removed: self.sl.pop()
        x, i = self.sl.pop()
        self.removed.add(i)
        return x

