class Solution:
    def candyCrush(self, board):
        R, C = len(board), len(board[0])
        while True:
            crush = set()
            for r in range(R):
                for c in range(C-2):
                    if board[r][c] and board[r][c]==board[r][c+1]==board[r][c+2]:
                        crush |= {(r,c),(r,c+1),(r,c+2)}
            for r in range(R-2):
                for c in range(C):
                    if board[r][c] and board[r][c]==board[r+1][c]==board[r+2][c]:
                        crush |= {(r,c),(r+1,c),(r+2,c)}
            if not crush: return board
            for r,c in crush: board[r][c] = 0
            for c in range(C):
                idx = R-1
                for r in range(R-1,-1,-1):
                    if board[r][c]:
                        board[idx][c] = board[r][c]
                        if idx != r: board[r][c] = 0
                        idx -= 1
                for r in range(idx,-1,-1): board[r][c] = 0

