        n, cur = 0, head
        while cur: n += 1; cur = cur.next
        width, rem = divmod(n, k)
        res, cur = [], head
        for i in range(k):
            res.append(cur)
            size = width + (1 if i < rem else 0)
            for _ in range(size - 1):
                if cur: cur = cur.next
            if cur:
                nxt = cur.next
                cur.next = None
                cur = nxt
        return res

class Solution:
    def countOfAtoms(self, formula):
        from collections import defaultdict
        stack = [defaultdict(int)]
        i, n = 0, len(formula)
        while i < n:
            if formula[i] == '(':
                stack.append(defaultdict(int))
                i += 1
            elif formula[i] == ')':
                i += 1
                j = i
                while i < n and formula[i].isdigit(): i += 1
                mult = int(formula[j:i] or 1)
                top = stack.pop()
                for k, v in top.items(): stack[-1][k] += v * mult
            else:
                j = i; i += 1
                while i < n and formula[i].islower(): i += 1
                name = formula[j:i]; j = i
                while i < n and formula[i].isdigit(): i += 1
                stack[-1][name] += int(formula[j:i] or 1)
        return ''.join(k + (str(v) if v > 1 else '') for k, v in sorted(stack[-1].items()))

class Solution:
    def minWindow(self, s1, s2):
        m, n = len(s1), len(s2)
        dp = [[-1]*n for _ in range(m)]
        for i in range(m):
            if s1[i] == s2[0]: dp[i][0] = i
            elif i > 0: dp[i][0] = dp[i-1][0]
        for j in range(1, n):
            for i in range(1, m):
                if s1[i] == s2[j]: dp[i][j] = dp[i-1][j-1]
                else: dp[i][j] = dp[i-1][j]
        start, length = -1, m+1
        for i in range(m):
            if dp[i][n-1] >= 0:
                l = i - dp[i][n-1] + 1
                if l < length: length = l; start = dp[i][n-1]
        return '' if start == -1 else s1[start:start+length]

