        if len(s1) != len(s2): return False
        parent = {}
        def find(x):
            parent.setdefault(x, x)
            while parent[x] != x: parent[x] = parent[parent[x]]; x = parent[x]
            return x
        for a, b in pairs: parent[find(a)] = find(b)
        return all(a==b or find(a)==find(b) for a,b in zip(s1,s2))

