class Solution:
    def cherryPickup(self, grid):
        n = len(grid)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(r1, c1, r2):
            c2 = r1+c1-r2
            if r1>=n or c1>=n or r2>=n or c2>=n: return -1
            if grid[r1][c1]==-1 or grid[r2][c2]==-1: return -1
            if r1==n-1 and c1==n-1: return grid[r1][c1]
            val = grid[r1][c1] + (grid[r2][c2] if (r1,c1)!=(r2,c2) else 0)
            best = max(dp(r1+1,c1,r2+1),dp(r1+1,c1,r2),dp(r1,c1+1,r2+1),dp(r1,c1+1,r2))
            return -1 if best==-1 else val+best
        return max(0, dp(0,0,0))

class Solution:
    def findClosestLeaf(self, root, k):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        leaves = set()
        def build(node, par):
            if not node: return
            if not node.left and not node.right: leaves.add(node.val)
            if par:
                graph[node.val].append(par.val)
                graph[par.val].append(node.val)
            build(node.left, node); build(node.right, node)
        build(root, None)
        q, seen = deque([k]), {k}
        while q:
            cur = q.popleft()
            if cur in leaves: return cur
            for nb in graph[cur]:
                if nb not in seen: seen.add(nb); q.append(nb)
        return k

