class Solution:
    def containVirus(self, isInfected):
        R, C = len(isInfected), len(isInfected[0])
        walls = 0
        while True:
            regions, fronts, perimeters = [], [], []
            visited = [[False]*C for _ in range(R)]
            for r in range(R):
                for c in range(C):
                    if isInfected[r][c]==1 and not visited[r][c]:
                        region, front, peri = [], set(), 0
                        q = [(r,c)]; visited[r][c] = True
                        while q:
                            x, y = q.pop()
                            region.append((x,y))
                            for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                                nx,ny = x+dx, y+dy
                                if 0<=nx<R and 0<=ny<C:
                                    if isInfected[nx][ny]==1 and not visited[nx][ny]:
                                        visited[nx][ny]=True; q.append((nx,ny))
                                    elif isInfected[nx][ny]==0:
                                        front.add((nx,ny)); peri += 1
                        regions.append(region); fronts.append(front); perimeters.append(peri)
            if not regions: break
            if all(len(f)==0 for f in fronts): break
            idx = max(range(len(fronts)), key=lambda i: len(fronts[i]))
            walls += perimeters[idx]
            for x,y in regions[idx]: isInfected[x][y] = 2
            for i in range(len(regions)):
                if i != idx:
                    for x,y in fronts[i]: isInfected[x][y] = 1
        return walls

