class Solution:
    def ipToCIDR(self, ip, n):
        def ip2int(ip):
            parts = list(map(int, ip.split('.')))
            return (parts[0]<<24)+(parts[1]<<16)+(parts[2]<<8)+parts[3]
        def int2ip(x):
            return f'{(x>>24)&255}.{(x>>16)&255}.{(x>>8)&255}.{x&255}'
        start = ip2int(ip)
        res = []
        while n > 0:
            lowbit = start & (-start) if start else (1<<32)
            while lowbit > n: lowbit >>= 1
            mask = 32 - lowbit.bit_length() + 1
            res.append(f'{int2ip(start)}/{mask}')
            start += lowbit; n -= lowbit
        return res

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        from collections import deque
        dead = set(deadends)
        if '0000' in dead:
            return -1
        queue = deque([('0000', 0)])
        visited = {'0000'}
        while queue:
            state, steps = queue.popleft()
            if state == target:
                return steps
            for i in range(4):
                d = int(state[i])
                for delta in (-1, 1):
                    nd = (d + delta) % 10
                    new_state = state[:i] + str(nd) + state[i+1:]
                    if new_state not in visited and new_state not in dead:
                        visited.add(new_state)
                        queue.append((new_state, steps + 1))
        return -1

