        return ''.join(res)

class Solution:
    def numMatchingSubseq(self, s: str, words: List[str]) -> int:
        from collections import defaultdict
        buckets = defaultdict(list)
        for w in words:
            buckets[w[0]].append(iter(w[1:]))
        count = 0
        for c in s:
            old = buckets[c]
            buckets[c] = []
            for it in old:
                nxt = next(it, None)
                if nxt is None: count += 1
                else: buckets[nxt].append(it)
        return count

class Solution:
    def preimageSizeFZF(self, k: int) -> int:
        def zeros(n):
            count = 0
            while n:
                n //= 5
                count += n
            return count
        def lower(target):
            lo, hi = 0, 5 * target + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if zeros(mid) >= target: hi = mid
                else: lo = mid + 1
            return lo
        return lower(k + 1) - lower(k)

class Solution:
    def numSubarrayBoundedMax(self, nums: List[int], left: int, right: int) -> int:
        def count(bound):
            ans = cur = 0
            for x in nums:
                cur = cur + 1 if x <= bound else 0
                ans += cur
            return ans
        return count(right) - count(left - 1)

