class Solution:
    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:
        res = []
        n = len(graph)
        def dfs(node, path):
            if node == n - 1:
                res.append(path[:])
                return
            for nei in graph[node]:
                path.append(nei)
                dfs(nei, path)
                path.pop()
        dfs(0, [0])
        return res

class Solution:
    def bestRotation(self, nums: List[int]) -> int:
        n = len(nums)
        change = [0] * (n + 1)
        for i in range(n):
            low = (i + 1) % n
            high = (i - nums[i] + n) % n
            change[low] += 1
            change[(high + 1) % n] -= 1
            if low > high:
                change[0] += 1
        best = -1
        bestK = 0
        cur = 0
        for k in range(n):
            cur += change[k]
            if cur > best:
                best = cur
                bestK = k
        return bestK

class Solution:
    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:
        dp = [poured] + [0] * query_row
        for row in range(1, query_row + 1):
            ndp = [0] * (row + 1)
            for i in range(row):
                overflow = max(0, dp[i] - 1)
                ndp[i] += overflow / 2
                ndp[i+1] += overflow / 2
            dp = ndp
        return min(1.0, dp[query_glass])

class Solution:
    def similarRGB(self, color: str) -> str:
