class Solution:
    def soupServings(self, n: int) -> float:
        if n > 4800: return 1.0
        import math
        n = math.ceil(n / 25)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(a, b):
            if a <= 0 and b <= 0: return 0.5
            if a <= 0: return 1.0
            if b <= 0: return 0.0
            return 0.25 * (dp(a-4,b) + dp(a-3,b-1) + dp(a-2,b-2) + dp(a-1,b-3))
        return dp(n, n)

class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        def groups(w):
            res = []
            i = 0
            while i < len(w):
                j = i
                while j < len(w) and w[j] == w[i]: j += 1
                res.append((w[i], j - i))
                i = j
            return res
        sg = groups(s)
        count = 0
        for w in words:
            wg = groups(w)
            if len(sg) != len(wg): continue
            valid = True
            for (c1, n1), (c2, n2) in zip(sg, wg):
                if c1 != c2 or n1 < n2 or (n1 != n2 and n1 < 3):
                    valid = False
                    break
            if valid: count += 1
        return count

class Solution:
    def xorGame(self, nums: List[int]) -> bool:
