class Solution:
    def largestTriangleArea(self, points: List[List[int]]) -> float:
        res = 0
        for i in range(len(points)):
            for j in range(i+1, len(points)):
                for k in range(j+1, len(points)):
                    x1,y1 = points[i]
                    x2,y2 = points[j]
                    x3,y3 = points[k]
                    area = abs(x1*(y2-y3)+x2*(y3-y1)+x3*(y1-y2))/2
                    res = max(res, area)
        return res

class Solution:
    def largestSumOfAverages(self, nums: List[int], k: int) -> float:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n): prefix[i+1] = prefix[i] + nums[i]
        dp = [prefix[i+1]/(i+1) for i in range(n)]  # k=1
        for _ in range(k - 1):
            ndp = [0.0] * n
            for i in range(n):
                for j in range(i):
                    ndp[i] = max(ndp[i], dp[j] + (prefix[i+1]-prefix[j+1])/(i-j))
            dp = ndp
        return dp[n-1]

class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target: return 0
        from collections import defaultdict, deque
        stop2routes = defaultdict(set)
        for i, route in enumerate(routes):
            for stop in route:
                stop2routes[stop].add(i)
        visited_routes = set()
        visited_stops = {source}
        queue = deque([source])
        level = 0
        while queue:
            level += 1
            for _ in range(len(queue)):
                stop = queue.popleft()
                for route_id in stop2routes[stop]:
                    if route_id in visited_routes: continue
                    visited_routes.add(route_id)
                    for next_stop in routes[route_id]:
                        if next_stop == target: return level
                        if next_stop not in visited_stops:
                            visited_stops.add(next_stop)
                            queue.append(next_stop)
        return -1

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        s = s[1:-1]
        def valid(part):
            res = []
            for i in range(1, len(part)+1):
                left, right = part[:i], part[i:]
                if (left == '0' or not left.startswith('0')) and not right.endswith('0'):
                    res.append(left + ('.' if right else '') + right)
            return res
        ans = []
        for i in range(1, len(s)):
            for x in valid(s[:i]):
                for y in valid(s[i:]):
                    ans.append(f'({x}, {y})')
        return ans

class Solution:
    def numComponents(self, head: Optional[ListNode], nums: List[int]) -> int:
        s = set(nums)
        count = 0
        while head:
            if head.val in s and (not head.next or head.next.val not in s):
                count += 1
            head = head.next
        return count

class Solution:
    def racecar(self, target: int) -> int:
        dp = [0] * (target + 1)
        for t in range(1, target + 1):
            k = t.bit_length()
            if t == (1 << k) - 1:
                dp[t] = k
                continue
            dp[t] = k + 1 + dp[(1 << k) - 1 - t]
            for j in range(k - 1):
                dp[t] = min(dp[t], k - 1 + 1 + j + 1 + dp[t - (1<<(k-1)) + (1<<j)])
        return dp[target]

class Solution:
    def minimumLengthEncoding(self, words: List[str]) -> int:
        good = set(words)
        for w in words:
            for k in range(1, len(w)):
                good.discard(w[k:])
        return sum(len(w) + 1 for w in good)

class Solution:
    def shortestToChar(self, s: str, c: str) -> List[int]:
        n = len(s)
        res = [float('inf')] * n
        pos = -float('inf')
        for i in range(n):
            if s[i] == c: pos = i
            res[i] = i - pos
        pos = float('inf')
        for i in range(n-1, -1, -1):
            if s[i] == c: pos = i
            res[i] = min(res[i], pos - i)
        return res

class Solution:
    def flipgame(self, fronts: List[int], backs: List[int]) -> int:
        bad = {f for f, b in zip(fronts, backs) if f == b}
        ans = float('inf')
        for x in fronts + backs:
            if x not in bad:
                ans = min(ans, x)
        return ans if ans != float('inf') else 0

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}
        for i, x in enumerate(arr):
            dp[x] = 1
            for j in range(i):
                if x % arr[j] == 0 and x // arr[j] in dp:
                    dp[x] = (dp[x] + dp[arr[j]] * dp[x // arr[j]]) % MOD
        return sum(dp.values()) % MOD

class Solution:
    def toGoatLatin(self, sentence: str) -> str:
        vowels = set('aeiouAEIOU')
        words = sentence.split()
        res = []
        for i, w in enumerate(words):
            if w[0] in vowels:
                res.append(w + 'ma' + 'a'*(i+1))
            else:
                res.append(w[1:] + w[0] + 'ma' + 'a'*(i+1))
        return ' '.join(res)

class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        from collections import Counter
        cnt = Counter(ages)
        res = 0
        for a in cnt:
            for b in cnt:
                if b <= 0.5 * a + 7: continue
                if b > a: continue
                if b > 100 and a < 100: continue
                res += cnt[a] * cnt[b]
                if a == b: res -= cnt[a]
        return res

class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:
        jobs = sorted(zip(difficulty, profit))
        worker.sort()
        res = i = best = 0
        for w in worker:
            while i < len(jobs) and jobs[i][0] <= w:
                best = max(best, jobs[i][1])
                i += 1
            res += best
        return res

class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        n = len(grid)
        label = [[0]*n for _ in range(n)]
        area = {0: 0}
        idx = 0
        def dfs(r, c, idx):
            label[r][c] = idx
            cnt = 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<n and 0<=nc<n and grid[nr][nc]==1 and label[nr][nc]==0:
                    cnt += dfs(nr, nc, idx)
            return cnt
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1 and label[i][j] == 0:
                    idx += 1
                    area[idx] = dfs(i, j, idx)
        res = max(area.values()) if area else 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    seen = set()
                    total = 1
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ni, nj = i+dr, j+dc
                        if 0<=ni<n and 0<=nj<n and label[ni][nj] not in seen:
                            seen.add(label[ni][nj])
                            total += area.get(label[ni][nj], 0)
                    res = max(res, total)
        return res

class Solution:
    def uniqueLetterString(self, s: str) -> int:
        from collections import defaultdict
        index = defaultdict(lambda: [-1])
        for i, c in enumerate(s):
            index[c].append(i)
        for c in index:
            index[c].append(len(s))
        res = 0
        for c in index:
            arr = index[c]
            for i in range(1, len(arr) - 1):
                res += (arr[i] - arr[i-1]) * (arr[i+1] - arr[i])
        return res

class Solution:
    def consecutiveNumbersSum(self, n: int) -> int:
        count = 0
        k = 1
        while k * (k - 1) // 2 < n:
            if (n - k * (k - 1) // 2) % k == 0:
                count += 1
            k += 1
        return count

class Solution:
    def largeGroupPositions(self, s: str) -> List[List[int]]:
        res = []
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]: j += 1
            if j - i >= 3: res.append([i, j-1])
