class Solution:
    def findReplaceString(self, s: str, indices: List[int], sources: List[str], targets: List[str]) -> str:
        s = list(s)
        for i, src, tgt in sorted(zip(indices, sources, targets), reverse=True):
            if ''.join(s[i:i+len(src)]) == src:
                s[i:i+len(src)] = list(tgt)
