class Solution:
    def new21Game(self, n: int, k: int, maxPts: int) -> float:
        if k == 0 or n >= k + maxPts: return 1.0
        dp = [0.0] * (n + 1)
        dp[0] = 1.0
        wSum = 1.0
        for i in range(1, n + 1):
            dp[i] = wSum / maxPts
            if i < k: wSum += dp[i]
            if i >= maxPts: wSum -= dp[i - maxPts]
        return sum(dp[k:])

class Solution:
    def pushDominoes(self, dominoes: str) -> str:
        n = len(dominoes)
        forces = [0] * n
        f = 0
        for i in range(n):
            if dominoes[i] == 'R': f = n
            elif dominoes[i] == 'L': f = 0
            else: f = max(f - 1, 0)
            forces[i] += f
        f = 0
        for i in range(n-1, -1, -1):
            if dominoes[i] == 'L': f = n
            elif dominoes[i] == 'R': f = 0
            else: f = max(f - 1, 0)
            forces[i] -= f
        return ''.join('.' if x == 0 else ('R' if x > 0 else 'L') for x in forces)

class Solution:
    def numSimilarGroups(self, strs: List[str]) -> int:
        n = len(strs)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb: parent[ra] = rb
        def similar(a, b):
            diff = sum(1 for x, y in zip(a, b) if x != y)
            return diff <= 2
        for i in range(n):
            for j in range(i+1, n):
                if similar(strs[i], strs[j]):
                    union(i, j)
        return len(set(find(i) for i in range(n)))

class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        def magic(r, c):
            vals = [grid[r+i][c+j] for i in range(3) for j in range(3)]
            if sorted(vals) != list(range(1, 10)): return False
            for i in range(3):
                if sum(grid[r+i][c:c+3]) != 15: return False
                if sum(grid[r+j][c+i] for j in range(3)) != 15: return False
            if grid[r][c]+grid[r+1][c+1]+grid[r+2][c+2] != 15: return False
            if grid[r][c+2]+grid[r+1][c+1]+grid[r+2][c] != 15: return False
            return True
        m, n = len(grid), len(grid[0])
        return sum(magic(i,j) for i in range(m-2) for j in range(n-2))

class Solution:
    def canVisitAllRooms(self, rooms: List[List[int]]) -> bool:
        visited = set([0])
        stack = [0]
        while stack:
            room = stack.pop()
            for key in rooms[room]:
                if key not in visited:
                    visited.add(key)
                    stack.append(key)
        return len(visited) == len(rooms)

class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        def backtrack(idx, seq):
            if idx == len(num) and len(seq) >= 3:
                return True
            for i in range(idx, len(num)):
                if num[idx] == '0' and i > idx:
                    break
                val = int(num[idx:i+1])
                if val > 2**31 - 1:
                    break
                if len(seq) >= 2 and val > seq[-1] + seq[-2]:
                    break
                if len(seq) < 2 or val == seq[-1] + seq[-2]:
                    seq.append(val)
                    if backtrack(i+1, seq):
                        return True
                    seq.pop()
            return False
        res = []
        backtrack(0, res)
        return res

class Solution:
    def findSecretWord(self, words: List[str], master: 'Master') -> None:
        def match(a, b):
            return sum(x == y for x, y in zip(a, b))
        candidates = words[:]
        for _ in range(10):
            guess = candidates[0]
            res = master.guess(guess)
            if res == 6:
                return
            candidates = [w for w in candidates if match(w, guess) == res]

class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def get_next(s, i):
            skip = 0
            while i >= 0:
                if s[i] == '#':
                    skip += 1
                elif skip > 0:
                    skip -= 1
                else:
                    break
                i -= 1
            return i
        i, j = len(s)-1, len(t)-1
        while i >= 0 or j >= 0:
            i, j = get_next(s, i), get_next(t, j)
            if i >= 0 and j >= 0 and s[i] != t[j]:
                return False
            if (i >= 0) != (j >= 0):
                return False
            i -= 1
            j -= 1
        return True

class Solution:
    def longestMountain(self, arr: List[int]) -> int:
        n, res = len(arr), 0
        i = 1
        while i < n - 1:
            if arr[i-1] < arr[i] > arr[i+1]:
                l, r = i-1, i+1
                while l > 0 and arr[l-1] < arr[l]: l -= 1
                while r < n-1 and arr[r] > arr[r+1]: r += 1
                res = max(res, r - l + 1)
                i = r + 1
            else:
                i += 1
        return res

class Solution:
    def isNStraightHand(self, hand: List[int], groupSize: int) -> bool:
        if len(hand) % groupSize != 0:
            return False
        from collections import Counter
        count = Counter(hand)
        for card in sorted(count):
            if count[card] > 0:
                need = count[card]
                for i in range(card, card + groupSize):
                    if count[i] < need:
                        return False
                    count[i] -= need
        return True

class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        import collections
        n = len(graph)
        target = (1 << n) - 1
        queue = collections.deque()
        visited = set()
        for i in range(n):
            queue.append((i, 1 << i, 0))
            visited.add((i, 1 << i))
        while queue:
            node, mask, dist = queue.popleft()
            if mask == target:
                return dist
            for nei in graph[node]:
                new_mask = mask | (1 << nei)
                if (nei, new_mask) not in visited:
                    visited.add((nei, new_mask))
                    queue.append((nei, new_mask, dist + 1))
        return 0

class Solution:
    def shiftingLetters(self, s: str, shifts: List[int]) -> str:
        total = 0
        res = list(s)
        for i in range(len(s)-1, -1, -1):
            total += shifts[i]
            res[i] = chr((ord(res[i]) - ord('a') + total) % 26 + ord('a'))
        return ''.join(res)

class Solution:
    def maxDistToClosest(self, seats: List[int]) -> int:
        n, res, last = len(seats), 0, -1
        for i in range(n):
            if seats[i] == 1:
                res = max(res, i if last == -1 else (i - last) // 2)
                last = i
        return max(res, n - 1 - last)

class Solution:
    def rectangleArea(self, rectangles: List[List[int]]) -> int:
        MOD = 10**9 + 7
        xs = sorted(set(x for r in rectangles for x in [r[0], r[2]]))
        x_idx = {x: i for i, x in enumerate(xs)}
        events = []
        for x1, y1, x2, y2 in rectangles:
            events.append((y1, 0, x1, x2))
            events.append((y2, 1, x1, x2))
        events.sort()
        count = [0] * len(xs)
        ans, prev_y = 0, events[0][0]
        for y, typ, x1, x2 in events:
            width = sum(xs[i+1] - xs[i] for i in range(len(xs)-1) if count[i] > 0)
            ans += width * (y - prev_y)
            prev_y = y
            for i in range(x_idx[x1], x_idx[x2]):
                count[i] += 1 if typ == 0 else -1
        return ans % MOD

class Solution:
    def loudAndRich(self, richer: List[List[int]], quiet: List[int]) -> List[int]:
        n = len(quiet)
        graph = [[] for _ in range(n)]
        for a, b in richer:
            graph[b].append(a)
        ans = [-1] * n
        def dfs(node):
            if ans[node] != -1:
                return
            ans[node] = node
            for nei in graph[node]:
                dfs(nei)
                if quiet[ans[nei]] < quiet[ans[node]]:
                    ans[node] = ans[nei]
        for i in range(n):
            dfs(i)
        return ans

class Solution:
    def peakIndexInMountainArray(self, arr: List[int]) -> int:
        lo, hi = 0, len(arr) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < arr[mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        return lo

class Solution:
    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        cars = sorted(zip(position, speed), reverse=True)
        fleets, prev_time = 0, 0
        for pos, spd in cars:
            time = (target - pos) / spd
            if time > prev_time:
                fleets += 1
                prev_time = time
        return fleets

class Solution:
    def kSimilarity(self, s1: str, s2: str) -> int:
        from collections import deque
        if s1 == s2: return 0
        queue = deque([(s1, 0)])
        visited = {s1}
        while queue:
            curr, swaps = queue.popleft()
            i = 0
            while curr[i] == s2[i]: i += 1
            for j in range(i+1, len(curr)):
                if curr[j] == s2[i] and curr[j] != s2[j]:
                    nxt = list(curr)
                    nxt[i], nxt[j] = nxt[j], nxt[i]
                    nxt = ''.join(nxt)
                    if nxt == s2: return swaps + 1
                    if nxt not in visited:
                        visited.add(nxt)
                        queue.append((nxt, swaps + 1))
        return -1

class ExamRoom:
    def __init__(self, n: int):
        self.n = n
        self.seats = []
    def seat(self) -> int:
        if not self.seats:
            self.seats.append(0)
            return 0
        max_dist, best = self.seats[0], 0
        for i in range(1, len(self.seats)):
            dist = (self.seats[i] - self.seats[i-1]) // 2
            if dist > max_dist:
                max_dist = dist
                best = self.seats[i-1] + dist
        if self.n - 1 - self.seats[-1] > max_dist:
            best = self.n - 1
        import bisect
        bisect.insort(self.seats, best)
        return best
    def leave(self, p: int) -> None:
        self.seats.remove(p)

class Solution:
    def scoreOfParentheses(self, s: str) -> int:
        stack = [0]
        for c in s:
            if c == '(':
                stack.append(0)
            else:
                v = stack.pop()
                stack[-1] += max(2 * v, 1)
        return stack[0]

class Solution:
    def mincostToHireWorkers(self, quality: List[int], wage: List[int], k: int) -> float:
        import heapq
        workers = sorted((w/q, q) for w, q in zip(wage, quality))
        heap, total_q, ans = [], 0, float('inf')
        for ratio, q in workers:
            heapq.heappush(heap, -q)
            total_q += q
            if len(heap) > k:
                total_q += heapq.heappop(heap)
            if len(heap) == k:
                ans = min(ans, ratio * total_q)
        return ans

class Solution:
    def buddyStrings(self, s: str, goal: str) -> bool:
        if len(s) != len(goal): return False
        if s == goal: return len(set(s)) < len(s)
        diffs = [(a, b) for a, b in zip(s, goal) if a != b]
        return len(diffs) == 2 and diffs[0] == diffs[1][::-1]

class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        five = ten = 0
        for bill in bills:
            if bill == 5:
                five += 1
            elif bill == 10:
                if not five: return False
                five -= 1; ten += 1
            else:
                if ten and five:
                    ten -= 1; five -= 1
                elif five >= 3:
                    five -= 3
                else:
                    return False
        return True

class Solution:
    def matrixScore(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        for i in range(m):
            if grid[i][0] == 0:
                for j in range(n): grid[i][j] ^= 1
        for j in range(1, n):
            ones = sum(grid[i][j] for i in range(m))
            if ones < m - ones:
                for i in range(m): grid[i][j] ^= 1
        return sum(int(''.join(map(str, row)), 2) for row in grid)

class Solution:
    def shortestSubarray(self, nums: List[int], k: int) -> int:
        from collections import deque
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n): prefix[i+1] = prefix[i] + nums[i]
        dq = deque()
        ans = n + 1
        for i in range(n + 1):
            while dq and prefix[i] - prefix[dq[0]] >= k:
                ans = min(ans, i - dq.popleft())
            while dq and prefix[i] <= prefix[dq[-1]]:
                dq.pop()
            dq.append(i)
        return ans if ans <= n else -1

class Solution:
    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:
        import collections
        parent = {}
        def dfs(node, par):
            if node:
                parent[node] = par
                dfs(node.left, node)
                dfs(node.right, node)
        dfs(root, None)
        queue = collections.deque([(target, 0)])
        visited = {target}
        res = []
        while queue:
            node, dist = queue.popleft()
            if dist == k:
                res.append(node.val)
            elif dist < k:
                for nei in [node.left, node.right, parent[node]]:
                    if nei and nei not in visited:
                        visited.add(nei)
                        queue.append((nei, dist + 1))
        return res

class Solution:
    def shortestPathAllKeys(self, grid: List[str]) -> int:
        from collections import deque
        m, n = len(grid), len(grid[0])
        start = total = 0
        si = sj = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '@': si, sj = i, j
                elif grid[i][j].islower(): total += 1
        target = (1 << total) - 1
        queue = deque([(si, sj, 0, 0)])
        visited = {(si, sj, 0)}
        while queue:
            x, y, keys, steps = queue.popleft()
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '#':
                    c = grid[nx][ny]
                    nkeys = keys
                    if c.islower(): nkeys |= (1 << (ord(c)-ord('a')))
                    elif c.isupper() and not (keys & (1 << (ord(c)-ord('A')))): continue
                    if nkeys == target: return steps + 1
                    if (nx, ny, nkeys) not in visited:
                        visited.add((nx, ny, nkeys))
                        queue.append((nx, ny, nkeys, steps + 1))
        return -1

class Solution:
    def subtreeWithAllDeepest(self, root: TreeNode) -> TreeNode:
        def dfs(node):
            if not node: return (0, None)
            ld, ln = dfs(node.left)
            rd, rn = dfs(node.right)
            if ld == rd: return (ld + 1, node)
            return (ld + 1, ln) if ld > rd else (rd + 1, rn)
        return dfs(root)[1]

