class Solution:
    def binaryGap(self, n: int) -> int:
        last, ans, pos = -1, 0, 0
        while n:
            if n & 1:
                if last >= 0: ans = max(ans, pos - last)
                last = pos
            n >>= 1
            pos += 1
        return ans

