class Solution:
    def advantageCount(self, nums1: List[int], nums2: List[int]) -> List[int]:
        nums1.sort()
        order = sorted(range(len(nums2)), key=lambda i: -nums2[i])
        lo, hi = 0, len(nums1) - 1
        res = [0] * len(nums1)
        for i in order:
            if nums1[hi] > nums2[i]:
                res[i] = nums1[hi]
                hi -= 1
            else:
                res[i] = nums1[lo]
                lo += 1
        return res

class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        import heapq
        heap, fuel, stops, i = [], startFuel, 0, 0
        while fuel < target:
            while i < len(stations) and stations[i][0] <= fuel:
                heapq.heappush(heap, -stations[i][1])
                i += 1
            if not heap: return -1
            fuel += -heapq.heappop(heap)
            stops += 1
        return stops

class Solution:
    def leafSimilar(self, root1: TreeNode, root2: TreeNode) -> bool:
        def leaves(node):
            if not node: return []
            if not node.left and not node.right: return [node.val]
            return leaves(node.left) + leaves(node.right)
        return leaves(root1) == leaves(root2)

class Solution:
    def lenLongestFibSubseq(self, arr: List[int]) -> int:
        idx = {v: i for i, v in enumerate(arr)}
        dp = {}
        ans = 0
        for j in range(len(arr)):
            for i in range(j):
                k = idx.get(arr[j] - arr[i], -1)
                if k >= 0 and k < i:
                    dp[i,j] = dp.get((k,i), 2) + 1
                    ans = max(ans, dp[i,j])
        return ans if ans >= 3 else 0

class Solution:
    def robotSim(self, commands: List[int], obstacles: List[List[int]]) -> int:
        obs = set(map(tuple, obstacles))
        dx, dy = [0,1,0,-1], [1,0,-1,0]
        x = y = d = 0
        ans = 0
        for cmd in commands:
            if cmd == -2: d = (d + 3) % 4
            elif cmd == -1: d = (d + 1) % 4
            else:
                for _ in range(cmd):
                    nx, ny = x + dx[d], y + dy[d]
                    if (nx, ny) in obs: break
                    x, y = nx, ny
                ans = max(ans, x*x + y*y)
        return ans

class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            if sum((p + mid - 1) // mid for p in piles) <= h:
                hi = mid
            else:
                lo = mid + 1
        return lo

