class Solution:
    def spiralMatrixIII(self, rows: int, cols: int, rStart: int, cStart: int) -> List[List[int]]:
        res = [[rStart, cStart]]
        dx, dy = [0, 1, 0, -1], [1, 0, -1, 0]
        steps = 1
        r, c, d = rStart, cStart, 0
        while len(res) < rows * cols:
            for _ in range(2):
                for _ in range(steps):
                    r, c = r + dx[d], c + dy[d]
                    if 0 <= r < rows and 0 <= c < cols:
                        res.append([r, c])
                d = (d + 1) % 4
            steps += 1
        return res

class Solution:
    def possibleBipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        graph = [[] for _ in range(n+1)]
        for u, v in dislikes:
            graph[u].append(v)
            graph[v].append(u)
        color = [0] * (n+1)
        for i in range(1, n+1):
            if color[i] == 0:
                queue = [i]
                color[i] = 1
                while queue:
                    node = queue.pop()
                    for nei in graph[node]:
                        if color[nei] == 0:
                            color[nei] = -color[node]
                            queue.append(nei)
                        elif color[nei] == color[node]:
                            return False
        return True

class Solution:
    def superEggDrop(self, k: int, n: int) -> int:
        dp = [[0] * (n+1) for _ in range(k+1)]
        m = 0
        while dp[k][m] < n:
            m += 1
            for i in range(1, k+1):
                dp[i][m] = dp[i-1][m-1] + dp[i][m-1] + 1
        return m

class Solution:
    def fairCandySwap(self, aliceSizes: List[int], bobSizes: List[int]) -> List[int]:
        sa, sb = sum(aliceSizes), sum(bobSizes)
        delta = (sa - sb) // 2
        setB = set(bobSizes)
        for a in aliceSizes:
            if a - delta in setB:
                return [a, a - delta]
        return []

class Solution:
    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:
        def match(w, p):
            m1, m2 = {}, {}
            for a, b in zip(w, p):
                if m1.setdefault(a, b) != b: return False
                if m2.setdefault(b, a) != a: return False
            return True
        return [w for w in words if match(w, pattern)]

class Solution:
