class RLEIterator:
    def __init__(self, encoding: List[int]):
        self.enc = encoding
        self.idx = 0
    def next(self, n: int) -> int:
        while self.idx < len(self.enc):
            if self.enc[self.idx] >= n:
                self.enc[self.idx] -= n
                return self.enc[self.idx + 1]
            n -= self.enc[self.idx]
            self.idx += 2
        return -1

class StockSpanner:
    def __init__(self):
        self.stack = []
    def next(self, price: int) -> int:
        span = 1
        while self.stack and self.stack[-1][0] <= price:
            span += self.stack.pop()[1]
        self.stack.append((price, span))
        return span

class Solution:
    def atMostNGivenDigitSet(self, digits, n: int) -> int:
        s = str(n)
        k, d = len(s), len(digits)
        res = sum(d**i for i in range(1, k))
        for i, c in enumerate(s):
            less = sum(1 for x in digits if x < c)
            res += less * (d ** (k - i - 1))
            if c not in digits:
                break
            if i == k - 1:
                res += 1
        return res

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [1] * (n + 1)
        for i in range(1, n + 1):
            ndp = [0] * (n + 1 - i)
            if s[i-1] == 'D':
                suffix = 0
                for j in range(len(ndp)-1, -1, -1):
                    suffix = (suffix + dp[j+1]) % MOD
                    ndp[j] = suffix
            else:
                prefix = 0
                for j in range(len(ndp)):
                    prefix = (prefix + dp[j]) % MOD
                    ndp[j] = prefix
            dp = ndp
        return dp[0]

