        ans = nums[-1] - nums[0]
        for i in range(n - 1):
            hi = max(nums[i] + k, nums[-1] - k)
            lo = min(nums[0] + k, nums[i+1] - k)
            ans = min(ans, hi - lo)
        return ans

class TopVotedCandidate:
    def __init__(self, persons, times):
        self.times = times
        self.leads = []
        cnt = {}
        lead = -1
        for p in persons:
            cnt[p] = cnt.get(p, 0) + 1
            if cnt[p] >= cnt.get(lead, 0):
                lead = p
            self.leads.append(lead)
    def q(self, t: int) -> int:
        import bisect
        i = bisect.bisect_right(self.times, t) - 1
        return self.leads[i]

class Solution:
    def sortArray(self, nums):
        if len(nums) <= 1: return nums
        mid = len(nums) // 2
        left = self.sortArray(nums[:mid])
        right = self.sortArray(nums[mid:])
        res, i, j = [], 0, 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                res.append(left[i]); i += 1
            else:
                res.append(right[j]); j += 1
        res.extend(left[i:])
        res.extend(right[j:])
        return res

class Solution:
    def catMouseGame(self, graph) -> int:
        from collections import deque
        n = len(graph)
        DRAW, MOUSE, CAT = 0, 1, 2
        color = [[[DRAW]*3 for _ in range(n)] for _ in range(n)]
        degree = [[[0]*3 for _ in range(n)] for _ in range(n)]
        for m in range(n):
            for c in range(n):
                degree[m][c][1] = len(graph[m])
                degree[m][c][2] = len(graph[c]) - (0 in graph[c])
        q = deque()
        for i in range(n):
            for t in (1, 2):
                color[0][i][t] = MOUSE
                q.append((0, i, t, MOUSE))
                if i > 0:
                    color[i][i][t] = CAT
                    q.append((i, i, t, CAT))
        while q:
            m, c, t, result = q.popleft()
            for pm, pc, pt in self.parents(graph, m, c, t, n):
                if color[pm][pc][pt] != DRAW: continue
                if pt == result:
                    color[pm][pc][pt] = result
                    q.append((pm, pc, pt, result))
                else:
                    degree[pm][pc][pt] -= 1
                    if degree[pm][pc][pt] == 0:
                        color[pm][pc][pt] = result
                        q.append((pm, pc, pt, result))
        return color[1][2][1]
    def parents(self, graph, m, c, t, n):
        if t == 2:
            for pm in graph[m]:
                yield (pm, c, 1)
        else:
            for pc in graph[c]:
                if pc != 0:
                    yield (m, pc, 2)

class Solution:
    def partitionDisjoint(self, nums) -> int:
        n = len(nums)
        max_left = [0] * n
        min_right = [0] * n
        max_left[0] = nums[0]
        for i in range(1, n):
            max_left[i] = max(max_left[i-1], nums[i])
        min_right[-1] = nums[-1]
        for i in range(n-2, -1, -1):
            min_right[i] = min(min_right[i+1], nums[i])
        for i in range(n-1):
            if max_left[i] <= min_right[i+1]:
                return i + 1

