class Solution:
    def threeSumMulti(self, arr, target):
        from collections import Counter
        c = Counter(arr)
        keys = sorted(c)
        res = 0
        MOD = 10**9 + 7
        for i, x in enumerate(keys):
            for y in keys[i:]:
                z = target - x - y
                if z < y: break
                if z not in c: continue
                if x == y == z:
                    res += c[x] * (c[x]-1) * (c[x]-2) // 6
                elif x == y:
                    res += c[x] * (c[x]-1) // 2 * c[z]
                elif y == z:
                    res += c[x] * c[y] * (c[y]-1) // 2
                else:
                    res += c[x] * c[y] * c[z]
        return res % MOD

class Solution:
    def minMalwareSpread(self, graph, initial):
        n = len(graph)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(n):
            for j in range(i+1, n):
                if graph[i][j]:
                    pi, pj = find(i), find(j)
                    if pi != pj: parent[pi] = pj
        from collections import Counter
        size = Counter(find(i) for i in range(n))
        inf_count = Counter()
        for x in initial:
            inf_count[find(x)] += 1
        initial.sort()
        res = initial[0]
        best = -1
        for x in initial:
            p = find(x)
            if inf_count[p] == 1 and size[p] > best:
                best = size[p]
                res = x
        return res

