class Solution:
    def minMalwareSpread(self, graph, initial):
        n = len(graph)
        inf_set = set(initial)
        parent = list(range(n))
        size = [1] * n
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            a, b = find(a), find(b)
            if a != b:
                if size[a] < size[b]: a, b = b, a
                parent[b] = a
                size[a] += size[b]
        for i in range(n):
            if i in inf_set: continue
            for j in range(i+1, n):
                if j in inf_set: continue
                if graph[i][j]: union(i, j)
        from collections import defaultdict
        contrib = defaultdict(int)
        for i in range(n):
            if i in inf_set: continue
            neighbors = set()
            for m in initial:
                if graph[i][m]: neighbors.add(m)
            if len(neighbors) == 1:
                m = neighbors.pop()
                contrib[m] += size[find(i)]
        initial.sort()
        if not contrib: return initial[0]
        return max(initial, key=lambda x: (contrib.get(x, 0), -x))

