class Solution:
    def shortestBridge(self, grid):
        from collections import deque
        n = len(grid)
        visited = [[False]*n for _ in range(n)]
        q = deque()
        def dfs(i, j):
            visited[i][j] = True
            q.append((i, j))
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = i+di, j+dj
                if 0<=ni<n and 0<=nj<n and not visited[ni][nj] and grid[ni][nj]:
                    dfs(ni, nj)
        import sys
        sys.setrecursionlimit(10000)
        found = False
        for i in range(n):
            for j in range(n):
                if grid[i][j] and not found:
                    dfs(i, j)
                    found = True
                    break
            if found: break
        step = 0
        while q:
            for _ in range(len(q)):
                x, y = q.popleft()
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = x+dx, y+dy
                    if 0<=nx<n and 0<=ny<n and not visited[nx][ny]:
                        if grid[nx][ny]: return step
                        visited[nx][ny] = True
                        q.append((nx, ny))
            step += 1
        return -1

class Solution:
    def knightDialer(self, n):
        MOD = 10**9 + 7
        moves = {0:[4,6],1:[6,8],2:[7,9],3:[4,8],4:[0,3,9],5:[],6:[0,1,7],7:[2,6],8:[1,3],9:[2,4]}
        dp = [1] * 10
        for _ in range(n-1):
            ndp = [0] * 10
            for i in range(10):
                for j in moves[i]:
                    ndp[j] = (ndp[j] + dp[i]) % MOD
            dp = ndp
        return sum(dp) % MOD

