class Solution:
    def removeStones(self, stones):
        parent = {}
        def find(x):
            if x not in parent: parent[x] = x
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            parent[find(a)] = find(b)
        for r, c in stones:
