            if not node:
                end = True
            else:
                if end: return False
                q.append(node.left)
                q.append(node.right)
        return True

class Solution:
    def regionsBySlashes(self, grid):
        n = len(grid)
        parent = list(range(4*n*n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            parent[find(a)] = find(b)
        for i in range(n):
            for j in range(n):
                base = 4*(i*n+j)
                if grid[i][j] == ' ':
                    union(base,base+1)
                    union(base+1,base+2)
                    union(base+2,base+3)
                elif grid[i][j] == '/':
                    union(base,base+3)
                    union(base+1,base+2)
                else:
                    union(base,base+1)
                    union(base+2,base+3)
                if j+1<n: union(base+1,4*(i*n+j+1)+3)
                if i+1<n: union(base+2,4*((i+1)*n+j))
        return len(set(find(x) for x in range(4*n*n)))

