        m, n = len(grid), len(grid[0])
        empty = 1
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1: si, sj = i, j
                elif grid[i][j] == 0: empty += 1
        def dfs(i, j, remain):
            if grid[i][j] == 2: return 1 if remain == 0 else 0
            grid[i][j] = -1
            res = 0
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = i+di, j+dj
                if 0<=ni<m and 0<=nj<n and grid[ni][nj]!=-1:
                    res += dfs(ni, nj, remain-1)
            grid[i][j] = 0
            return res
        return dfs(si, sj, empty)

class TimeMap:
    def __init__(self):
        self.d = {}
    def set(self, key: str, value: str, timestamp: int) -> None:
        self.d.setdefault(key, []).append((timestamp, value))
    def get(self, key: str, timestamp: int) -> str:
        if key not in self.d: return ''
        arr = self.d[key]
        lo, hi = 0, len(arr)-1
        res = ''
        while lo <= hi:
            mid = (lo+hi)//2
            if arr[mid][0] <= timestamp:
                res = arr[mid][1]; lo = mid+1
            else: hi = mid-1
        return res

