class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        left = zeros = result = 0
        for right in range(len(nums)):
            if nums[right] == 0:
                zeros += 1
            while zeros > k:
                if nums[left] == 0:
                    zeros -= 1
                left += 1
            result = max(result, right - left + 1)
        return result

class Solution:
    def largestSumAfterKNegations(self, nums: List[int], k: int) -> int:
        nums.sort()
        for i in range(len(nums)):
            if nums[i] < 0 and k > 0:
                nums[i] = -nums[i]; k -= 1
        return sum(nums) - (min(nums)*2 if k%2 else 0)

class Solution:
    def clumsy(self, n: int) -> int:
        stack = [n]
        ops = ['*', '//', '+', '-']
        idx = 0
        for i in range(n-1, 0, -1):
            op = ops[idx % 4]
            if op == '*': stack[-1] *= i
            elif op == '//': stack[-1] = int(stack[-1]/i)
            elif op == '+': stack.append(i)
            else: stack.append(-i)
            idx += 1
        return sum(stack)

class Solution:
    def minDominoRotations(self, tops: List[int], bottoms: List[int]) -> int:
        def check(target):
            a = b = 0
            for i in range(len(tops)):
                if tops[i] != target and bottoms[i] != target: return -1
                elif tops[i] != target: a += 1
                elif bottoms[i] != target: b += 1
            return min(a, b)
        res = check(tops[0])
        if res != -1: return res
        return check(bottoms[0])

class Solution:
    def bstFromPreorder(self, preorder: List[int]) -> Optional[TreeNode]:
        self.i = 0
        def build(bound):
            if self.i == len(preorder) or preorder[self.i] > bound:
                return None
            val = preorder[self.i]
            self.i += 1
            node = TreeNode(val)
            node.left = build(val)
            node.right = build(bound)
            return node
        return build(float('inf'))

class Solution:
    def bitwiseComplement(self, n: int) -> int:
        if n == 0: return 1
        mask = (1 << n.bit_length()) - 1
        return n ^ mask

class Solution:
    def numPairsDivisibleBy60(self, time: List[int]) -> int:
        cnt = [0]*60
        res = 0
        for t in time:
            r = t % 60
            res += cnt[(60-r)%60]
            cnt[r] += 1
        return res

class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def can_ship(cap):
            d, curr = 1, 0
            for w in weights:
                if curr + w > cap:
                    d += 1
                    curr = w
                else:
                    curr += w
            return d <= days
        lo, hi = max(weights), sum(weights)
        while lo < hi:
            mid = (lo + hi) // 2
            if can_ship(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def numDupDigitsAtMostN(self, n: int) -> int:
        digits = list(map(int, str(n+1)))
        k = len(digits)
        cnt = 0
        # count numbers with fewer digits
        for i in range(1, k):
            cnt += 9 * self.perm(9, i-1)
        # count numbers with same digits
        seen = set()
        for i, d in enumerate(digits):
            start = 0 if i else 1
            for j in range(start, d):
                if j not in seen:
                    cnt += self.perm(9-i, k-i-1)
            if d in seen: break
            seen.add(d)
        return n - cnt
    def perm(self, m, n):
        r = 1
        for i in range(n): r *= m-i
        return r

class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        total = sum(arr)
        if total % 3 != 0: return False
        target = total // 3
        parts = s = 0
        for i in range(len(arr)):
            s += arr[i]
            if s == target * (parts+1):
                parts += 1
                if parts == 2 and i < len(arr)-1: return True
        return False

class Solution:
    def maxScoreSightseeingPair(self, values: List[int]) -> int:
        res = 0
        best = values[0]
        for j in range(1, len(values)):
            res = max(res, best + values[j] - j)
            best = max(best, values[j] + j)
        return res

class Solution:
    def smallestRepunitDivByK(self, k: int) -> int:
        if k % 2 == 0 or k % 5 == 0: return -1
        r = 0
        for length in range(1, k+1):
            r = (r * 10 + 1) % k
            if r == 0: return length
        return -1

class Solution:
    def queryString(self, s: str, n: int) -> bool:
        for i in range(n, n//2, -1):
            if bin(i)[2:] not in s: return False
        return True

class Solution:
    def baseNeg2(self, n: int) -> str:
        if n == 0: return '0'
        res = []
        while n:
            n, r = divmod(n, -2)
            if r < 0: r += 2; n += 1
            res.append(str(r))
        return ''.join(reversed(res))

class Solution:
    def prefixesDivBy5(self, nums: List[int]) -> List[bool]:
        res = []
        val = 0
        for x in nums:
            val = (val * 2 + x) % 5
            res.append(val == 0)
        return res

class Solution:
    def nextLargerNodes(self, head: Optional[ListNode]) -> List[int]:
        arr = []
        while head:
            arr.append(head.val); head = head.next
        res = [0]*len(arr)
        stack = []
        for i, v in enumerate(arr):
            while stack and arr[stack[-1]] < v:
                res[stack.pop()] = v
            stack.append(i)
        return res

class Solution:
    def numEnclaves(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        def dfs(i, j):
            if i<0 or i>=m or j<0 or j>=n or grid[i][j]!=1: return
            grid[i][j] = 0
            for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]: dfs(i+di,j+dj)
        for i in range(m):
            for j in range(n):
                if (i==0 or i==m-1 or j==0 or j==n-1) and grid[i][j]==1:
                    dfs(i,j)
        return sum(grid[i][j] for i in range(m) for j in range(n))

class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        res, opened = [], 0
        for c in s:
            if c == '(':
                if opened > 0: res.append(c)
                opened += 1
            else:
                opened -= 1
                if opened > 0: res.append(c)
        return ''.join(res)

class Solution:
    def sumRootToLeaf(self, root) -> int:
        def dfs(node, val):
            if not node: return 0
            val = val * 2 + node.val
            if not node.left and not node.right: return val
            return dfs(node.left, val) + dfs(node.right, val)
        return dfs(root, 0)

class Solution:
    def camelMatch(self, queries, pattern: str):
        def match(q, p):
            j = 0
            for c in q:
                if j < len(p) and c == p[j]: j += 1
                elif c.isupper(): return False
            return j == len(p)
        return [match(q, pattern) for q in queries]

class Solution:
    def videoStitching(self, clips, time: int) -> int:
        clips.sort()
        res, end, far = 0, 0, 0
        i = 0
        while end < time:
            while i < len(clips) and clips[i][0] <= end:
                far = max(far, clips[i][1])
                i += 1
            if far == end: return -1
            end = far
            res += 1
        return res

class Solution:
    def divisorGame(self, n: int) -> bool:
        return n % 2 == 0

class Solution:
    def maxAncestorDiff(self, root) -> int:
        def dfs(node, mn, mx):
            if not node: return mx - mn
            mn, mx = min(mn, node.val), max(mx, node.val)
            return max(dfs(node.left, mn, mx), dfs(node.right, mn, mx))
        return dfs(root, root.val, root.val)

class Solution:
    def longestArithSeqLength(self, nums) -> int:
        n = len(nums)
        dp = [{} for _ in range(n)]
        res = 2
        for i in range(n):
            for j in range(i):
                d = nums[i] - nums[j]
                dp[i][d] = dp[j].get(d, 1) + 1
                res = max(res, dp[i][d])
        return res

class Solution:
    def recoverFromPreorder(self, traversal: str):
        from TreeNode import TreeNode
        stack, i = [], 0
        while i < len(traversal):
            depth = 0
            while i < len(traversal) and traversal[i] == '-': depth += 1; i += 1
            val = 0
            while i < len(traversal) and traversal[i].isdigit(): val = val*10+int(traversal[i]); i += 1
            node = TreeNode(val)
            while len(stack) > depth: stack.pop()
            if stack:
                if not stack[-1].left: stack[-1].left = node
                else: stack[-1].right = node
            stack.append(node)
        return stack[0]

class Solution:
    def twoCitySchedCost(self, costs) -> int:
        costs.sort(key=lambda x: x[0]-x[1])
        n = len(costs)//2
        return sum(c[0] for c in costs[:n]) + sum(c[1] for c in costs[n:])

class Solution:
    def allCellsDistOrder(self, rows, cols, rCenter, cCenter):
        cells = [(r,c) for r in range(rows) for c in range(cols)]
        cells.sort(key=lambda x: abs(x[0]-rCenter)+abs(x[1]-cCenter))
        return cells

class Solution:
    def maxSumTwoNoOverlap(self, nums, firstLen, lastLen) -> int:
        def helper(L, M):
            n = len(nums)
            p = [0]*(n+1)
            for i in range(n): p[i+1]=p[i]+nums[i]
            res, maxL = 0, 0
            for i in range(L+M, n+1):
                maxL = max(maxL, p[i-M]-p[i-M-L])
                res = max(res, maxL+p[i]-p[i-M])
            return res
        return max(helper(firstLen,lastLen), helper(lastLen,firstLen))

class StreamChecker:
    def __init__(self, words):
        self.trie = {}
        self.stream = []
        for w in words:
            node = self.trie
            for c in reversed(w):
                node = node.setdefault(c, {})
            node['#'] = True
    def query(self, letter: str) -> bool:
        self.stream.append(letter)
        node = self.trie
        for c in reversed(self.stream):
            if c not in node: return False
            node = node[c]
            if '#' in node: return True
        return False

class Solution:
    def colorBorder(self, grid, row, col, color):
        m, n = len(grid), len(grid[0])
        orig = grid[row][col]
        visited = set()
        border = []
        def dfs(r, c):
            if (r,c) in visited: return
            visited.add((r,c))
            is_border = False
            for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n:
                    if grid[nr][nc] == orig: dfs(nr,nc)
                    elif (nr,nc) not in visited: is_border = True
                else: is_border = True
            if is_border: border.append((r,c))
        dfs(row, col)
        for r,c in border: grid[r][c] = color
        return grid

class Solution:
    def maxUncrossedLines(self, nums1, nums2) -> int:
        m, n = len(nums1), len(nums2)
        dp = [[0]*(n+1) for _ in range(m+1)]
        for i in range(1,m+1):
            for j in range(1,n+1):
                if nums1[i-1]==nums2[j-1]: dp[i][j]=dp[i-1][j-1]+1
                else: dp[i][j]=max(dp[i-1][j],dp[i][j-1])
        return dp[m][n]

class Solution:
    def isEscapePossible(self, blocked, source, target) -> bool:
        if not blocked: return True
        blocked = set(map(tuple, blocked))
        limit = len(blocked) * len(blocked) // 2
        def bfs(start, end):
            queue, visited = [start], {tuple(start)}
            for x, y in queue:
                if [x,y] == end: return True
                if len(visited) > limit: return True
                for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = x+dx, y+dy
                    if 0<=nx<10**6 and 0<=ny<10**6 and (nx,ny) not in blocked and (nx,ny) not in visited:
                        visited.add((nx,ny))
                        queue.append((nx,ny))
            return False
        return bfs(source, target) and bfs(target, source)

class Solution:
    def isBoomerang(self, points) -> bool:
        (x1,y1),(x2,y2),(x3,y3) = points
        return (x2-x1)*(y3-y1) - (y2-y1)*(x3-x1) != 0

class Solution:
    def minScoreTriangulation(self, values) -> int:
        n = len(values)
        dp = [[0]*n for _ in range(n)]
        for l in range(2, n):
            for i in range(n-l):
                j = i+l
                dp[i][j] = float('inf')
                for k in range(i+1, j):
                    dp[i][j] = min(dp[i][j], dp[i][k]+dp[k][j]+values[i]*values[k]*values[j])
        return dp[0][n-1]

class Solution:
    def numMovesStonesII(self, stones):
        stones.sort()
        n = len(stones)
        mx = max(stones[n-1]-stones[1], stones[n-2]-stones[0]) - (n-2)
        mn = n
        j = 0
        for i in range(n):
            while j < n and stones[j]-stones[i] < n: j += 1
            cnt = j - i
            if cnt == n-1 and stones[j-1]-stones[i] == n-2:
                mn = min(mn, 2)
            else:
                mn = min(mn, n-cnt)
        return [mn, mx]

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        x, y, dx, dy = 0, 0, 0, 1
        for c in instructions:
            if c == 'G': x, y = x+dx, y+dy
            elif c == 'L': dx, dy = -dy, dx
            else: dx, dy = dy, -dx
        return (x==0 and y==0) or (dx, dy) != (0, 1)

class Solution:
    def gardenNoAdj(self, n, paths):
        graph = [[] for _ in range(n)]
        for u,v in paths:
            graph[u-1].append(v-1)
            graph[v-1].append(u-1)
        res = [0]*n
        for i in range(n):
            used = {res[j] for j in graph[i]}
            for c in range(1,5):
                if c not in used:
                    res[i] = c
                    break
        return res

class Solution:
    def maxSumAfterPartitioning(self, arr, k: int) -> int:
        n = len(arr)
        dp = [0]*(n+1)
        for i in range(1, n+1):
            mx = 0
            for j in range(1, min(k, i)+1):
                mx = max(mx, arr[i-j])
                dp[i] = max(dp[i], dp[i-j]+mx*j)
        return dp[n]

class Solution:
    def longestDupSubstring(self, s: str) -> str:
        from functools import reduce
        n, mod, base = len(s), (1<<61)-1, 131
        nums = [ord(c)-ord('a') for c in s]
        def check(L):
            h = reduce(lambda a,b: (a*base+b)%mod, nums[:L], 0)
            seen = {h}
            power = pow(base, L, mod)
            for i in range(1, n-L+1):
                h = (h*base - nums[i-1]*power + nums[i+L-1]) % mod
                if h in seen: return i
                seen.add(h)
            return -1
        lo, hi, res = 1, n-1, 0
        while lo <= hi:
            mid = (lo+hi)//2
            idx = check(mid)
            if idx != -1:
                res = idx
                lo = mid+1
            else: hi = mid-1
        return s[res:res+hi] if hi >= 1 else ''

import heapq
class Solution:
    def lastStoneWeight(self, stones: List[int]) -> int:
        heap = [-s for s in stones]
        heapq.heapify(heap)
        while len(heap) > 1:
            a = -heapq.heappop(heap)
            b = -heapq.heappop(heap)
            if a != b:
                heapq.heappush(heap, -(a - b))
        return -heap[0] if heap else 0

class Solution:
    def removeDuplicates(self, s: str) -> str:
        stack = []
        for c in s:
            if stack and stack[-1] == c: stack.pop()
            else: stack.append(c)
        return ''.join(stack)

class Solution:
    def longestStrChain(self, words) -> int:
        words.sort(key=len)
        dp = {}
        res = 1
        for w in words:
            dp[w] = 1
            for i in range(len(w)):
                prev = w[:i]+w[i+1:]
                if prev in dp:
                    dp[w] = max(dp[w], dp[prev]+1)
            res = max(res, dp[w])
        return res

class Solution:
    def lastStoneWeightII(self, stones: List[int]) -> int:
        total = sum(stones)
        target = total // 2
        dp = [False] * (target + 1)
        dp[0] = True
        for s in stones:
            for j in range(target, s-1, -1):
                dp[j] = dp[j] or dp[j-s]
        for j in range(target, -1, -1):
            if dp[j]:
                return total - 2 * j

class Solution:
    def heightChecker(self, heights) -> int:
        return sum(a!=b for a,b in zip(heights, sorted(heights)))

class Solution:
    def maxSatisfied(self, customers, grumpy, minutes) -> int:
        base = sum(c for c,g in zip(customers, grumpy) if g==0)
        extra = sum(customers[i]*grumpy[i] for i in range(minutes))
        max_extra = extra
        for i in range(minutes, len(customers)):
            extra += customers[i]*grumpy[i] - customers[i-minutes]*grumpy[i-minutes]
            max_extra = max(max_extra, extra)
        return base + max_extra

class Solution:
    def rearrangeBarcodes(self, barcodes):
        from collections import Counter
        cnt = Counter(barcodes)
        sorted_items = sorted(cnt.items(), key=lambda x: -x[1])
        res = [0]*len(barcodes)
        idx = 0
        for val, freq in sorted_items:
            for _ in range(freq):
                res[idx] = val
                idx += 2
                if idx >= len(barcodes): idx = 1
        return res

class Solution:
    def shortestWay(self, source: str, target: str) -> int:
        res, i = 0, 0
        while i < len(target):
            start = i
            for c in source:
                if i < len(target) and c == target[i]: i += 1
            if i == start: return -1
            res += 1
        return res

class Solution:
    def confusingNumber(self, n: int) -> bool:
        mp = {'0':'0','1':'1','6':'9','8':'8','9':'6'}
        s = str(n)
        rotated = ''
        for c in s:
            if c not in mp: return False
            rotated = mp[c] + rotated
        return rotated != s

class Solution:
    def assignBikes(self, workers, bikes):
        pairs = []
        for i, w in enumerate(workers):
            for j, b in enumerate(bikes):
                pairs.append((abs(w[0]-b[0])+abs(w[1]-b[1]), i, j))
        pairs.sort()
        res = [-1]*len(workers)
        used = set()
        for d, i, j in pairs:
            if res[i] == -1 and j not in used:
                res[i] = j
                used.add(j)
        return res

class Solution:
    def leadsToDestination(self, n, edges, source, destination) -> bool:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
        if graph[destination]: return False
        state = [0]*n  # 0:unvisited, 1:visiting, 2:visited
        def dfs(u):
            if state[u] == 1: return False
            if state[u] == 2: return True
            if not graph[u]: return u == destination
            state[u] = 1
            for v in graph[u]:
                if not dfs(v): return False
            state[u] = 2
            return True
        return dfs(source)

class Solution:
    def missingElement(self, nums, k: int) -> int:
        def missing(i):
            return nums[i] - nums[0] - i
        n = len(nums)
        if k > missing(n-1):
            return nums[-1] + k - missing(n-1)
        lo, hi = 0, n-1
        while lo < hi:
            mid = (lo+hi)//2
            if missing(mid) < k: lo = mid+1
            else: hi = mid
        return nums[lo-1] + k - missing(lo-1)

class Solution:
    def smallestEquivalentString(self, s1, s2, baseStr) -> str:
        parent = list(range(26))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra < rb: parent[rb] = ra
            else: parent[ra] = rb
        for a, b in zip(s1, s2):
            union(ord(a)-97, ord(b)-97)
        return ''.join(chr(find(ord(c)-97)+97) for c in baseStr)

class Solution:
    def longestRepeatingSubstring(self, s: str) -> int:
        n = len(s)
        def check(L):
            seen = set()
            for i in range(n-L+1):
                t = s[i:i+L]
                if t in seen: return True
                seen.add(t)
            return False
        lo, hi = 0, n-1
        while lo < hi:
            mid = (lo+hi+1)//2
            if check(mid): lo = mid
            else: hi = mid-1
        return lo

class Solution:
    def validSubarrays(self, nums) -> int:
        stack = []
        res = 0
        for i, num in enumerate(nums):
            while stack and nums[stack[-1]] > num:
                res += i - stack.pop()
            stack.append(i)
        while stack:
            res += len(nums) - stack.pop()
        return res

class Solution:
    def fixedPoint(self, arr) -> int:
        lo, hi, res = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo+hi)//2
            if arr[mid] == mid:
                res = mid
                hi = mid-1
            elif arr[mid] < mid: lo = mid+1
            else: hi = mid-1
        return res

class Solution:
    def indexPairs(self, text, words):
        res = []
        for w in words:
            start = 0
            while True:
                idx = text.find(w, start)
                if idx == -1: break
                res.append([idx, idx+len(w)-1])
                start = idx+1
        res.sort()
        return res

class Solution:
    def assignBikes(self, workers, bikes) -> int:
        from functools import lru_cache
        n, m = len(workers), len(bikes)
        @lru_cache(None)
        def dp(i, mask):
            if i == n: return 0
            res = float('inf')
            for j in range(m):
                if not (mask & (1<<j)):
                    d = abs(workers[i][0]-bikes[j][0])+abs(workers[i][1]-bikes[j][1])
                    res = min(res, d + dp(i+1, mask|(1<<j)))
            return res
        return dp(0, 0)

class Solution:
    def digitsCount(self, d: int, low: int, high: int) -> int:
        def count(n):
            if n < 0: return 0
            res, pos = 0, 1
            while pos <= n:
                divider = pos * 10
                res += (n // divider) * pos
                cur = (n // pos) % 10
                if d == 0: res -= pos
                if cur > d: res += pos
                elif cur == d: res += n % pos + 1
                pos *= 10
            return res
        return count(high) - count(low - 1)

class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:
        if str1 + str2 != str2 + str1: return ''
        from math import gcd
        return str1[:gcd(len(str1), len(str2))]

class Solution:
    def maxEqualRowsAfterFlips(self, matrix) -> int:
        from collections import Counter
        cnt = Counter()
        for row in matrix:
            key = tuple(x ^ row[0] for x in row)
            cnt[key] += 1
        return max(cnt.values())

class Solution:
    def addNegabinary(self, arr1, arr2):
        res, carry = [], 0
        i, j = len(arr1)-1, len(arr2)-1
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0: s += arr1[i]; i -= 1
            if j >= 0: s += arr2[j]; j -= 1
            res.append(s & 1)
            carry = -(s >> 1)
        while len(res) > 1 and res[-1] == 0: res.pop()
        return res[::-1]

class Solution:
    def numSubmatrixSumTarget(self, matrix, target) -> int:
        m, n = len(matrix), len(matrix[0])
        res = 0
        for r1 in range(m):
            col_sum = [0]*n
            for r2 in range(r1, m):
                for c in range(n):
                    col_sum[c] += matrix[r2][c]
                cnt = {0: 1}
                s = 0
                for v in col_sum:
                    s += v
                    res += cnt.get(s-target, 0)
                    cnt[s] = cnt.get(s, 0)+1
        return res

class Solution:
    def findOcurrences(self, text: str, first: str, second: str):
        words = text.split()
        return [words[i+2] for i in range(len(words)-2) if words[i]==first and words[i+1]==second]

class Solution:
    def numTilePossibilities(self, tiles: str) -> int:
        from collections import Counter
        cnt = Counter(tiles)
        def bt():
            total = 0
            for c in cnt:
                if cnt[c] > 0:
                    cnt[c] -= 1
                    total += 1 + bt()
                    cnt[c] += 1
            return total
        return bt()

class Solution:
    def sufficientSubset(self, root, limit: int):
        def dfs(node, total):
            if not node: return None
            total += node.val
            if not node.left and not node.right:
                return None if total < limit else node
            node.left = dfs(node.left, total)
            node.right = dfs(node.right, total)
            if not node.left and not node.right: return None
            return node
        return dfs(root, 0)

class Solution:
    def smallestSubsequence(self, s: str) -> str:
        last = {c: i for i, c in enumerate(s)}
        stack = []
        in_stack = set()
        for i, c in enumerate(s):
            if c in in_stack:
                continue
            while stack and c < stack[-1] and last[stack[-1]] > i:
                in_stack.remove(stack.pop())
            stack.append(c)
            in_stack.add(c)
        return ''.join(stack)

class Solution:
    def sumOfDigits(self, nums: List[int]) -> int:
        min_val = min(nums)
        digit_sum = sum(int(d) for d in str(min_val))
        return 1 if digit_sum % 2 == 0 else 0

class Solution:
    def highFive(self, items: List[List[int]]) -> List[List[int]]:
        from collections import defaultdict
        d = defaultdict(list)
        for sid, score in items:
            d[sid].append(score)
        res = []
        for sid in sorted(d):
            top5 = sorted(d[sid], reverse=True)[:5]
            res.append([sid, sum(top5) // 5])
        return res

class Solution:
    def expand(self, s: str) -> List[str]:
        groups = []
        i = 0
        while i < len(s):
            if s[i] == '{':
                j = s.index('}', i)
                groups.append(sorted(s[i+1:j].split(',')))
                i = j + 1
            else:
                groups.append([s[i]])
                i += 1
        res = []
        def bt(idx, path):
            if idx == len(groups):
                res.append(''.join(path))
                return
            for c in groups[idx]:
                bt(idx + 1, path + [c])
        bt(0, [])
        return res

class Solution:
    def confusingNumberII(self, n: int) -> int:
        mapping = {0:0, 1:1, 6:9, 8:8, 9:6}
        digits = [0, 1, 6, 8, 9]
        self.count = 0
        def is_confusing(num):
            src = num
            rotated = 0
            while num > 0:
                rotated = rotated * 10 + mapping[num % 10]
                num //= 10
            return rotated != src
        def bt(cur):
            if cur > n:
                return
            if cur != 0 and is_confusing(cur):
                self.count += 1
            for d in digits:
                nxt = cur * 10 + d
                if nxt == 0:
                    continue
                if nxt > n:
                    break
                bt(nxt)
        bt(0)
        return self.count

class Solution:
    def duplicateZeros(self, arr: List[int]) -> None:
        n = len(arr)
        zeros = arr.count(0)
        for i in range(n - 1, -1, -1):
            if arr[i] == 0:
                zeros -= 1
                if i + zeros + 1 < n:
                    arr[i + zeros + 1] = 0
            if i + zeros < n:
                arr[i + zeros] = arr[i]

class Solution:
    def largestValsFromLabels(self, values: List[int], labels: List[int], numWanted: int, useLimit: int) -> int:
        from collections import Counter
        items = sorted(zip(values, labels), reverse=True)
        label_count = Counter()
        res = 0
        chosen = 0
        for val, label in items:
            if chosen >= numWanted:
                break
            if label_count[label] < useLimit:
                res += val
                label_count[label] += 1
                chosen += 1
        return res

class Solution:
    def shortestPathBinaryMatrix(self, grid: List[List[int]]) -> int:
        from collections import deque
        n = len(grid)
        if grid[0][0] or grid[n-1][n-1]:
            return -1
        q = deque([(0, 0, 1)])
        grid[0][0] = 1
        while q:
            r, c, d = q.popleft()
            if r == n-1 and c == n-1:
                return d
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 0:
                        grid[nr][nc] = 1
                        q.append((nr, nc, d+1))
        return -1

class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        m, n = len(str1), len(str2)
        dp = [[''] * (n+1) for _ in range(m+1)]
        for i in range(1, m+1):
            for j in range(1, n+1):
                if str1[i-1] == str2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + str1[i-1]
                else:
                    dp[i][j] = dp[i-1][j] if len(dp[i-1][j]) > len(dp[i][j-1]) else dp[i][j-1]
        lcs = dp[m][n]
        res = []
        i = j = 0
        for c in lcs:
            while i < m and str1[i] != c:
                res.append(str1[i]); i += 1
            while j < n and str2[j] != c:
                res.append(str2[j]); j += 1
            res.append(c); i += 1; j += 1
        return ''.join(res) + str1[i:] + str2[j:]

class Solution:
    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:
        diff = [0] * 1001
        for num, start, end in trips:
            diff[start] += num
            diff[end] -= num
        cur = 0
        for d in diff:
            cur += d
            if cur > capacity:
                return False
        return True

class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def parse(expr, i):
            groups = [[{''}]]
            while i < len(expr):
                if expr[i] == '{':
                    i, sub = parse(expr, i + 1)
                    groups[-1].append(sub)
                elif expr[i] == '}':
                    break
                elif expr[i] == ',':
                    groups.append([{''}])
                    i += 1
                    continue
                else:
                    groups[-1].append({expr[i]})
                i += 1
            result = set()
            for group in groups:
                cur = {''}
                for s in group:
                    cur = {a + b for a in cur for b in s}
                result |= cur
            return i + 1, result
        _, res = parse(expression, 0)
        return sorted(res)

class Solution:
    def twoSumLessThanK(self, nums: List[int], k: int) -> int:
        nums.sort()
        lo, hi = 0, len(nums) - 1
        res = -1
        while lo < hi:
            s = nums[lo] + nums[hi]
            if s < k:
                res = max(res, s)
                lo += 1
            else:
                hi -= 1
        return res

class Solution:
    def numKLenSubstrNoRepeats(self, s: str, k: int) -> int:
        if k > 26:
            return 0
        from collections import Counter
        cnt = Counter()
        res = 0
        for i, c in enumerate(s):
            cnt[c] += 1
            if i >= k:
                left = s[i - k]
                cnt[left] -= 1
                if cnt[left] == 0:
                    del cnt[left]
            if i >= k - 1 and len(cnt) == k:
                res += 1
        return res

class Solution:
    def maximumMinimumPath(self, grid: List[List[int]]) -> int:
        import heapq
        m, n = len(grid), len(grid[0])
        heap = [(-grid[0][0], 0, 0)]
        visited = [[False]*n for _ in range(m)]
        visited[0][0] = True
        while heap:
            val, r, c = heapq.heappop(heap)
            if r == m-1 and c == n-1:
                return -val
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and not visited[nr][nc]:
                    visited[nr][nc] = True
                    heapq.heappush(heap, (max(val, -grid[nr][nc]), nr, nc))
        return -1

class Solution:
    def minHeightShelves(self, books: List[List[int]], shelfWidth: int) -> int:
        n = len(books)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            w = 0
            h = 0
            for j in range(i, 0, -1):
                w += books[j-1][0]
                if w > shelfWidth:
                    break
                h = max(h, books[j-1][1])
                dp[i] = min(dp[i], dp[j-1] + h)
        return dp[n]

class Solution:
    def parseBoolExpr(self, expression: str) -> bool:
        stack = []
        for c in expression:
            if c == ',':
                continue
            elif c == ')':
                operands = []
                while stack[-1] != '(':
                    operands.append(stack.pop())
                stack.pop()  # remove '('
                op = stack.pop()
                if op == '!':
                    stack.append('t' if operands[0] == 'f' else 'f')
                elif op == '&':
                    stack.append('f' if 'f' in operands else 't')
                elif op == '|':
                    stack.append('t' if 't' in operands else 'f')
            else:
                stack.append(c)
        return stack[0] == 't'

