class Solution:
    def corpFlightBookings(self, bookings, n):
        diff = [0] * (n + 1)
        for first, last, seats in bookings:
            diff[first - 1] += seats
            if last < n:
                diff[last] -= seats
        res = []
        cur = 0
        for i in range(n):
            cur += diff[i]
            res.append(cur)
        return res

class Solution:
    def delNodes(self, root, to_delete):
        res = []
        to_delete = set(to_delete)
        def dfs(node, is_root):
            if not node:
                return None
            deleted = node.val in to_delete
            if is_root and not deleted:
                res.append(node)
            node.left = dfs(node.left, deleted)
            node.right = dfs(node.right, deleted)
            return None if deleted else node
        dfs(root, True)
        return res

class Solution:
    def maxDepthAfterSplit(self, seq: str):
        res = []
        depth = 0
        for c in seq:
            if c == '(':
                depth += 1
                res.append(depth % 2)
            else:
                res.append(depth % 2)
                depth -= 1
        return res

