import threading
class FooBar:
    def __init__(self, n):
        self.n = n
        self.foo_sem = threading.Semaphore(1)
        self.bar_sem = threading.Semaphore(0)
    def foo(self, printFoo):
        for _ in range(self.n):
            self.foo_sem.acquire()
            printFoo()
            self.bar_sem.release()
    def bar(self, printBar):
        for _ in range(self.n):
            self.bar_sem.acquire()
            printBar()
            self.foo_sem.release()

import threading
class ZeroEvenOdd:
    def __init__(self, n):
        self.n = n
        self.zero_sem = threading.Semaphore(1)
        self.even_sem = threading.Semaphore(0)
        self.odd_sem = threading.Semaphore(0)
    def zero(self, printNumber):
        for i in range(1, self.n + 1):
            self.zero_sem.acquire()
            printNumber(0)
            if i % 2 == 1:
                self.odd_sem.release()
            else:
                self.even_sem.release()
    def even(self, printNumber):
        for i in range(2, self.n + 1, 2):
            self.even_sem.acquire()
            printNumber(i)
            self.zero_sem.release()
    def odd(self, printNumber):
        for i in range(1, self.n + 1, 2):
            self.odd_sem.acquire()
            printNumber(i)
            self.zero_sem.release()

class Solution:
    def numberOfDays(self, year: int, month: int) -> int:
        days = [31,28,31,30,31,30,31,31,30,31,30,31]
        if month == 2 and (year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)):
            return 29
        return days[month - 1]

class Solution:
    def removeVowels(self, s: str) -> str:
        return ''.join(c for c in s if c not in 'aeiou')

class Solution:
    def canDivideIntoSubsequences(self, nums, k):
        max_freq = max(len(nums) - i for i, (a, b) in enumerate(zip(nums, nums[1:])) if a != b) if len(set(nums)) > 1 else len(nums)
        # Simpler: count max frequency
        from collections import Counter
        max_freq = max(Counter(nums).values())
        return max_freq * k <= len(nums)

class Solution:
    def relativeSortArray(self, arr1, arr2):
        order = {v: i for i, v in enumerate(arr2)}
        return sorted(arr1, key=lambda x: (order.get(x, len(arr2) + x), x))

class Solution:
    def lcaDeepestLeaves(self, root):
        def dfs(node):
            if not node:
                return None, 0
            left, ld = dfs(node.left)
            right, rd = dfs(node.right)
            if ld == rd:
                return node, ld + 1
            elif ld > rd:
                return left, ld + 1
            else:
                return right, rd + 1
        return dfs(root)[0]

class Solution:
    def longestWPI(self, hours):
        prefix = 0
        first = {}
        ans = 0
        for i, h in enumerate(hours):
            prefix += 1 if h > 8 else -1
            if prefix > 0:
                ans = i + 1
            else:
                if prefix - 1 in first:
                    ans = max(ans, i - first[prefix - 1])
                if prefix not in first:
                    first[prefix] = i
        return ans

class Solution:
    def smallestSufficientTeam(self, req_skills, people):
        n = len(req_skills)
        skill_idx = {s: i for i, s in enumerate(req_skills)}
        target = (1 << n) - 1
        dp = {0: []}
        for i, p in enumerate(people):
            mask = 0
            for s in p:
                if s in skill_idx:
                    mask |= 1 << skill_idx[s]
            for state, team in list(dp.items()):
                new_state = state | mask
                if new_state not in dp or len(dp[new_state]) > len(team) + 1:
                    dp[new_state] = team + [i]
        return dp[target]

class Solution:
    def numEquivDominoPairs(self, dominoes):
        from collections import Counter
        cnt = Counter()
        ans = 0
        for a, b in dominoes:
            key = (min(a,b), max(a,b))
            ans += cnt[key]
            cnt[key] += 1
        return ans

class Solution:
    def shortestAlternatingPaths(self, n, redEdges, blueEdges):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        for u, v in redEdges:
            graph[(u, 0)].append((v, 1))
        for u, v in blueEdges:
            graph[(u, 1)].append((v, 0))
        ans = [-1] * n
        ans[0] = 0
        visited = set()
        q = deque([(0, 0, 0), (0, 1, 0)])  # node, color, dist
        visited.add((0, 0))
        visited.add((0, 1))
        while q:
            node, color, dist = q.popleft()
            for nei, nc in graph[(node, color)]:
                if (nei, nc) not in visited:
                    visited.add((nei, nc))
                    if ans[nei] == -1:
                        ans[nei] = dist + 1
                    q.append((nei, nc, dist + 1))
        return ans

class Solution:
    def mctFromLeafValues(self, arr):
        stack = [float('inf')]
        res = 0
        for x in arr:
            while stack[-1] <= x:
                mid = stack.pop()
                res += mid * min(stack[-1], x)
            stack.append(x)
        while len(stack) > 2:
            res += stack.pop() * stack[-1]
        return res

class Solution:
    def maxAbsValExpr(self, arr1, arr2):
        ans = 0
        for s1 in [1, -1]:
            for s2 in [1, -1]:
                vals = [s1*arr1[i] + s2*arr2[i] + i for i in range(len(arr1))]
                ans = max(ans, max(vals) - min(vals))
        return ans

