class Solution:
    def isArmstrong(self, n: int) -> bool:
        digits = str(n)
        k = len(digits)
        return sum(int(d) ** k for d in digits) == n

class Solution:
    def minimumCost(self, n, connections):
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        connections.sort(key=lambda x: x[2])
        cost = 0
        edges = 0
        for u, v, w in connections:
            pu, pv = find(u), find(v)
            if pu != pv:
                parent[pu] = pv
                cost += w
                edges += 1
        return cost if edges == n - 1 else -1

class Solution:
    def minimumSemesters(self, n, relations):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        indegree = [0] * (n + 1)
        for u, v in relations:
            graph[u].append(v)
            indegree[v] += 1
        q = deque([i for i in range(1, n+1) if indegree[i] == 0])
        semesters = 0
        taken = 0
        while q:
            semesters += 1
            for _ in range(len(q)):
                node = q.popleft()
                taken += 1
                for nei in graph[node]:
                    indegree[nei] -= 1
                    if indegree[nei] == 0:
                        q.append(nei)
        return semesters if taken == n else -1

class Solution:
    def tribonacci(self, n: int) -> int:
        if n == 0: return 0
        if n <= 2: return 1
        a, b, c = 0, 1, 1
        for _ in range(n - 2):
            a, b, c = b, c, a + b + c
        return c

class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        res = []
        r, c = 0, 0
        for ch in target:
            idx = ord(ch) - ord('a')
            tr, tc = idx // 5, idx % 5
            # Move up/left before down/right to avoid going out of bounds at 'z'
            if tr < r:
                res.append('U' * (r - tr))
            if tc < c:
                res.append('L' * (c - tc))
            if tr > r:
                res.append('D' * (tr - r))
            if tc > c:
                res.append('R' * (tc - c))
            res.append('!')
            r, c = tr, tc
        return ''.join(res)

class Solution:
    def largest1BorderedSquare(self, grid):
        m, n = len(grid), len(grid[0])
        left = [[0]*n for _ in range(m)]
        top = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    left[i][j] = (left[i][j-1] if j > 0 else 0) + 1
                    top[i][j] = (top[i-1][j] if i > 0 else 0) + 1
        for side in range(min(m, n), 0, -1):
            for i in range(m - side + 1):
                for j in range(n - side + 1):
                    if (left[i][j+side-1] >= side and
                        left[i+side-1][j+side-1] >= side and
                        top[i+side-1][j] >= side and
                        top[i+side-1][j+side-1] >= side):
                        return side * side
        return 0

class Solution:
    def stoneGameII(self, piles):
        from functools import lru_cache
        n = len(piles)
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + piles[i]
        @lru_cache(maxsize=None)
        def dp(i, M):
            if i >= n:
                return 0
            if i + 2 * M >= n:
                return suffix[i]
            res = 0
            for x in range(1, 2 * M + 1):
                res = max(res, suffix[i] - dp(i + x, max(M, x)))
            return res
        return dp(0, 1)

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if text1[i-1] == text2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])
        return dp[m][n]

class Solution:
    def movesToMakeZigzag(self, nums: list[int]) -> int:
        n = len(nums)
        res = [0, 0]
        for i in range(n):
            left = nums[i-1] if i > 0 else float('inf')
            right = nums[i+1] if i < n-1 else float('inf')
            res[i % 2] += max(0, nums[i] - min(left, right) + 1)
        return min(res)

class Solution:
    def btreeGameWinningMove(self, root, n: int, x: int) -> bool:
        self.left_count = self.right_count = 0
        def count(node):
            if not node:
                return 0
            l = count(node.left)
            r = count(node.right)
            if node.val == x:
                self.left_count = l
                self.right_count = r
            return l + r + 1
        count(root)
        parent_count = n - self.left_count - self.right_count - 1
        return max(self.left_count, self.right_count, parent_count) > n // 2

import bisect
class SnapshotArray:
    def __init__(self, length: int):
        self.snaps = [[[0, 0]] for _ in range(length)]
        self.snap_id = 0

    def set(self, index: int, val: int) -> None:
        if self.snaps[index][-1][0] == self.snap_id:
            self.snaps[index][-1][1] = val
        else:
            self.snaps[index].append([self.snap_id, val])

    def snap(self) -> int:
        self.snap_id += 1
        return self.snap_id - 1

    def get(self, index: int, snap_id: int) -> int:
        arr = self.snaps[index]
        i = bisect.bisect_right(arr, [snap_id, float('inf')]) - 1
        return arr[i][1]

import bisect
class Solution:
    def isMajorityElement(self, nums: list[int], target: int) -> bool:
        left = bisect.bisect_left(nums, target)
        right = bisect.bisect_right(nums, target)
        return right - left > len(nums) // 2

class Solution:
    def minSwaps(self, data: list[int]) -> int:
        k = sum(data)
        ones = sum(data[:k])
        max_ones = ones
        for i in range(k, len(data)):
            ones += data[i] - data[i - k]
            max_ones = max(max_ones, ones)
        return k - max_ones

from collections import defaultdict
from itertools import combinations
class Solution:
    def mostVisitedPattern(self, username, timestamp, website):
        visits = defaultdict(list)
        for u, t, w in sorted(zip(username, timestamp, website)):
            visits[u].append(w)
        count = defaultdict(int)
        for sites in visits.values():
            patterns = set(combinations(sites, 3))
            for p in patterns:
                count[p] += 1
        return list(max(count, key=lambda x: (count[x], [-ord(c) for c in ''.join(x)])))

class Solution:
    def canConvert(self, str1: str, str2: str) -> bool:
        if str1 == str2:
            return True
        mapping = {}
        for c1, c2 in zip(str1, str2):
            if c1 in mapping and mapping[c1] != c2:
                return False
            mapping[c1] = c2
        return len(set(str2)) < 26

class Solution:
    def dayOfYear(self, date: str) -> int:
        y, m, d = map(int, date.split('-'))
        days = [31,28,31,30,31,30,31,31,30,31,30,31]
        if (y % 4 == 0 and y % 100 != 0) or y % 400 == 0:
            days[1] = 29
        return sum(days[:m-1]) + d

class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (target + 1)
        dp[0] = 1
        for i in range(n):
            new_dp = [0] * (target + 1)
            for j in range(1, target + 1):
                for face in range(1, k + 1):
                    if j - face >= 0:
                        new_dp[j] = (new_dp[j] + dp[j - face]) % MOD
            dp = new_dp
        return dp[target]

