from collections import defaultdict
class MajorityChecker:
    def __init__(self, arr: list[int]):
        self.arr = arr
        self.pos = defaultdict(list)
        for i, v in enumerate(arr):
            self.pos[v].append(i)

    def query(self, left: int, right: int, threshold: int) -> int:
        for _ in range(20):
            idx = random.randint(left, right)
            candidate = self.arr[idx]
            lo = bisect.bisect_left(self.pos[candidate], left)
            hi = bisect.bisect_right(self.pos[candidate], right)
            if hi - lo >= threshold:
                return candidate
        return -1

from collections import Counter
class Solution:
    def countCharacters(self, words: list[str], chars: str) -> int:
        char_count = Counter(chars)
        res = 0
        for word in words:
            word_count = Counter(word)
            if all(word_count[c] <= char_count[c] for c in word_count):
                res += len(word)
        return res

from collections import deque
class Solution:
    def maxLevelSum(self, root) -> int:
        queue = deque([root])
        max_sum = float('-inf')
        res = level = 0
        while queue:
            level += 1
            curr_sum = 0
            for _ in range(len(queue)):
                node = queue.popleft()
                curr_sum += node.val
                if node.left: queue.append(node.left)
                if node.right: queue.append(node.right)
            if curr_sum > max_sum:
                max_sum = curr_sum
                res = level
        return res

from collections import deque
class Solution:
    def maxDistance(self, grid: list[list[int]]) -> int:
        n = len(grid)
        queue = deque()
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    queue.append((i, j))
        if len(queue) == 0 or len(queue) == n * n:
            return -1
        dist = -1
        while queue:
            dist += 1
            for _ in range(len(queue)):
                x, y = queue.popleft()
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0:
                        grid[nx][ny] = 1
                        queue.append((nx, ny))
        return dist

class Solution:
    def lastSubstring(self, s: str) -> str:
        i, j, k = 0, 1, 0
        n = len(s)
        while j + k < n:
            if s[i+k] == s[j+k]:
                k += 1
            elif s[i+k] > s[j+k]:
                j = j + k + 1
                k = 0
            else:
                i = max(i + k + 1, j)
                if i == j:
                    j += 1
                k = 0
        return s[i:]

class Solution:
    def calculateTime(self, keyboard: str, word: str) -> int:
        pos = {c: i for i, c in enumerate(keyboard)}
        res = pos[word[0]]
        for i in range(1, len(word)):
            res += abs(pos[word[i]] - pos[word[i-1]])
        return res

class FileSystem:
    def __init__(self):
        self.paths = {'': -1}

    def createPath(self, path: str, value: int) -> bool:
        if path in self.paths or path == '':
            return False
        parent = path[:path.rfind('/')]
        if parent not in self.paths:
            return False
        self.paths[path] = value
        return True

    def get(self, path: str) -> int:
        return self.paths.get(path, -1)

class Solution:
    def minCostToSupplyWater(self, n: int, wells: list[int], pipes: list[list[int]]) -> int:
        edges = []
        for i, w in enumerate(wells):
            edges.append((w, 0, i + 1))
        for a, b, cost in pipes:
            edges.append((cost, a, b))
        edges.sort()
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        total = 0
        for cost, u, v in edges:
            pu, pv = find(u), find(v)
            if pu != pv:
                parent[pu] = pv
                total += cost
        return total

class Solution:
    def invalidTransactions(self, transactions: list[str]) -> list[str]:
        parsed = []
        for t in transactions:
            name, time, amount, city = t.split(',')
            parsed.append((name, int(time), int(amount), city))
        res = []
        for i, (n1, t1, a1, c1) in enumerate(parsed):
            if a1 > 1000:
                res.append(transactions[i])
                continue
            for j, (n2, t2, a2, c2) in enumerate(parsed):
                if i != j and n1 == n2 and abs(t1 - t2) <= 60 and c1 != c2:
                    res.append(transactions[i])
                    break
        return res

import bisect
class Solution:
    def numSmallerByFrequency(self, queries: list[str], words: list[str]) -> list[int]:
        def f(s):
            return s.count(min(s))
        word_f = sorted(f(w) for w in words)
        res = []
        for q in queries:
            fq = f(q)
            res.append(len(word_f) - bisect.bisect_right(word_f, fq))
        return res

import heapq
class DinnerPlates:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.stacks = []
        self.available = []  # min-heap of indices with space

    def push(self, val: int) -> None:
        while self.available and self.available[0] < len(self.stacks) and len(self.stacks[self.available[0]]) == self.cap:
            heapq.heappop(self.available)
        if not self.available or self.available[0] >= len(self.stacks):
            self.stacks.append([])
            heapq.heappush(self.available, len(self.stacks) - 1)
        idx = self.available[0]
        self.stacks[idx].append(val)
        if len(self.stacks[idx]) == self.cap:
            heapq.heappop(self.available)

    def pop(self) -> int:
        while self.stacks and not self.stacks[-1]:
            self.stacks.pop()
        if not self.stacks:
            return -1
        return self.popAtStack(len(self.stacks) - 1)

    def popAtStack(self, index: int) -> int:
        if index >= len(self.stacks) or not self.stacks[index]:
            return -1
        heapq.heappush(self.available, index)
        return self.stacks[index].pop()

class Solution:
    def numPrimeArrangements(self, n: int) -> int:
        MOD = 10**9 + 7
        def count_primes(n):
            if n < 2: return 0
            sieve = [True] * (n + 1)
            sieve[0] = sieve[1] = False
            for i in range(2, int(n**0.5) + 1):
                if sieve[i]:
                    for j in range(i*i, n+1, i):
                        sieve[j] = False
            return sum(sieve)
        p = count_primes(n)
        def factorial(k):
            res = 1
            for i in range(2, k+1):
                res = res * i % MOD
            return res
        return factorial(p) * factorial(n - p) % MOD

class Solution:
    def canMakePaliQueries(self, s: str, queries: list[list[int]]) -> list[bool]:
        n = len(s)
        prefix = [0] * (n + 1)
        for i, c in enumerate(s):
            prefix[i+1] = prefix[i] ^ (1 << (ord(c) - ord('a')))
        res = []
        for l, r, k in queries:
            diff = prefix[r+1] ^ prefix[l]
            odd_count = bin(diff).count('1')
            res.append(odd_count // 2 <= k)
        return res

from collections import Counter
class Solution:
    def findNumOfValidWords(self, words: list[str], puzzles: list[str]) -> list[int]:
        word_mask_count = Counter()
        for word in words:
            mask = 0
            for c in word:
                mask |= 1 << (ord(c) - ord('a'))
            word_mask_count[mask] += 1
        res = []
        for puzzle in puzzles:
            total = 0
            first = 1 << (ord(puzzle[0]) - ord('a'))
            # Enumerate subsets of puzzle mask that include first letter
            puzzle_mask = 0
            for c in puzzle:
                puzzle_mask |= 1 << (ord(c) - ord('a'))
            sub = puzzle_mask
            while sub:
                if sub & first:
                    total += word_mask_count[sub]
                sub = (sub - 1) & puzzle_mask
            res.append(total)
        return res

class Solution:
    def countLetters(self, s: str) -> int:
        res = 0
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            L = j - i
            res += L * (L + 1) // 2
            i = j
        return res

class Solution:
    def beforeAndAfterPuzzles(self, phrases: list[str]) -> list[str]:
        words = [p.split() for p in phrases]
        res = set()
        for i in range(len(phrases)):
            for j in range(len(phrases)):
                if i != j and words[i][-1] == words[j][0]:
                    merged = ' '.join(words[i] + words[j][1:])
                    res.add(merged)
        return sorted(res)

import bisect
class Solution:
    def shortestDistanceColor(self, colors: list[int], queries: list[list[int]]) -> list[int]:
        positions = {1: [], 2: [], 3: []}
        for i, c in enumerate(colors):
            positions[c].append(i)
        res = []
        for idx, color in queries:
            arr = positions[color]
            if not arr:
                res.append(-1)
                continue
            pos = bisect.bisect_left(arr, idx)
            dist = float('inf')
            if pos < len(arr):
                dist = min(dist, arr[pos] - idx)
            if pos > 0:
                dist = min(dist, idx - arr[pos-1])
            res.append(dist)
        return res

class Solution:
    def maximumNumberOfOnes(self, width: int, height: int, sideLength: int, maxOnes: int) -> int:
        counts = []
        for i in range(sideLength):
            for j in range(sideLength):
                # How many times position (i,j) in the tile appears in the matrix
                rows = (height - 1 - i) // sideLength + 1
                cols = (width - 1 - j) // sideLength + 1
                counts.append(rows * cols)
        counts.sort(reverse=True)
        return sum(counts[:maxOnes])

class Solution:
    def distanceBetweenBusStops(self, distance: list[int], start: int, destination: int) -> int:
        if start > destination:
            start, destination = destination, start
        clockwise = sum(distance[start:destination])
        return min(clockwise, sum(distance) - clockwise)

import bisect
class Solution:
    def makeArrayIncreasing(self, arr1: list[int], arr2: list[int]) -> int:
        arr2 = sorted(set(arr2))
        # dp: {last_value: min_operations}
        dp = {-1: 0}
        for num in arr1:
            new_dp = {}
            for prev, ops in dp.items():
                # Option 1: keep num if num > prev
                if num > prev:
                    if num not in new_dp or new_dp[num] > ops:
                        new_dp[num] = ops
                # Option 2: replace with smallest arr2 value > prev
                idx = bisect.bisect_right(arr2, prev)
                if idx < len(arr2):
                    val = arr2[idx]
                    if val not in new_dp or new_dp[val] > ops + 1:
                        new_dp[val] = ops + 1
            dp = new_dp
            if not dp:
                return -1
        return min(dp.values())

import threading
from collections import deque
class BoundedBlockingQueue:
    def __init__(self, capacity: int):
        self.queue = deque()
        self.cap = capacity
        self.lock = threading.Lock()
        self.not_full = threading.Condition(self.lock)
        self.not_empty = threading.Condition(self.lock)

    def enqueue(self, element: int) -> None:
        with self.not_full:
            while len(self.queue) >= self.cap:
                self.not_full.wait()
            self.queue.append(element)
            self.not_empty.notify()

    def dequeue(self) -> int:
        with self.not_empty:
            while not self.queue:
                self.not_empty.wait()
            val = self.queue.popleft()
            self.not_full.notify()
            return val

    def size(self) -> int:
        with self.lock:
            return len(self.queue)

