class Solution:
    def reverseParentheses(self, s: str) -> str:
        stack = []
        for c in s:
            if c == ')':
                temp = []
                while stack[-1] != '(':
                    temp.append(stack.pop())
                stack.pop()  # remove '('
                stack.extend(temp)
            else:
                stack.append(c)
        return ''.join(stack)

class Solution:
    def kConcatenationMaxSum(self, arr: list[int], k: int) -> int:
        MOD = 10**9 + 7
        def kadane(a):
            max_sum = cur = 0
            for x in a:
                cur = max(0, cur + x)
                max_sum = max(max_sum, cur)
            return max_sum
        single = kadane(arr)
        if k == 1:
            return single % MOD
        double = kadane(arr + arr)
        total = sum(arr)
        if total > 0:
            return (double + (k - 2) * total) % MOD
        return double % MOD

class Solution:
    def criticalConnections(self, n: int, connections: list[list[int]]) -> list[list[int]]:
        graph = [[] for _ in range(n)]
        for u, v in connections:
            graph[u].append(v)
            graph[v].append(u)
        disc = [-1] * n
        low = [0] * n
        res = []
        self.timer = 0
        def dfs(u, parent):
            disc[u] = low[u] = self.timer
            self.timer += 1
            for v in graph[u]:
                if v == parent:
                    continue
                if disc[v] == -1:
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        res.append([u, v])
                else:
                    low[u] = min(low[u], disc[v])
        dfs(0, -1)
        return res

import threading
class FizzBuzz:
    def __init__(self, n: int):
        self.n = n
        self.current = 1
        self.lock = threading.Lock()
        self.cond = threading.Condition(self.lock)

    def _run(self, check_fn, output_fn):
        while True:
            with self.cond:
                while self.current <= self.n and not check_fn(self.current):
                    self.cond.wait()
                if self.current > self.n:
                    return
                output_fn(self.current)
                self.current += 1
                self.cond.notify_all()

    def fizz(self, printFizz):
        self._run(lambda x: x%3==0 and x%5!=0, lambda x: printFizz())

    def buzz(self, printBuzz):
        self._run(lambda x: x%5==0 and x%3!=0, lambda x: printBuzz())

    def fizzbuzz(self, printFizzBuzz):
        self._run(lambda x: x%15==0, lambda x: printFizzBuzz())

    def number(self, printNumber):
        self._run(lambda x: x%3!=0 and x%5!=0, lambda x: printNumber(x))

