from collections import deque
class Solution:
    def minKnightMoves(self, x: int, y: int) -> int:
        x, y = abs(x), abs(y)
        queue = deque([(0, 0, 0)])
        visited = {(0, 0)}
        while queue:
            cx, cy, steps = queue.popleft()
            if cx == x and cy == y:
                return steps
            for dx, dy in [(1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2)]:
                nx, ny = cx+dx, cy+dy
                if (nx, ny) not in visited and nx >= -2 and ny >= -2:
                    visited.add((nx, ny))
                    queue.append((nx, ny, steps+1))
        return -1

import bisect
class Solution:
    def smallestCommonElement(self, mat: list[list[int]]) -> int:
        for val in mat[0]:
            found = True
            for row in mat[1:]:
                idx = bisect.bisect_left(row, val)
                if idx >= len(row) or row[idx] != val:
                    found = False
                    break
            if found:
                return val
        return -1

import heapq
class Solution:
    def minBuildTime(self, blocks: list[int], split: int) -> int:
        heapq.heapify(blocks)
        while len(blocks) > 1:
            heapq.heappop(blocks)
            b = heapq.heappop(blocks)
            heapq.heappush(blocks, b + split)
        return blocks[0]

class Solution:
    def minimumAbsDifference(self, arr: list[int]) -> list[list[int]]:
        arr.sort()
        min_diff = min(arr[i+1] - arr[i] for i in range(len(arr)-1))
        return [[arr[i], arr[i+1]] for i in range(len(arr)-1) if arr[i+1] - arr[i] == min_diff]

import math
class Solution:
    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        def lcm(x, y):
            return x * y // math.gcd(x, y)
        ab, ac, bc = lcm(a,b), lcm(a,c), lcm(b,c)
        abc = lcm(ab, c)
        lo, hi = 1, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            cnt = mid//a + mid//b + mid//c - mid//ab - mid//ac - mid//bc + mid//abc
            if cnt < n:
                lo = mid + 1
            else:
                hi = mid
        return lo

class Solution:
    def smallestStringWithSwaps(self, s: str, pairs):
        n = len(s)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for a, b in pairs:
            pa, pb = find(a), find(b)
            if pa != pb:
                parent[pa] = pb
        from collections import defaultdict
        groups = defaultdict(list)
        for i in range(n):
            groups[find(i)].append(i)
        res = list(s)
        for indices in groups.values():
            chars = sorted(res[i] for i in indices)
            for i, idx in enumerate(sorted(indices)):
                res[idx] = chars[i]
        return ''.join(res)

from collections import defaultdict, deque
class Solution:
    def sortItems(self, n, m, group, beforeItems):
        for i in range(n):
            if group[i] == -1:
                group[i] = m
                m += 1
        group_graph = defaultdict(set)
        group_indeg = defaultdict(int)
        item_graph = defaultdict(set)
        item_indeg = defaultdict(int)
        for i in range(n):
            for prev in beforeItems[i]:
                if group[prev] != group[i]:
                    if i not in group_graph[group[prev]]:
                        group_graph[group[prev]].add(group[i])
                        group_indeg[group[i]] = group_indeg.get(group[i],0)+1
                item_graph[prev].add(i)
                item_indeg[i] = item_indeg.get(i,0)+1
        def topo(nodes, graph, indeg):
            q = deque([x for x in nodes if indeg.get(x,0)==0])
            res = []
            while q:
                x = q.popleft()
                res.append(x)
                for y in graph[x]:
                    indeg[y] -= 1
                    if indeg[y] == 0:
                        q.append(y)
            return res if len(res)==len(nodes) else []
        all_groups = set(range(m))
        group_order = topo(all_groups, group_graph, group_indeg)
        if not group_order:
            return []
        group_items = defaultdict(list)
        for i in range(n):
            group_items[group[i]].append(i)
        res = []
        for g in group_order:
            items = group_items[g]
            order = topo(items, item_graph, item_indeg)
            if len(order) != len(items):
                return []
            res.extend(order)
        return res

import random
class Node:
    def __init__(self, val=-1, right=None, down=None):
        self.val = val
        self.right = right
        self.down = down

class Skiplist:
    def __init__(self):
        self.head = Node()

    def search(self, target: int) -> bool:
        cur = self.head
        while cur:
            while cur.right and cur.right.val < target:
                cur = cur.right
            if cur.right and cur.right.val == target:
                return True
            cur = cur.down
        return False

    def add(self, num: int) -> None:
        stack = []
        cur = self.head
        while cur:
            while cur.right and cur.right.val < num:
                cur = cur.right
            stack.append(cur)
            cur = cur.down
        insert = True
        down = None
        while insert and stack:
            cur = stack.pop()
            cur.right = Node(num, cur.right, down)
            down = cur.right
            insert = random.random() < 0.5
        if insert:
            self.head = Node(-1, None, self.head)

    def erase(self, num: int) -> bool:
        cur = self.head
        found = False
        while cur:
            while cur.right and cur.right.val < num:
                cur = cur.right
            if cur.right and cur.right.val == num:
                found = True
                cur.right = cur.right.right
            cur = cur.down
        return found

