class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        stack = []  # (char, count)
        for c in s:
            if stack and stack[-1][0] == c:
                stack[-1][1] += 1
                if stack[-1][1] == k:
                    stack.pop()
            else:
                stack.append([c, 1])
        return ''.join(c * cnt for c, cnt in stack)

from collections import deque
class Solution:
    def minimumMoves(self, grid) -> int:
        n = len(grid)
        visited = set()
        q = deque([(0, 0, 0, 0)])  # row, col, dir(0=horizontal), steps
        visited.add((0, 0, 0))
        while q:
            r, c, d, steps = q.popleft()
            if (r, c, d) == (n-1, n-2, 0):
                return steps
            if d == 0:  # horizontal
                if c+2 < n and grid[r][c+2] == 0 and (r,c+1,0) not in visited:
                    visited.add((r,c+1,0)); q.append((r,c+1,0,steps+1))
                if r+1 < n and grid[r+1][c] == 0 and grid[r+1][c+1] == 0 and (r+1,c,0) not in visited:
                    visited.add((r+1,c,0)); q.append((r+1,c,0,steps+1))
                if r+1 < n and grid[r+1][c] == 0 and grid[r+1][c+1] == 0 and (r,c,1) not in visited:
                    visited.add((r,c,1)); q.append((r,c,1,steps+1))
            else:  # vertical
                if r+2 < n and grid[r+2][c] == 0 and (r+1,c,1) not in visited:
                    visited.add((r+1,c,1)); q.append((r+1,c,1,steps+1))
                if c+1 < n and grid[r][c+1] == 0 and grid[r+1][c+1] == 0 and (r,c+1,1) not in visited:
                    visited.add((r,c+1,1)); q.append((r,c+1,1,steps+1))
                if c+1 < n and grid[r][c+1] == 0 and grid[r+1][c+1] == 0 and (r,c,0) not in visited:
                    visited.add((r,c,0)); q.append((r,c,0,steps+1))
        return -1

class Solution:
