        res = []
        while i < len(arr1) and j < len(arr2) and k < len(arr3):
            if arr1[i] == arr2[j] == arr3[k]:
                res.append(arr1[i])
                i += 1; j += 1; k += 1
            elif arr1[i] <= arr2[j] and arr1[i] <= arr3[k]:
                i += 1
            elif arr2[j] <= arr3[k]:
                j += 1
            else:
                k += 1
        return res

class Solution:
    def twoSumBSTs(self, root1, root2, target: int) -> bool:
        vals = set()
        def inorder(node):
            if not node: return
            inorder(node.left)
            vals.add(node.val)
            inorder(node.right)
        inorder(root1)
        def search(node):
            if not node: return False
            if target - node.val in vals: return True
            return search(node.left) or search(node.right)
        return search(root2)

from collections import deque
class Solution:
    def countSteppingNumbers(self, low: int, high: int):
        res = []
        if low == 0:
            res.append(0)
        q = deque(range(1, 10))
        while q:
            num = q.popleft()
            if num > high:
                continue
            if num >= low:
                res.append(num)
            last = num % 10
            if last > 0:
                q.append(num * 10 + last - 1)
            if last < 9:
                q.append(num * 10 + last + 1)
        return sorted(res)

class Solution:
    def isValidPalindrome(self, s: str, k: int) -> bool:
        n = len(s)
        dp = [[0]*n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for length in range(2, n+1):
            for i in range(n-length+1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] + 2
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])
        return n - dp[0][n-1] <= k

