        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                r, c = king[0]+dr, king[1]+dc
                while 0 <= r < 8 and 0 <= c < 8:
