class Solution:
    def dieSimulator(self, n: int, rollMax) -> int:
        MOD = 10**9 + 7
        # dp[j][k] = ways ending with face j, k consecutive
        dp = [[0]*16 for _ in range(6)]
        for j in range(6):
            dp[j][1] = 1
        for i in range(1, n):
            ndp = [[0]*16 for _ in range(6)]
            for j in range(6):
                for nj in range(6):
                    if nj == j:
                        for k in range(1, rollMax[j]):
                            if dp[j][k]:
                                ndp[j][k+1] = (ndp[j][k+1] + dp[j][k]) % MOD
                    else:
                        total = sum(dp[j]) % MOD
                        ndp[nj][1] = (ndp[nj][1] + total) % MOD
            dp = ndp
        return sum(sum(row) for row in dp) % MOD

from collections import defaultdict
class Solution:
    def maxEqualFreq(self, nums) -> int:
        count = defaultdict(int)
        freq = defaultdict(int)
        maxf = 0
        res = 0
        for i, x in enumerate(nums):
            if count[x]:
                freq[count[x]] -= 1
            count[x] += 1
            freq[count[x]] += 1
            maxf = max(maxf, count[x])
            n = i + 1
            if maxf == 1:
                res = n
            elif maxf * freq[maxf] == n - 1 and freq[maxf-1] == 0:
                res = n
            elif (maxf-1) * (freq[maxf-1]+1) == n - 1 and freq[maxf] == 1:
                res = n
            elif maxf * freq[maxf] + 1 == n and freq[maxf] == freq.get(1,0) + freq[maxf]:
                res = n
            elif freq[maxf] * maxf == n - 1 and freq[1] == 1:
                res = n
        return res

