class Solution:
    def missingNumber(self, arr) -> int:
        n = len(arr)
        diff = (arr[-1] - arr[0]) // n
        if diff == 0:
            return arr[0]
        for i in range(1, n):
            if arr[i] != arr[0] + i * diff:
                return arr[0] + i * diff
        return arr[0]

