class Solution:
    def maxLength(self, arr) -> int:
        masks = []
        for s in arr:
            mask = 0
            for c in s:
                bit = 1 << (ord(c) - ord('a'))
                if mask & bit:
                    mask = 0
                    break
                mask |= bit
            if mask:
                masks.append((mask, len(s)))
        res = 0
        def dfs(i, cur, length):
            nonlocal res
            res = max(res, length)
            for j in range(i, len(masks)):
                if cur & masks[j][0] == 0:
                    dfs(j + 1, cur | masks[j][0], length + masks[j][1])
        dfs(0, 0, 0)
        return res

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        self.ans = n * m
        heights = [0] * m
        def dfs(heights, cnt):
            if cnt >= self.ans:
                return
            min_h = min(heights)
            if min_h == n:
                self.ans = cnt
                return
            idx = heights.index(min_h)
            end = idx
            while end < m and heights[end] == min_h and end - idx + 1 + min_h <= n:
                end += 1
            for size in range(end - idx, 0, -1):
                new_h = heights[:]
                for j in range(idx, idx + size):
                    new_h[j] += size
                dfs(new_h, cnt + 1)
        dfs(heights, 0)
        return self.ans

