class Solution:
    def treeDiameter(self, edges):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        def bfs(start):
            visited = {start}
            queue = deque([(start, 0)])
            farthest, max_dist = start, 0
            while queue:
                node, dist = queue.popleft()
                if dist > max_dist:
                    max_dist = dist
                    farthest = node
                for nei in graph[node]:
                    if nei not in visited:
                        visited.add(nei)
                        queue.append((nei, dist + 1))
            return farthest, max_dist
        far_node, _ = bfs(0)
        _, diameter = bfs(far_node)
        return diameter

class Solution:
    def minimumMoves(self, arr) -> int:
        n = len(arr)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                dp[i][j] = dp[i+1][j] + 1
                if arr[i] == arr[i+1]:
                    dp[i][j] = min(dp[i][j], dp[i+2][j] + 1 if i+2 <= j else 1)
                for k in range(i+2, j+1):
                    if arr[i] == arr[k]:
                        dp[i][j] = min(dp[i][j], dp[i+1][k-1] + (dp[k+1][j] if k+1 <= j else 0))
        return dp[0][n-1]

