        row1, row2 = [], []
        for s in colsum:
            if s == 2:
                row1.append(1)
                row2.append(1)
                upper -= 1
                lower -= 1
            elif s == 0:
                row1.append(0)
                row2.append(0)
            else:
                if upper >= lower:
                    row1.append(1)
                    row2.append(0)
                    upper -= 1
                else:
                    row1.append(0)
                    row2.append(1)
                    lower -= 1
        if upper != 0 or lower != 0:
            return []
        return [row1, row2]

class Solution:
