        m, n = len(grid), len(grid[0])
        def dfs(i, j):
            if i < 0 or i >= m or j < 0 or j >= n:
                return False
            if grid[i][j] == 1:
                return True
            grid[i][j] = 1
            a = dfs(i+1, j)
            b = dfs(i-1, j)
            c = dfs(i, j+1)
            d = dfs(i, j-1)
            return a and b and c and d
        return sum(dfs(i, j) for i in range(m) for j in range(n) if grid[i][j] == 0)

class Solution:
    def maxScoreWords(self, words, letters, score):
        from collections import Counter
        avail = Counter(letters)
        def dfs(i, cnt):
            if i == len(words):
                return 0
            # skip word i
            res = dfs(i + 1, cnt)
            # take word i
            word_cnt = Counter(words[i])
            if all(cnt[c] >= word_cnt[c] for c in word_cnt):
                s = sum(score[ord(c)-ord('a')] for c in words[i])
                for c in word_cnt:
                    cnt[c] -= word_cnt[c]
                res = max(res, s + dfs(i + 1, cnt))
                for c in word_cnt:
                    cnt[c] += word_cnt[c]
            return res
        return dfs(0, avail)

