        for a, b in intervals:
            if b <= lo or a >= hi:
                res.append([a, b])
            else:
                if a < lo: res.append([a, lo])
                if b > hi: res.append([hi, b])
        return res

class Solution:
    def deleteTreeNodes(self, nodes, parent, value):
        children = [[] for _ in range(nodes)]
        root = -1
        for i in range(nodes):
            if parent[i] == -1: root = i
            else: children[parent[i]].append(i)
        def dfs(node):
            total_sum, total_count = value[node], 1
            for child in children[node]:
                s, c = dfs(child)
                total_sum += s
                total_count += c
            if total_sum == 0: return 0, 0
            return total_sum, total_count
        _, count = dfs(root)
        return count

class Solution:
    def countShips(self, sea, topRight, bottomLeft):
        if bottomLeft[0] > topRight[0] or bottomLeft[1] > topRight[1]:
            return 0
        if not sea.hasShips(topRight, bottomLeft):
            return 0
        if bottomLeft == topRight:
            return 1
        mx = (bottomLeft[0] + topRight[0]) // 2
        my = (bottomLeft[1] + topRight[1]) // 2
        return (self.countShips(sea, [mx, my], bottomLeft) +
                self.countShips(sea, topRight, [mx+1, my+1]) +
                self.countShips(sea, [mx, topRight[1]], [bottomLeft[0], my+1]) +
                self.countShips(sea, [topRight[0], my], [mx+1, bottomLeft[1]]))

class Solution:
    def tictactoe(self, moves):
        rows, cols, diag, anti = [0]*3, [0]*3, 0, 0
        for i, (r, c) in enumerate(moves):
            sign = 1 if i % 2 == 0 else -1
            rows[r] += sign
            cols[c] += sign
            if r == c: diag += sign
            if r + c == 2: anti += sign
            if abs(rows[r])==3 or abs(cols[c])==3 or abs(diag)==3 or abs(anti)==3:
                return 'A' if sign == 1 else 'B'
        return 'Draw' if len(moves) == 9 else 'Pending'

