from collections import deque
class Solution:
    def minFlips(self, mat):
        m, n = len(mat), len(mat[0])
        start = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j]: start |= 1 << (i*n+j)
        if start == 0: return 0
        q = deque([(start, 0)])
        visited = {start}
        while q:
            state, steps = q.popleft()
            for i in range(m):
                for j in range(n):
                    ns = state
                    for di, dj in [(0,0),(0,1),(0,-1),(1,0),(-1,0)]:
                        ni, nj = i+di, j+dj
                        if 0<=ni<m and 0<=nj<n:
                            ns ^= 1 << (ni*n+nj)
                    if ns == 0: return steps+1
                    if ns not in visited:
                        visited.add(ns)
                        q.append((ns, steps+1))
        return -1

