class Solution:
    def maxCandies(self, status, candies, keys, containedBoxes, initialBoxes):
        have_box = set(initialBoxes)
        have_key = set(i for i in range(len(status)) if status[i])
        q = deque([b for b in initialBoxes if b in have_key])
        opened = set(q)
        res = 0
        while q:
            box = q.popleft()
            res += candies[box]
            for k in keys[box]:
                have_key.add(k)
                if k in have_box and k not in opened:
                    opened.add(k)
                    q.append(k)
            for b in containedBoxes[box]:
                have_box.add(b)
                if b in have_key and b not in opened:
                    opened.add(b)
                    q.append(b)
        return res

