        prefix = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                prefix[i+1][j+1] = mat[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]
        res = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                r1, c1 = max(0, i-k), max(0, j-k)
                r2, c2 = min(m-1, i+k), min(n-1, j+k)
