class Solution:
    def minTaps(self, n: int, ranges: List[int]) -> int:
        max_reach = [0] * (n + 1)
        for i, r in enumerate(ranges):
            left = max(0, i - r)
            right = min(n, i + r)
            max_reach[left] = max(max_reach[left], right)
        taps = 0
        cur_end = 0
        far = 0
        for i in range(n + 1):
            if i > far:
                return -1
            far = max(far, max_reach[i])
            if i == cur_end:
                if cur_end >= n:
                    break
                taps += 1
                cur_end = far
        return taps

