        dp[0][0] = 0
        for i in range(1, n + 1):
            for k in range(1, min(i, d) + 1):
                mx = 0
                for j in range(i, k - 1, -1):
                    mx = max(mx, jobDifficulty[j - 1])
                    dp[i][k] = min(dp[i][k], dp[j - 1][k - 1] + mx)
        return dp[n][d]

class Solution:
