class Solution:
    def minJumps(self, arr: List[int]) -> int:
        from collections import defaultdict, deque
        n = len(arr)
        if n == 1:
            return 0
        graph = defaultdict(list)
        for i, v in enumerate(arr):
            graph[v].append(i)
        visited = [False] * n
        visited[0] = True
        q = deque([0])
        steps = 0
        while q:
            steps += 1
            for _ in range(len(q)):
                i = q.popleft()
                for ni in [i-1, i+1] + graph[arr[i]]:
                    if 0 <= ni < n and not visited[ni]:
                        if ni == n - 1:
                            return steps
                        visited[ni] = True
                        q.append(ni)
                graph[arr[i]] = []
        return -1

