class ProductOfNumbers:
    def __init__(self):
        self.prefix = [1]
    def add(self, num: int) -> None:
        if num == 0:
            self.prefix = [1]
        else:
            self.prefix.append(self.prefix[-1] * num)
    def getProduct(self, k: int) -> int:
        if k >= len(self.prefix):
            return 0
        return self.prefix[-1] // self.prefix[-1 - k]

class Solution:
    def maxEvents(self, events: List[List[int]]) -> int:
        import heapq
        events.sort()
        heap = []
        i, n = 0, len(events)
        res = 0
        day = 0
        while i < n or heap:
            if not heap:
                day = events[i][0]
            while i < n and events[i][0] <= day:
                heapq.heappush(heap, events[i][1])
                i += 1
            while heap and heap[0] < day:
                heapq.heappop(heap)
            if heap:
                heapq.heappop(heap)
                res += 1
            day += 1
        return res

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        import heapq
        total = sum(target)
        heap = [-x for x in target]
        heapq.heapify(heap)
        while True:
            mx = -heapq.heappop(heap)
            if mx == 1:
                return True
            rest = total - mx
            if rest == 0 or rest >= mx:
                return False
            if rest == 1:
                return True
            new_val = mx % rest
            if new_val == 0:
                return False
            total = total - mx + new_val
            heapq.heappush(heap, -new_val)

