class Solution:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        from collections import defaultdict, deque
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        prob = [0.0] * (n + 1)
        prob[1] = 1.0
        visited = [False] * (n + 1)
        visited[1] = True
        q = deque([1])
        for _ in range(t):
            for _ in range(len(q)):
                node = q.popleft()
                children = [nb for nb in graph[node] if not visited[nb]]
                if children:
                    for c in children:
                        visited[c] = True
                        prob[c] = prob[node] / len(children)
                        q.append(c)
                    prob[node] = 0
                else:
                    q.append(node)
        return prob[target]

