        res = 0
        for n in nums:
            divisors = set()
            for i in range(1, int(n**0.5) + 1):
                if n % i == 0:
                    divisors.add(i)
                    divisors.add(n // i)
                if len(divisors) > 4:
                    break
            if len(divisors) == 4:
                res += sum(divisors)
        return res

class Solution:
    def hasValidPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        # directions each street connects: (row_diff, col_diff)
        dirs = {
            1: [(0,-1),(0,1)], 2: [(-1,0),(1,0)], 3: [(0,-1),(1,0)],
            4: [(0,1),(1,0)], 5: [(0,-1),(-1,0)], 6: [(0,1),(-1,0)]
        }
        from collections import deque
        visited = set()
        q = deque([(0, 0)])
        visited.add((0, 0))
        while q:
            r, c = q.popleft()
            if r == m-1 and c == n-1: return True
            for dr, dc in dirs[grid[r][c]]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and (nr,nc) not in visited:
                    if (-dr,-dc) in dirs[grid[nr][nc]]:
                        visited.add((nr,nc))
                        q.append((nr,nc))
        return False

class Solution:
    def longestPrefix(self, s: str) -> str:
        n = len(s)
        lps = [0] * n
        length = 0
        i = 1
        while i < n:
            if s[i] == s[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return s[:lps[-1]]

