class Solution:
    def constrainedSubsetSum(self, nums, k):
        from collections import deque
        n = len(nums)
        dp = nums[:]
        dq = deque()
        for i in range(n):
            if dq:
                dp[i] = max(dp[i], dp[i] + dp[dq[0]])
            while dq and dp[dq[-1]] <= dp[i]:
                dq.pop()
            dq.append(i)
            if dq[0] <= i - k:
                dq.popleft()
        return max(dp)

