class FirstUnique:
    def __init__(self, nums):
        from collections import OrderedDict
        self.od = OrderedDict()
        self.seen = set()
        for n in nums:
            self.add(n)
    def showFirstUnique(self):
        if self.od:
            return next(iter(self.od))
        return -1
    def add(self, value):
        if value in self.seen:
            self.od.pop(value, None)
        else:
            self.seen.add(value)
