class Solution:
    def maxDiff(self, num):
        s = str(num)
        # maximize: replace first non-9 digit with 9
        a = s
        for d in s:
            if d != '9':
                a = s.replace(d, '9')
                break
        # minimize: replace to get smallest
        b = s
        if s[0] != '1':
            b = s.replace(s[0], '1')
        else:
            for d in s[1:]:
                if d != '0' and d != '1':
                    b = s.replace(d, '0')
                    break
        return int(a) - int(b)

