        return (first - 1) * (second - 1)

class Solution:
    def maxArea(self, h: int, w: int, horizontalCuts: List[int], verticalCuts: List[int]) -> int:
        MOD = 10**9 + 7
        horizontalCuts.sort()
        verticalCuts.sort()
        max_h = max(horizontalCuts[0], h - horizontalCuts[-1])
        for i in range(1, len(horizontalCuts)):
            max_h = max(max_h, horizontalCuts[i] - horizontalCuts[i-1])
        max_v = max(verticalCuts[0], w - verticalCuts[-1])
        for i in range(1, len(verticalCuts)):
            max_v = max(max_v, verticalCuts[i] - verticalCuts[i-1])
        return (max_h * max_v) % MOD

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        graph = [[] for _ in range(n)]
        roads = set()
        for u, v in connections:
            graph[u].append(v)
            graph[v].append(u)
            roads.add((u, v))
        from collections import deque
        q = deque([0])
        visited = {0}
        count = 0
        while q:
            node = q.popleft()
            for nei in graph[node]:
                if nei not in visited:
                    visited.add(nei)
                    if (node, nei) in roads:
                        count += 1
                    q.append(nei)
        return count

class Solution:
    def getProbability(self, balls: List[int]) -> float:
        from math import comb, factorial
        n = sum(balls) // 2
        total = [0]
        valid = [0]
        def dfs(i, cnt1, cnt2, d1, d2):
            if cnt1 > n or cnt2 > n:
                return
            if i == len(balls):
                if cnt1 == cnt2 == n:
                    ways = 1
                    total[0] += ways
                    if d1 == d2:
                        valid[0] += ways
                return
            for k in range(balls[i] + 1):
                w = comb(balls[i], k)
                nd1 = d1 + (1 if k > 0 else 0)
                nd2 = d2 + (1 if balls[i] - k > 0 else 0)
                # Multiply combinatorial weight later
                dfs(i + 1, cnt1 + k, cnt2 + balls[i] - k, nd1, nd2)
        # Use multinomial approach
        from functools import lru_cache
        k = len(balls)
        res_valid = 0
        res_total = 0
        def backtrack(i, s1, s2, d1, d2, prob):
            nonlocal res_valid, res_total
            if s1 > n or s2 > n:
                return
            if i == k:
                if s1 == n and s2 == n:
                    res_total += prob
                    if d1 == d2:
                        res_valid += prob
                return
            for j in range(balls[i] + 1):
                p = comb(balls[i], j)
                backtrack(i+1, s1+j, s2+balls[i]-j,
                         d1+(1 if j>0 else 0), d2+(1 if balls[i]-j>0 else 0),
                         prob * p)
        backtrack(0, 0, 0, 0, 0, 1)
        return res_valid / res_total

class Solution:
    def getLonelyNodes(self, root: TreeNode) -> List[int]:
        res = []
        def dfs(node):
            if not node:
                return
            if node.left and not node.right:
                res.append(node.left.val)
            if node.right and not node.left:
                res.append(node.right.val)
            dfs(node.left)
            dfs(node.right)
        dfs(root)
        return res

