        def clone(node):
            if not node:
                return None
            if node in mapping:
                return mapping[node]
            copy = NodeCopy(node.val)
            mapping[node] = copy
            copy.left = clone(node.left)
            copy.right = clone(node.right)
            copy.random = clone(node.random)
            return copy
        return clone(root)

