        res = []
        for name in names:
            if name not in used:
                used[name] = 1
                res.append(name)
            else:
                k = used[name]
                new_name = f"{name}({k})"
                while new_name in used:
                    k += 1
                    new_name = f"{name}({k})"
                used[name] = k + 1
