        dirs = {'N':(0,1),'S':(0,-1),'E':(1,0),'W':(-1,0)}
        for d in path:
            dx, dy = dirs[d]
            x, y = x + dx, y + dy
            if (x, y) in visited:
                return True
            visited.add((x, y))
        return False

class Solution:
