class Solution:
    def numSubmat(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        # width[i][j] = consecutive ones ending at (i,j)
        width = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1:
                    width[i][j] = (width[i][j-1] + 1) if j > 0 else 1
        ans = 0
        for i in range(m):
            for j in range(n):
                min_w = float('inf')
                for k in range(i, -1, -1):
                    if width[k][j] == 0:
                        break
                    min_w = min(min_w, width[k][j])
                    ans += min_w
        return ans

class Solution:
    def minInteger(self, num: str, k: int) -> str:
        from collections import deque
        n = len(num)
        # BIT to count how many elements have been moved out before index i
        tree = [0] * (n + 1)
        def update(i):
            i += 1
            while i <= n:
                tree[i] += 1
                i += i & (-i)
        def query(i):
            i += 1
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s
        queues = [deque() for _ in range(10)]
        for i, ch in enumerate(num):
            queues[int(ch)].append(i)
        res = []
        for _ in range(n):
            for d in range(10):
                if not queues[d]:
                    continue
                idx = queues[d][0]
                cost = idx - query(idx)
                if cost <= k:
                    k -= cost
                    queues[d].popleft()
                    update(idx)
                    res.append(str(d))
                    break
        return ''.join(res)

