class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start_node: int, end_node: int) -> float:
        import heapq
        from collections import defaultdict
        graph = defaultdict(list)
        for (u, v), p in zip(edges, succProb):
            graph[u].append((v, p))
            graph[v].append((u, p))
        dist = [0.0] * n
        dist[start_node] = 1.0
        heap = [(-1.0, start_node)]
        while heap:
            neg_prob, u = heapq.heappop(heap)
            prob = -neg_prob
            if u == end_node:
                return prob
            if prob < dist[u]:
                continue
            for v, w in graph[u]:
                new_prob = prob * w
                if new_prob > dist[v]:
                    dist[v] = new_prob
                    heapq.heappush(heap, (-new_prob, v))
        return 0.0

class Solution:
    def getMinDistSum(self, positions: List[List[int]]) -> float:
        x = sum(p[0] for p in positions) / len(positions)
        y = sum(p[1] for p in positions) / len(positions)
        decay = 0.5
        step = 1.0
        for _ in range(100):
            for _ in range(100):
                gx, gy = 0, 0
                for px, py in positions:
                    d = ((x-px)**2 + (y-py)**2)**0.5
                    if d > 1e-7:
                        gx += (x-px)/d
                        gy += (y-py)/d
                nx, ny = x - step*gx, y - step*gy
                if sum(((nx-px)**2+(ny-py)**2)**0.5 for px,py in positions) < sum(((x-px)**2+(y-py)**2)**0.5 for px,py in positions):
                    x, y = nx, ny
                    break
            step *= decay
        return sum(((x-px)**2+(y-py)**2)**0.5 for px,py in positions)

class Solution:
    def moveSubTree(self, root: 'Node', p: 'Node', q: 'Node') -> 'Node':
        # Find parents
        dummy = Node(0, [root])
        parent = {}
        def dfs(node, par):
            parent[node] = par
            for child in node.children:
                dfs(child, node)
        dfs(root, dummy)
        if q in self.getSubtree(p):
            # q is in p's subtree - remove p from its parent, add p as child of q
            parent[q].children.remove(q)
            parent[p].children.remove(p)
            q.children.append(p)
            parent[q].children.append(q) if parent[q] != dummy else None
        else:
            parent[q].children.remove(q)
            p.children.append(q)
        return dummy.children[0]

