            total += new
            empty = empty % numExchange + new
        return total

class Solution:
    def countSubTrees(self, n: int, edges: List[List[int]], labels: str) -> List[int]:
        from collections import defaultdict
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        ans = [0] * n
        def dfs(node, parent):
            count = [0] * 26
            idx = ord(labels[node]) - ord('a')
            count[idx] = 1
            for nei in graph[node]:
                if nei != parent:
                    child_count = dfs(nei, node)
                    for i in range(26):
                        count[i] += child_count[i]
            ans[node] = count[idx]
            return count
        dfs(0, -1)
        return ans

class Solution:
    def maxNumOfSubstrings(self, s: str) -> List[str]:
        n = len(s)
        first = [n] * 26
        last = [-1] * 26
        for i, ch in enumerate(s):
            c = ord(ch) - ord('a')
            first[c] = min(first[c], i)
            last[c] = max(last[c], i)
        def getRight(i):
            right = last[ord(s[i]) - ord('a')]
            j = i
            while j <= right:
                c = ord(s[j]) - ord('a')
                if first[c] < i:
                    return -1
                right = max(right, last[c])
                j += 1
            return right
        res = []
        prev_right = -1
        for i in range(n):
            if i != first[ord(s[i]) - ord('a')]:
                continue
            right = getRight(i)
            if right == -1:
                continue
            if i > prev_right:
                res.append('')
            prev_right = right
            res[-1] = s[i:right+1]
        return res

