class Solution:
    def diameter(self, root: 'Node') -> int:
        self.ans = 0
        def dfs(node):
            if not node:
                return 0
            top1 = top2 = 0
            for child in node.children:
                d = dfs(child)
                if d >= top1:
                    top2 = top1
                    top1 = d
                elif d > top2:
                    top2 = d
            self.ans = max(self.ans, top1 + top2)
            return top1 + 1
        dfs(root)
        return self.ans

class Solution:
    def countOdds(self, low: int, high: int) -> int:
