class Solution:
    def numOfSubarrays(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        odd = even = 0
        even = 1  # prefix sum 0 is even
        prefix = 0
        ans = 0
        for num in arr:
            prefix += num
            if prefix % 2 == 1:
                ans += even
                odd += 1
            else:
                ans += odd
                even += 1
        return ans % MOD

class Solution:
    def numSplits(self, s: str) -> int:
        from collections import Counter
        right = Counter(s)
        left = Counter()
        ans = 0
        for ch in s:
            left[ch] += 1
            right[ch] -= 1
            if right[ch] == 0:
                del right[ch]
            if len(left) == len(right):
                ans += 1
        return ans

