class Solution:
    def countPairs(self, root: TreeNode, distance: int) -> int:
        self.ans = 0
        def dfs(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [1]
            left = dfs(node.left)
            right = dfs(node.right)
            for l in left:
                for r in right:
                    if l + r <= distance:
                        self.ans += 1
            return [d + 1 for d in left + right if d + 1 < distance]
        dfs(root)
        return self.ans

class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache
        n = len(s)
        def encode_len(count):
            if count == 0: return 0
            if count == 1: return 1
            if count < 10: return 2
            if count < 100: return 3
            return 4
        @lru_cache(None)
        def dp(i, k):
            if k < 0:
                return float('inf')
            if i >= n:
                return 0
            # Option 1: delete s[i]
            res = dp(i + 1, k - 1)
            # Option 2: keep s[i] and some following same chars
            count = 0
            deletes = 0
            for j in range(i, n):
                if s[j] == s[i]:
                    count += 1
                else:
                    deletes += 1
                if deletes > k:
                    break
                res = min(res, encode_len(count) + dp(j + 1, k - deletes))
            return res
        return dp(0, k)

class Solution:
    def getIndex(self, reader: 'ArrayReader') -> int:
        left, right = 0, reader.length() - 1
        while left < right:
            mid = (left + right) // 2
            length = right - left + 1
            if length % 2 == 0:
                cmp = reader.compareSub(left, mid, mid + 1, right)
            else:
                cmp = reader.compareSub(left, mid, mid, right)
            if cmp == 1:
                right = mid
            elif cmp == -1:
                left = mid + 1 if length % 2 == 0 else mid
            else:
                return mid
        return left

class Solution:
    def countGoodTriplets(self, arr: List[int], a: int, b: int, c: int) -> int:
        n = len(arr)
        count = 0
        for i in range(n):
            for j in range(i+1, n):
                if abs(arr[i]-arr[j]) > a:
                    continue
                for k in range(j+1, n):
                    if abs(arr[j]-arr[k]) <= b and abs(arr[i]-arr[k]) <= c:
                        count += 1
        return count

class Solution:
    def getWinner(self, arr: List[int], k: int) -> int:
