class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()
        def canPlace(min_dist):
            count = 1
            last = position[0]
            for i in range(1, len(position)):
                if position[i] - last >= min_dist:
                    count += 1
                    last = position[i]
            return count >= m
        left, right = 1, position[-1] - position[0]
        while left <= right:
            mid = (left + right) // 2
            if canPlace(mid):
                left = mid + 1
            else:
                right = mid - 1
        return right

