class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        m, n = len(grid), len(grid[0])
        visited = [[False]*n for _ in range(m)]
        def dfs(x, y, px, py, ch):
            visited[x][y] = True
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0<=nx<m and 0<=ny<n and grid[nx][ny]==ch and (nx,ny)!=(px,py):
                    if visited[nx][ny]:
                        return True
                    if dfs(nx, ny, x, y, ch):
                        return True
            return False
        import sys
        sys.setrecursionlimit(500000)
        for i in range(m):
            for j in range(n):
                if not visited[i][j]:
                    if dfs(i, j, -1, -1, grid[i][j]):
                        return True
        return False

