class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        def count_islands(g):
            seen = set()
            count = 0
            for i in range(len(g)):
                for j in range(len(g[0])):
                    if g[i][j] == 1 and (i, j) not in seen:
                        count += 1
                        stack = [(i, j)]
                        seen.add((i, j))
                        while stack:
                            x, y = stack.pop()
                            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                                nx, ny = x+dx, y+dy
                                if 0<=nx<len(g) and 0<=ny<len(g[0]) and g[nx][ny]==1 and (nx,ny) not in seen:
                                    seen.add((nx, ny))
                                    stack.append((nx, ny))
            return count
        if count_islands(grid) != 1:
            return 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    if count_islands(grid) != 1:
                        return 1
                    grid[i][j] = 1
        return 2

class Solution:
    def numOfWays(self, nums: List[int]) -> int:
        from math import comb
        MOD = 10**9 + 7
        def solve(arr):
            if len(arr) <= 2:
                return 1
            root = arr[0]
            left = [x for x in arr if x < root]
            right = [x for x in arr if x > root]
            return comb(len(left) + len(right), len(left)) * solve(left) % MOD * solve(right) % MOD
        return (solve(nums) - 1) % MOD

class SparseVector:
    def __init__(self, nums: List[int]):
        self.nonzero = {i: v for i, v in enumerate(nums) if v != 0}
    def dotProduct(self, vec: 'SparseVector') -> int:
        a, b = self.nonzero, vec.nonzero
        if len(a) > len(b):
            a, b = b, a
        return sum(v * b[i] for i, v in a.items() if i in b)

class Solution:
    def diagonalSum(self, mat: List[List[int]]) -> int:
        n = len(mat)
        total = 0
        for i in range(n):
            total += mat[i][i] + mat[i][n - 1 - i]
        if n % 2 == 1:
            total -= mat[n // 2][n // 2]
        return total

class Solution:
    def numWays(self, s: str) -> int:
        MOD = 10**9 + 7
        ones = s.count('1')
        n = len(s)
        if ones == 0:
            return (n - 1) * (n - 2) // 2 % MOD
        if ones % 3 != 0:
            return 0
        target = ones // 3
        count = 0
        gap1 = gap2 = 0
        for c in s:
            if c == '1':
                count += 1
            if count == target:
                gap1 += 1
            elif count == 2 * target:
                gap2 += 1
        return gap1 * gap2 % MOD

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        left = 0
        while left < n - 1 and arr[left] <= arr[left + 1]:
            left += 1
        if left == n - 1:
            return 0
        right = n - 1
        while right > 0 and arr[right - 1] <= arr[right]:
            right -= 1
        res = min(n - left - 1, right)
        i, j = 0, right
        while i <= left and j < n:
            if arr[i] <= arr[j]:
                res = min(res, j - i - 1)
                i += 1
            else:
                j += 1
        return res

class Solution:
    def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:
        MOD = 10**9 + 7
        from functools import lru_cache
        n = len(locations)
        @lru_cache(maxsize=None)
        def dp(city, remaining):
            if remaining < 0:
                return 0
            res = 1 if city == finish else 0
            for next_city in range(n):
                if next_city != city:
                    cost = abs(locations[city] - locations[next_city])
                    if cost <= remaining:
                        res = (res + dp(next_city, remaining - cost)) % MOD
            return res
        return dp(start, fuel)

