class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        from collections import Counter
        def count_pairs(arr, target):
            cnt = Counter()
            res = 0
            for num in arr:
                if target % num == 0:
                    res += cnt[target // num]
                cnt[num] += 1
            return res
        result = 0
        for x in nums1:
            result += count_pairs(nums2, x * x)
        for x in nums2:
            result += count_pairs(nums1, x * x)
        return result

class Solution:
    def maxNumEdgesToRemove(self, n: int, edges: List[List[int]]) -> int:
        class UF:
            def __init__(self, n):
                self.parent = list(range(n + 1))
                self.rank = [0] * (n + 1)
                self.components = n
            def find(self, x):
                while self.parent[x] != x:
                    self.parent[x] = self.parent[self.parent[x]]
                    x = self.parent[x]
                return x
            def union(self, x, y):
                px, py = self.find(x), self.find(y)
                if px == py: return False
                if self.rank[px] < self.rank[py]: px, py = py, px
                self.parent[py] = px
                if self.rank[px] == self.rank[py]: self.rank[px] += 1
                self.components -= 1
                return True
        alice, bob = UF(n), UF(n)
        removed = 0
        for t, u, v in edges:
            if t == 3:
                a = alice.union(u, v)
                b = bob.union(u, v)
                if not a and not b: removed += 1
        for t, u, v in edges:
            if t == 1:
                if not alice.union(u, v): removed += 1
            elif t == 2:
                if not bob.union(u, v): removed += 1
        if alice.components != 1 or bob.components != 1: return -1
        return removed

class Solution:
    def maxBoxesInWarehouse(self, boxes: List[int], warehouse: List[int]) -> int:
        n = len(warehouse)
        left_h = warehouse[:]
        right_h = warehouse[:]
        for i in range(1, n):
            left_h[i] = min(left_h[i], left_h[i-1])
        for i in range(n-2, -1, -1):
            right_h[i] = min(right_h[i], right_h[i+1])
        effective = [max(left_h[i], right_h[i]) for i in range(n)]
        effective.sort()
        boxes.sort()
        count = 0
        j = 0
        for h in effective:
            if j < len(boxes) and boxes[j] <= h:
                count += 1
                j += 1
        return count

class Solution:
    def numSpecial(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        row_sum = [sum(row) for row in mat]
        col_sum = [sum(mat[i][j] for i in range(m)) for j in range(n)]
        count = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1 and row_sum[i] == 1 and col_sum[j] == 1:
                    count += 1
        return count

class Solution:
    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        rank = [[0]*n for _ in range(n)]
        for i in range(n):
            for j, p in enumerate(preferences[i]):
                rank[i][p] = j
        partner = [0] * n
        for x, y in pairs:
            partner[x] = y
            partner[y] = x
        count = 0
        for x in range(n):
            y = partner[x]
            for u in preferences[x]:
                if u == y:
                    break
                v = partner[u]
                if rank[u][x] < rank[u][v]:
                    count += 1
                    break
        return count

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        import heapq
        n = len(points)
        visited = [False] * n
        min_heap = [(0, 0)]
        total = 0
        count = 0
        while count < n:
            cost, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total += cost
            count += 1
            for v in range(n):
                if not visited[v]:
                    dist = abs(points[u][0]-points[v][0]) + abs(points[u][1]-points[v][1])
                    heapq.heappush(min_heap, (dist, v))
        return total

class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        from collections import deque
        pos = [deque() for _ in range(10)]
        for i, c in enumerate(s):
            pos[int(c)].append(i)
        for c in t:
            d = int(c)
            if not pos[d]:
                return False
            target = pos[d][0]
            for smaller in range(d):
                if pos[smaller] and pos[smaller][0] < target:
                    return False
            pos[d].popleft()
        return True

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        target = sum(nums) % p
        if target == 0:
            return 0
        prefix_mod = {0: -1}
        cur = 0
        res = len(nums)
        for i, num in enumerate(nums):
            cur = (cur + num) % p
            need = (cur - target) % p
            if need in prefix_mod:
                res = min(res, i - prefix_mod[need])
            prefix_mod[cur] = i
        return res if res < len(nums) else -1

class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:
        from collections import defaultdict, deque
        m, n = len(targetGrid), len(targetGrid[0])
        colors = defaultdict(lambda: [m, n, -1, -1])
        for i in range(m):
            for j in range(n):
                c = targetGrid[i][j]
                colors[c][0] = min(colors[c][0], i)
                colors[c][1] = min(colors[c][1], j)
                colors[c][2] = max(colors[c][2], i)
                colors[c][3] = max(colors[c][3], j)
        graph = defaultdict(set)
        indegree = defaultdict(int)
        for c in colors:
            indegree.setdefault(c, 0)
        for c, (r1, c1, r2, c2) in colors.items():
            for i in range(r1, r2+1):
                for j in range(c1, c2+1):
                    other = targetGrid[i][j]
                    if other != c and other not in graph[c]:
                        graph[c].add(other)
                        indegree[other] = indegree.get(other, 0) + 1
        queue = deque([c for c in colors if indegree.get(c, 0) == 0])
        count = 0
        while queue:
            c = queue.popleft()
            count += 1
            for nei in graph[c]:
                indegree[nei] -= 1
                if indegree[nei] == 0:
                    queue.append(nei)
        return count == len(colors)

class Solution:
    def reorderSpaces(self, text: str) -> str:
        spaces = text.count(' ')
        words = text.split()
        if len(words) == 1:
            return words[0] + ' ' * spaces
        gap = spaces // (len(words) - 1)
        extra = spaces % (len(words) - 1)
        return (' ' * gap).join(words) + ' ' * extra

class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        seen = set()
        def backtrack(start):
            if start == len(s):
                return 0
            res = -1
            for end in range(start + 1, len(s) + 1):
                sub = s[start:end]
                if sub not in seen:
                    seen.add(sub)
                    nxt = backtrack(end)
                    if nxt >= 0:
                        res = max(res, 1 + nxt)
                    seen.remove(sub)
            return res
        return backtrack(0)

class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])
        mx = [[0]*n for _ in range(m)]
        mn = [[0]*n for _ in range(m)]
        mx[0][0] = mn[0][0] = grid[0][0]
        for i in range(1, m):
            a = mx[i-1][0] * grid[i][0]
            b = mn[i-1][0] * grid[i][0]
            mx[i][0], mn[i][0] = max(a, b), min(a, b)
        for j in range(1, n):
            a = mx[0][j-1] * grid[0][j]
            b = mn[0][j-1] * grid[0][j]
            mx[0][j], mn[0][j] = max(a, b), min(a, b)
        for i in range(1, m):
            for j in range(1, n):
                if grid[i][j] >= 0:
                    mx[i][j] = max(mx[i-1][j], mx[i][j-1]) * grid[i][j]
                    mn[i][j] = min(mn[i-1][j], mn[i][j-1]) * grid[i][j]
                else:
                    mx[i][j] = min(mn[i-1][j], mn[i][j-1]) * grid[i][j]
                    mn[i][j] = max(mx[i-1][j], mx[i][j-1]) * grid[i][j]
        return mx[m-1][n-1] % MOD if mx[m-1][n-1] >= 0 else -1

class Solution:
    def connectTwoGroups(self, cost: List[List[int]]) -> int:
        m, n = len(cost), len(cost[0])
        min_col = [min(cost[i][j] for i in range(m)) for j in range(n)]
        dp = [[float('inf')] * (1 << n) for _ in range(m + 1)]
        dp[0][0] = 0
        for i in range(m):
            for mask in range(1 << n):
                if dp[i][mask] == float('inf'): continue
                for j in range(n):
                    new_mask = mask | (1 << j)
                    dp[i+1][new_mask] = min(dp[i+1][new_mask], dp[i][mask] + cost[i][j])
                    dp[i][new_mask] = min(dp[i][new_mask], dp[i][mask] + cost[i][j])
        res = float('inf')
        for mask in range(1 << n):
            if dp[m][mask] == float('inf'): continue
            val = dp[m][mask]
            for j in range(n):
                if not (mask & (1 << j)):
                    val += min_col[j]
            res = min(res, val)
        return res

class Solution:
    def expTree(self, s: str):
        nums = []
        ops = []
        def precedence(op):
            if op in '+-': return 1
            if op in '*/': return 2
            return 0
        def build():
            right = nums.pop()
            left = nums.pop()
            op = ops.pop()
            node = Node(op)
            node.left = left
            node.right = right
            nums.append(node)
        for c in s:
            if c.isdigit():
                nums.append(Node(c))
            elif c == '(':
                ops.append(c)
            elif c == ')':
                while ops[-1] != '(':
                    build()
                ops.pop()
            else:
                while ops and ops[-1] != '(' and precedence(ops[-1]) >= precedence(c):
                    build()
                ops.append(c)
        while ops:
            build()
        return nums[0]

