class Solution:
    def maximalNetworkRank(self, n: int, roads: List[List[int]]) -> int:
        degree = [0] * n
        connected = set()
        for a, b in roads:
            degree[a] += 1
            degree[b] += 1
            connected.add((a, b))
            connected.add((b, a))
        res = 0
        for i in range(n):
            for j in range(i+1, n):
                rank = degree[i] + degree[j]
                if (i, j) in connected:
                    rank -= 1
                res = max(res, rank)
        return res

class Solution:
    def checkPalindromeFormation(self, a: str, b: str) -> bool:
        def check(s1, s2):
            i, j = 0, len(s2) - 1
            while i < j and s1[i] == s2[j]:
                i += 1
                j -= 1
            if i >= j:
                return True
            sub1 = s1[i:j+1]
            sub2 = s2[i:j+1]
            return sub1 == sub1[::-1] or sub2 == sub2[::-1]
        return check(a, b) or check(b, a)

class Solution:
    def countSubgraphsForEachDiameter(self, n: int, edges: List[List[int]]) -> List[int]:
        from collections import defaultdict, deque
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        res = [0] * (n - 1)
        for mask in range(3, 1 << n):
            nodes = [i+1 for i in range(n) if mask & (1 << i)]
            if len(nodes) < 2: continue
            def bfs(start):
                visited = {start}
                q = deque([(start, 0)])
                farthest, dist = start, 0
                while q:
                    node, d = q.popleft()
                    for nei in adj[node]:
                        if nei not in visited and (mask & (1 << (nei-1))):
                            visited.add(nei)
                            q.append((nei, d+1))
                            if d+1 > dist:
                                dist = d+1
                                farthest = nei
                return farthest, dist, visited
            far1, _, visited = bfs(nodes[0])
            if len(visited) != len(nodes): continue
            _, diameter, _ = bfs(far1)
            if diameter > 0:
                res[diameter-1] += 1
        return res

class Solution:
    def maxFont(self, text: str, w: int, h: int, fonts: List[int], fontInfo) -> int:
        left, right = 0, len(fonts) - 1
        res = -1
        while left <= right:
            mid = (left + right) // 2
            font = fonts[mid]
            if fontInfo.getHeight(font) > h:
                right = mid - 1
                continue
            width = sum(fontInfo.getWidth(font, c) for c in text)
            if width <= w:
                res = font
                left = mid + 1
            else:
                right = mid - 1
        return res

