class Solution:
    def bestCoordinate(self, towers: List[List[int]], radius: int) -> List[int]:
        import math
        max_signal = 0
        res = [0, 0]
        for x in range(51):
            for y in range(51):
                signal = 0
                for tx, ty, q in towers:
                    d = math.sqrt((x-tx)**2 + (y-ty)**2)
                    if d <= radius:
                        signal += int(q / (1 + d))
                if signal > max_signal:
                    max_signal = signal
                    res = [x, y]
        return res

