import heapq
class Solution:
    def minimumEffortPath(self, heights) -> int:
        m, n = len(heights), len(heights[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        heap = [(0, 0, 0)]
        while heap:
            d, x, y = heapq.heappop(heap)
            if x == m-1 and y == n-1:
                return d
            if d > dist[x][y]:
                continue
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n:
                    nd = max(d, abs(heights[nx][ny] - heights[x][y]))
                    if nd < dist[nx][ny]:
                        dist[nx][ny] = nd
                        heapq.heappush(heap, (nd, nx, ny))
        return 0

from collections import defaultdict
class Solution:
    def matrixRankTransform(self, matrix):
        m, n = len(matrix), len(matrix[0])
        val_pos = defaultdict(list)
        for i in range(m):
            for j in range(n):
                val_pos[matrix[i][j]].append((i, j))
        rank = [[0]*n for _ in range(m)]
        row_max = [0] * m
        col_max = [0] * n
        for val in sorted(val_pos):
            parent = {}
            def find(x):
                parent.setdefault(x, x)
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x
            def union(a, b):
                pa, pb = find(a), find(b)
                if pa != pb: parent[pa] = pb
            for i, j in val_pos[val]:
                union(('r', i), ('c', j))
            groups = defaultdict(list)
            for i, j in val_pos[val]:
                groups[find(('r', i))].append((i, j))
            for cells in groups.values():
                max_rank = max(max(row_max[i], col_max[j]) for i, j in cells) + 1
                for i, j in cells:
                    rank[i][j] = max_rank
                    row_max[i] = max_rank
                    col_max[j] = max_rank
        return rank

class Solution:
    def addPoly(self, poly1, poly2):
        dummy = Node(0, 0)
        cur = dummy
        p1, p2 = poly1, poly2
        while p1 and p2:
            if p1.power > p2.power:
                cur.next = p1
                p1 = p1.next
            elif p1.power < p2.power:
                cur.next = p2
                p2 = p2.next
            else:
                coeff = p1.coefficient + p2.coefficient
                if coeff != 0:
                    cur.next = Node(coeff, p1.power)
                    cur = cur.next
                p1, p2 = p1.next, p2.next
                continue
            cur = cur.next
        cur.next = p1 or p2
        return dummy.next

from collections import Counter
class Solution:
