class Solution:
    def countSubstrings(self, s: str, t: str) -> int:
        res = 0
        m, n = len(s), len(t)
        for i in range(m):
            for j in range(n):
                diff = 0
                k = 0
                while i + k < m and j + k < n:
                    if s[i+k] != t[j+k]:
                        diff += 1
                    if diff == 1:
                        res += 1
                    elif diff > 1:
                        break
                    k += 1
        return res

class Solution:
    def numWays(self, words, target: str) -> int:
        MOD = 10**9 + 7
        m, k = len(target), len(words[0])
        cnt = [[0]*26 for _ in range(k)]
        for w in words:
            for j, c in enumerate(w):
                cnt[j][ord(c)-ord('a')] += 1
        dp = [0] * (m + 1)
        dp[0] = 1
        for j in range(k):
            for i in range(min(m, j+1), 0, -1):
                dp[i] = (dp[i] + dp[i-1] * cnt[j][ord(target[i-1])-ord('a')]) % MOD
        return dp[m]

class Solution:
    def canFormArray(self, arr, pieces) -> bool:
        mp = {p[0]: p for p in pieces}
        i = 0
        while i < len(arr):
            if arr[i] not in mp:
                return False
            piece = mp[arr[i]]
            for val in piece:
                if i >= len(arr) or arr[i] != val:
                    return False
                i += 1
        return True

