import heapq
class Solution:
    def furthestBuilding(self, heights, bricks: int, ladders: int) -> int:
        heap = []
        for i in range(len(heights) - 1):
            diff = heights[i+1] - heights[i]
            if diff <= 0:
                continue
            heapq.heappush(heap, diff)
            if len(heap) > ladders:
                bricks -= heapq.heappop(heap)
            if bricks < 0:
                return i
        return len(heights) - 1

from math import comb
class Solution:
    def kthSmallestPath(self, destination, k: int) -> str:
        v, h = destination
        res = []
        for _ in range(h + v):
            if h > 0:
                ways = comb(h - 1 + v, v)
                if k <= ways:
                    res.append('H')
                    h -= 1
                else:
                    k -= ways
                    res.append('V')
                    v -= 1
            else:
                res.append('V')
                v -= 1
        return ''.join(res)

class Solution:
    def lowestCommonAncestor(self, root, p, q):
        self.found_p = self.found_q = False
        res = self.dfs(root, p, q)
        return res if self.found_p and self.found_q else None
    def dfs(self, node, p, q):
        if not node:
            return None
        left = self.dfs(node.left, p, q)
        right = self.dfs(node.right, p, q)
        if node == p:
            self.found_p = True
            return node
        if node == q:
            self.found_q = True
            return node
        if left and right:
            return node
        return left or right

class Solution:
    def getMaximumGenerated(self, n: int) -> int:
        if n <= 1:
            return n
        nums = [0] * (n + 1)
        nums[1] = 1
        for i in range(2, n + 1):
            if i % 2 == 0:
                nums[i] = nums[i // 2]
            else:
                nums[i] = nums[i // 2] + nums[i // 2 + 1]
        return max(nums)

from collections import Counter
class Solution:
    def minDeletions(self, s: str) -> int:
        freq = sorted(Counter(s).values(), reverse=True)
        res = 0
        max_allowed = freq[0]
        for f in freq:
            if f > max_allowed:
                res += f - max_allowed
                f = max_allowed
            if f > 0:
                max_allowed = f - 1
            else:
                max_allowed = 0
        return res

class Solution:
    def createSortedArray(self, instructions) -> int:
        MOD = 10**9 + 7
        m = max(instructions)
        tree = [0] * (m + 1)
        def update(i):
            while i <= m:
                tree[i] += 1
                i += i & (-i)
        def query(i):
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s
        res = 0
        for i, val in enumerate(instructions):
            left = query(val - 1)
            right = i - query(val)
            res = (res + min(left, right)) % MOD
            update(val)
        return res

class Solution:
    def lowestCommonAncestor(self, p, q):
        a, b = p, q
        while a != b:
            a = a.parent if a else q
            b = b.parent if b else p
        return a

class Solution:
    def decrypt(self, code, k: int) -> list:
        n = len(code)
        res = [0] * n
        if k == 0:
            return res
        for i in range(n):
            if k > 0:
                res[i] = sum(code[(i+j) % n] for j in range(1, k+1))
            else:
                res[i] = sum(code[(i+j) % n] for j in range(k, 0))
        return res

