from collections import Counter
class Solution:
    def canDistribute(self, nums, quantity) -> bool:
        cnt = list(Counter(nums).values())
        m = len(quantity)
        # precompute subset sums
        sub_sum = [0] * (1 << m)
        for mask in range(1, 1 << m):
            for j in range(m):
                if mask & (1 << j):
                    sub_sum[mask] = sub_sum[mask ^ (1 << j)] + quantity[j]
                    break
        n = len(cnt)
        dp = [[False] * (1 << m) for _ in range(n + 1)]
        dp[0][0] = True
        for i in range(1, n + 1):
            for mask in range(1 << m):
                dp[i][mask] = dp[i-1][mask]
                sub = mask
                while sub > 0:
                    if dp[i-1][mask ^ sub] and sub_sum[sub] <= cnt[i-1]:
                        dp[i][mask] = True
                        break
                    sub = (sub - 1) & mask
        return dp[n][(1 << m) - 1]

class OrderedStream:
    def __init__(self, n: int):
        self.stream = [None] * (n + 1)
        self.ptr = 1

    def insert(self, idKey: int, value: str):
        self.stream[idKey] = value
        res = []
        while self.ptr < len(self.stream) and self.stream[self.ptr]:
            res.append(self.stream[self.ptr])
            self.ptr += 1
        return res

