class Solution:
    def minOperations(self, nums, x: int) -> int:
        target = sum(nums) - x
        if target < 0:
            return -1
        if target == 0:
            return len(nums)
        n = len(nums)
        left = 0
        cur_sum = 0
        max_len = -1
        for right in range(n):
            cur_sum += nums[right]
            while cur_sum > target:
                cur_sum -= nums[left]
                left += 1
            if cur_sum == target:
                max_len = max(max_len, right - left + 1)
        return n - max_len if max_len != -1 else -1

class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(pos, intro, extro, last_row):
            if pos == m * n or (intro == 0 and extro == 0):
                return 0
            row, col = divmod(pos, n)
            res = dp(pos + 1, intro, extro, last_row)  # skip
            for t in [1, 2]:  # 1=intro, 2=extro
                if t == 1 and intro == 0: continue
                if t == 2 and extro == 0: continue
                gain = 120 if t == 1 else 40
                ni, ne = (intro-1, extro) if t == 1 else (intro, extro-1)
                new_row = last_row[1:] + (t,)
                # neighbor effects
                if col > 0 and last_row[-1] != 0:
                    nb = last_row[-1]
                    gain += (-30 if t == 1 else 20) + (-30 if nb == 1 else 20)
                if row > 0 and last_row[0] != 0:
                    nb = last_row[0]
                    gain += (-30 if t == 1 else 20) + (-30 if nb == 1 else 20)
                res = max(res, gain + dp(pos + 1, ni, ne, new_row))
            return res
        return dp(0, introvertsCount, extrovertsCount, tuple([0] * n))

from collections import deque
class Solution:
    def correctBinaryTree(self, root):
        queue = deque([(root, None, False)])
        visited = set()
        while queue:
            for _ in range(len(queue)):
                node, parent, is_left = queue.popleft()
                if node.right and node.right.val in visited:
                    if is_left:
                        parent.left = None
                    else:
                        parent.right = None
                    return root
                visited.add(node.val)
                if node.right:
                    queue.append((node.right, node, False))
                if node.left:
                    queue.append((node.left, node, True))
        return root

