class Solution:
    def getSmallestString(self, n: int, k: int) -> str:
        res = ['a'] * n
        k -= n
        for i in range(n - 1, -1, -1):
            add = min(25, k)
            res[i] = chr(ord('a') + add)
            k -= add
            if k <= 0:
                break
        return ''.join(res)

class Solution:
    def waysToMakeFair(self, nums) -> int:
        n = len(nums)
        right_even = sum(nums[i] for i in range(0, n, 2))
        right_odd = sum(nums[i] for i in range(1, n, 2))
        left_even = left_odd = 0
        res = 0
        for i in range(n):
            if i % 2 == 0:
                right_even -= nums[i]
            else:
                right_odd -= nums[i]
            # after removal: left_even + right_odd == left_odd + right_even?
            if left_even + right_odd == left_odd + right_even:
                res += 1
            if i % 2 == 0:
                left_even += nums[i]
            else:
                left_odd += nums[i]
        return res

class Solution:
    def minimumEffort(self, tasks) -> int:
        tasks.sort(key=lambda t: t[0] - t[1])
        res = 0
        cur = 0
        for actual, minimum in tasks:
            if cur < minimum:
                res += minimum - cur
                cur = minimum
            cur -= actual
        return res

class Solution:
    def flipBinaryTree(self, root, leaf):
        def dfs(node, prev):
            parent = node.parent
            node.parent = prev
            if node.left == prev:
                node.left = None
            if node.right == prev:
                node.right = None
            if parent:
                child = dfs(parent, node)
                if node.left:
                    node.right = child
                else:
                    node.left = child
            return node
        # disconnect leaf
        p = leaf.parent
        if p.left == leaf:
            p.left = None
        else:
            p.right = None
        leaf.parent = None
        child = dfs(p, leaf)
        if leaf.left:
            leaf.right = child
        else:
            leaf.left = child
        return leaf

