class Solution:
    def mostCompetitive(self, nums, k: int):
        stack = []
        n = len(nums)
        for i, num in enumerate(nums):
            while stack and stack[-1] > num and len(stack) + (n - i) > k:
                stack.pop()
            if len(stack) < k:
                stack.append(num)
        return stack

class Solution:
    def lowestCommonAncestor(self, root, nodes):
        target = set(nodes)
        def dfs(node):
            if not node or node in target:
                return node
            left = dfs(node.left)
            right = dfs(node.right)
            if left and right:
                return node
            return left or right
        return dfs(root)

