from collections import Counter
class Solution:
    def maxOperations(self, nums, k: int) -> int:
        cnt = Counter(nums)
        res = 0
        for num in list(cnt.keys()):
            comp = k - num
            if comp == num:
                res += cnt[num] // 2
            elif comp in cnt:
                pairs = min(cnt[num], cnt[comp])
                res += pairs
                cnt[num] -= pairs
                cnt[comp] -= pairs
        return res

class Solution:
    def concatenatedBinary(self, n: int) -> int:
        MOD = 10**9 + 7
        res = 0
        for i in range(1, n + 1):
            res = ((res << i.bit_length()) | i) % MOD
        return res

class Solution:
    def minimumIncompatibility(self, nums: List[int], k: int) -> int:
        n = len(nums)
        group_size = n // k
        INF = float('inf')
        # precompute cost of each valid subset of size group_size
        cost = {}
        for mask in range(1, 1 << n):
            if bin(mask).count('1') != group_size:
                continue
            elements = [nums[i] for i in range(n) if mask & (1 << i)]
            if len(set(elements)) != group_size:
                continue
            cost[mask] = max(elements) - min(elements)
        full = (1 << n) - 1
        dp = [INF] * (1 << n)
        dp[0] = 0
        for mask in range(full + 1):
            if dp[mask] == INF:
                continue
            remain = full & ~mask
            sub = remain
            while sub:
                if sub in cost:
                    dp[mask | sub] = min(dp[mask | sub], dp[mask] + cost[sub])
                sub = (sub - 1) & remain
        return dp[full] if dp[full] != INF else -1

class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        n = len(s)
        # dp[i][j][c]: longest palindrome in s[i..j] where last matched pair is char c
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i, j, last):
            if i >= j:
                return 0
            res = 0
            for c in range(26):
                if c == last:
                    continue
                ch = chr(c + ord('a'))
                # find leftmost ch in [i,j] and rightmost ch in [i,j]
                l = i
                while l <= j and s[l] != ch:
                    l += 1
                r = j
                while r >= i and s[r] != ch:
                    r -= 1
                if l < r:
                    res = max(res, dp(l+1, r-1, c) + 2)
            return res
        return dp(0, n-1, -1)

