class Solution:
    def stoneGameVII(self, stones: List[int]) -> int:
        n = len(stones)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + stones[i]
        def rangeSum(i, j):
            return prefix[j+1] - prefix[i]
        dp = [[0]*n for _ in range(n)]
        for length in range(2, n+1):
            for i in range(n - length + 1):
                j = i + length - 1
                # remove left: score = rangeSum(i+1,j), then opponent plays dp[i+1][j]
                # remove right: score = rangeSum(i,j-1), then opponent plays dp[i][j-1]
                dp[i][j] = max(rangeSum(i+1, j) - dp[i+1][j], rangeSum(i, j-1) - dp[i][j-1])
        return dp[0][n-1]

class Solution:
    def maxHeight(self, cuboids: List[List[int]]) -> int:
        for c in cuboids:
            c.sort()
        cuboids.sort()
        n = len(cuboids)
        dp = [c[2] for c in cuboids]
        for i in range(1, n):
            for j in range(i):
                if cuboids[j][0] <= cuboids[i][0] and cuboids[j][1] <= cuboids[i][1] and cuboids[j][2] <= cuboids[i][2]:
                    dp[i] = max(dp[i], dp[j] + cuboids[i][2])
        return max(dp)

class Solution:
    def waysToDistribute(self, n: int, k: int) -> int:
        MOD = 10**9 + 7
        dp = [[0]*(k+1) for _ in range(n+1)]
        dp[0][0] = 1
        for i in range(1, n+1):
            for j in range(1, min(i, k)+1):
                dp[i][j] = (j * dp[i-1][j] + dp[i-1][j-1]) % MOD
        return dp[n][k]

class Solution:
    def reformatNumber(self, number: str) -> str:
        digits = number.replace(' ', '').replace('-', '')
        res = []
        i = 0
        n = len(digits)
        while n - i > 4:
            res.append(digits[i:i+3])
            i += 3
        if n - i == 4:
            res.append(digits[i:i+2])
            res.append(digits[i+2:i+4])
        else:
            res.append(digits[i:])
        return '-'.join(res)

class Solution:
    def maxResult(self, nums: List[int], k: int) -> int:
        from collections import deque
        n = len(nums)
        dp = [0] * n
        dp[0] = nums[0]
        dq = deque([0])
        for i in range(1, n):
            while dq and dq[0] < i - k:
                dq.popleft()
            dp[i] = nums[i] + dp[dq[0]]
            while dq and dp[dq[-1]] <= dp[i]:
                dq.pop()
            dq.append(i)
        return dp[n-1]

class Solution:
    def distanceLimitedPathsExist(self, n: int, edgeList: List[List[int]], queries: List[List[int]]) -> List[bool]:
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py
        edgeList.sort(key=lambda e: e[2])
        q_idx = sorted(range(len(queries)), key=lambda i: queries[i][2])
        res = [False] * len(queries)
        ei = 0
        for qi in q_idx:
            u, v, limit = queries[qi]
            while ei < len(edgeList) and edgeList[ei][2] < limit:
                union(edgeList[ei][0], edgeList[ei][1])
                ei += 1
            res[qi] = find(u) == find(v)
        return res

class Solution:
    def countDistinct(self, s: str) -> int:
        seen = set()
        n = len(s)
        for i in range(n):
            for j in range(i+1, n+1):
                seen.add(s[i:j])
        return len(seen)

class Solution:
    def countStudents(self, students: List[int], sandwiches: List[int]) -> int:
        from collections import Counter
        cnt = Counter(students)
        for i, s in enumerate(sandwiches):
            if cnt[s] == 0:
                return len(sandwiches) - i
            cnt[s] -= 1
        return 0

class Solution:
    def averageWaitingTime(self, customers: List[List[int]]) -> float:
        cur_time = 0
        total_wait = 0
        for arrival, time in customers:
            cur_time = max(cur_time, arrival) + time
            total_wait += cur_time - arrival
        return total_wait / len(customers)

class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        n = len(binary)
        # find first 0
        first_zero = binary.find('0')
        if first_zero == -1:
            return binary
        # count zeros from first_zero onwards
        zeros = binary[first_zero:].count('0')
        # result: all 1s except position (first_zero + zeros - 1) is 0
        res = ['1'] * n
        res[first_zero + zeros - 1] = '0'
        return ''.join(res)

class Solution:
    def eatenApples(self, apples: List[int], days: List[int]) -> int:
        import heapq
        n = len(apples)
        heap = []
        eaten = 0
        day = 0
        while day < n or heap:
            if day < n and apples[day] > 0:
                heapq.heappush(heap, (day + days[day], apples[day]))
            while heap and heap[0][0] <= day:
                heapq.heappop(heap)
            if heap:
                exp, cnt = heapq.heappop(heap)
                eaten += 1
                if cnt > 1:
                    heapq.heappush(heap, (exp, cnt - 1))
            day += 1
        return eaten

class Solution:
    def findBall(self, grid: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        res = []
        for col in range(n):
            c = col
            for r in range(m):
                nc = c + grid[r][c]
                if nc < 0 or nc >= n or grid[r][nc] != grid[r][c]:
                    c = -1
                    break
                c = nc
            res.append(c)
        return res

class Solution:
    def maximizeXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        nums.sort()
        q_sorted = sorted(enumerate(queries), key=lambda x: x[1][1])
        trie = {}
        res = [-1] * len(queries)
        idx = 0
        for qi, (xi, mi) in q_sorted:
            while idx < len(nums) and nums[idx] <= mi:
                node = trie
                for bit in range(30, -1, -1):
                    b = (nums[idx] >> bit) & 1
                    if b not in node:
                        node[b] = {}
                    node = node[b]
                idx += 1
            if not trie:
                res[qi] = -1
                continue
            node = trie
            xor_val = 0
            for bit in range(30, -1, -1):
                want = (xi >> bit) & 1 ^ 1
                if want in node:
                    xor_val |= (1 << bit)
                    node = node[want]
                else:
                    node = node[1 - want]
            res[qi] = xor_val
        return res

class Solution:
    def largestSubarray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        max_idx = 0
        for i in range(1, n - k + 1):
            if nums[i] > nums[max_idx]:
                max_idx = i
        return nums[max_idx:max_idx+k]

class Solution:
    def maximumUnits(self, boxTypes: List[List[int]], truckSize: int) -> int:
        boxTypes.sort(key=lambda x: -x[1])
        units = 0
        for count, unit in boxTypes:
            take = min(count, truckSize)
            units += take * unit
            truckSize -= take
            if truckSize == 0:
                break
        return units

class Solution:
    def countPairs(self, deliciousness: List[int]) -> int:
        MOD = 10**9 + 7
        cnt = {}
        res = 0
        for d in deliciousness:
            for p in range(22):
                target = (1 << p) - d
                if target in cnt:
                    res = (res + cnt[target]) % MOD
            cnt[d] = cnt.get(d, 0) + 1
        return res

class Solution:
    def waysToSplit(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]
        total = prefix[n]
        res = 0
        for i in range(1, n - 1):
            left_sum = prefix[i]
            if left_sum * 3 > total:
                break
            # find min j: prefix[j] - prefix[i] >= prefix[i]
            lo, hi = i + 1, n - 1
            while lo < hi:
                mid = (lo + hi) // 2
                if prefix[mid] - prefix[i] >= left_sum:
                    hi = mid
                else:
                    lo = mid + 1
            j_min = lo
            # find max j: prefix[j] - prefix[i] <= total - prefix[j] => 2*prefix[j] <= total + prefix[i]
            lo, hi = j_min, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if 2 * prefix[mid] <= total + prefix[i]:
                    lo = mid
                else:
                    hi = mid - 1
            j_max = lo
            if j_min <= j_max:
                res = (res + j_max - j_min + 1) % MOD
        return res

class Solution:
    def minOperations(self, target: List[int], arr: List[int]) -> int:
        import bisect
        pos = {v: i for i, v in enumerate(target)}
        # map arr to indices in target
        mapped = [pos[x] for x in arr if x in pos]
        # LIS on mapped
        tails = []
        for x in mapped:
            idx = bisect.bisect_left(tails, x)
            if idx == len(tails):
                tails.append(x)
            else:
                tails[idx] = x
        return len(target) - len(tails)

class Solution:
    def solve(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        MOD = 10**9 + 7
        n = len(nums)
        import math
        B = int(math.sqrt(n)) + 1
        # precompute suffix sums for small steps
        cache = {}
        for y in range(1, B):
            suf = [0] * (n + 1)
            for i in range(n - 1, -1, -1):
                suf[i] = (nums[i] + (suf[i + y] if i + y <= n else 0)) % MOD
            cache[y] = suf
        res = []
        for x, y in queries:
            if y < B:
                res.append(cache[y][x])
            else:
                s = 0
                i = x
                while i < n:
                    s = (s + nums[i]) % MOD
                    i += y
                res.append(s)
        return res

class Solution:
    def maximumGain(self, s: str, x: int, y: int) -> int:
        def remove(s, first, second, score):
            stack = []
            total = 0
            for c in s:
                if stack and stack[-1] == first and c == second:
                    stack.pop()
                    total += score
                else:
                    stack.append(c)
            return total, ''.join(stack)
        if x >= y:
            score1, remaining = remove(s, 'a', 'b', x)
            score2, _ = remove(remaining, 'b', 'a', y)
        else:
            score1, remaining = remove(s, 'b', 'a', y)
            score2, _ = remove(remaining, 'a', 'b', x)
        return score1 + score2

class Solution:
    def constructDistancedSequence(self, n: int) -> List[int]:
        size = 2 * n - 1
        res = [0] * size
        used = [False] * (n + 1)
        def dfs(idx):
            if idx == size:
                return True
            if res[idx] != 0:
                return dfs(idx + 1)
            for num in range(n, 0, -1):
                if used[num]:
                    continue
                if num == 1:
                    res[idx] = 1
                    used[1] = True
                    if dfs(idx + 1):
                        return True
                    res[idx] = 0
                    used[1] = False
                else:
                    if idx + num < size and res[idx + num] == 0:
                        res[idx] = res[idx + num] = num
                        used[num] = True
                        if dfs(idx + 1):
                            return True
                        res[idx] = res[idx + num] = 0
                        used[num] = False
            return False
        dfs(0)
        return res

class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        from collections import defaultdict
        adj = defaultdict(set)
        for u, v in pairs:
            adj[u].add(v)
            adj[v].add(u)
        nodes = list(adj.keys())
        n = len(nodes)
        # root must be connected to all other nodes
        root = None
        for node in nodes:
            if len(adj[node]) == n - 1:
                root = node
                break
        if root is None:
            return 0
        res = 1
        for node in nodes:
            if node == root:
                continue
            # find parent: node with smallest degree among adj[node] that has degree >= degree of node
            parent = None
            min_deg = float('inf')
            for neighbor in adj[node]:
                if len(adj[neighbor]) >= len(adj[node]) and len(adj[neighbor]) < min_deg:
                    min_deg = len(adj[neighbor])
                    parent = neighbor
            if parent is None:
                return 0
            # adj[node] - {parent} must be subset of adj[parent]
            for neighbor in adj[node]:
                if neighbor != parent and neighbor not in adj[parent]:
                    return 0
            if len(adj[node]) == len(adj[parent]):
                res = 2
        return res

