        res = []
        for t, d, cap in queries:
            min_eat = d + 1
            max_eat = (d + 1) * cap
            res.append(not (min_eat > prefix[t + 1] or max_eat < prefix[t] + 1))
        return res

class Solution:
    def checkPartitioning(self, s: str) -> bool:
        n = len(s)
        dp = [[False]*n for _ in range(n)]
        for i in range(n-1, -1, -1):
            for j in range(i, n):
                if s[i] == s[j] and (j - i <= 2 or dp[i+1][j-1]):
                    dp[i][j] = True
        for i in range(1, n-1):
            for j in range(i+1, n):
                if dp[0][i-1] and dp[i][j-1] and dp[j][n-1]:
                    return True
        return False

class Solution:
    def maxSumAfterOperation(self, nums: List[int]) -> int:
        dp0 = dp1 = 0
        res = float('-inf')
        for x in nums:
            dp1 = max(dp1 + x, dp0 + x*x, x*x)
            dp0 = max(dp0 + x, x)
            res = max(res, dp1)
