class Solution:
    def highestPeak(self, isWater: List[List[int]]) -> List[List[int]]:
        from collections import deque
        m, n = len(isWater), len(isWater[0])
        height = [[-1]*n for _ in range(m)]
        q = deque()
        for i in range(m):
            for j in range(n):
                if isWater[i][j]:
                    height[i][j] = 0
                    q.append((i, j))
        while q:
            x, y = q.popleft()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and height[nx][ny] == -1:
                    height[nx][ny] = height[x][y] + 1
                    q.append((nx, ny))
        return height

class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        from math import gcd
        from collections import defaultdict
        n = len(nums)
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        coprime = defaultdict(list)
        for i in range(1, 51):
            for j in range(1, 51):
                if gcd(i, j) == 1:
                    coprime[i].append(j)
        ans = [-1] * n
        ancestor = {}  # val -> (depth, node)
        def dfs(node, parent, depth):
            best_depth, best_node = -1, -1
            for v in coprime[nums[node]]:
                if v in ancestor and ancestor[v][0] > best_depth:
                    best_depth, best_node = ancestor[v]
            ans[node] = best_node
            old = ancestor.get(nums[node])
            ancestor[nums[node]] = (depth, node)
            for nei in graph[node]:
                if nei != parent:
                    dfs(nei, node, depth + 1)
            if old is None:
                del ancestor[nums[node]]
            else:
                ancestor[nums[node]] = old
        dfs(0, -1, 0)
        return ans

