class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        self.ans = baseCosts[0]
        def dfs(idx, cur):
            if abs(cur - target) < abs(self.ans - target) or                (abs(cur - target) == abs(self.ans - target) and cur < self.ans):
                self.ans = cur
            if idx == len(toppingCosts) or cur > target:
                return
            dfs(idx + 1, cur)
            dfs(idx + 1, cur + toppingCosts[idx])
            dfs(idx + 1, cur + 2 * toppingCosts[idx])
        for base in baseCosts:
            dfs(0, base)
        return self.ans

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        s1, s2 = sum(nums1), sum(nums2)
        if s1 > s2:
            nums1, nums2 = nums2, nums1
            s1, s2 = s2, s1
        diff = s2 - s1
        if diff == 0:
            return 0
        gains = sorted([min(6, x) - max(1, x) for x in nums1] + [max(1, x) - min(6, x) for x in nums2], reverse=True)
        # Correction: gains from nums1 (increase) and nums2 (decrease)
        gains = []
        for x in nums1:
            gains.append(6 - x)
        for x in nums2:
            gains.append(x - 1)
        gains.sort(reverse=True)
        ops = 0
        for g in gains:
            if diff <= 0:
                return ops
            diff -= g
            ops += 1
        return ops if diff <= 0 else -1

class Solution:
    def getCollisionTimes(self, cars: List[List[int]]) -> List[float]:
        n = len(cars)
        ans = [-1.0] * n
        stack = []
        for i in range(n-1, -1, -1):
            pos, speed = cars[i]
            while stack:
                j = stack[-1]
                pj, sj = cars[j]
                if speed <= sj:
                    stack.pop()
                else:
                    t = (pj - pos) / (speed - sj)
                    if ans[j] < 0 or t <= ans[j]:
                        break
                    stack.pop()
            if stack:
                j = stack[-1]
                ans[i] = (cars[j][0] - pos) / (speed - cars[j][1])
            stack.append(i)
        return ans

# Interactive problem - conceptual solution
# DFS to explore grid, then BFS for shortest path
class Solution:
    def findShortestPath(self, master: 'GridMaster') -> int:
        dirs = {'U': (-1,0), 'D': (1,0), 'L': (0,-1), 'R': (0,1)}
        opposite = {'U':'D', 'D':'U', 'L':'R', 'R':'L'}
        grid = {(0,0): True}
        target = None
        def dfs(r, c):
            nonlocal target
            if master.isTarget():
                target = (r, c)
            for d, (dr, dc) in dirs.items():
                nr, nc = r+dr, c+dc
                if (nr,nc) not in grid:
                    if master.canMove(d):
                        master.move(d)
                        grid[(nr,nc)] = True
                        dfs(nr, nc)
                        master.move(opposite[d])
                    else:
                        grid[(nr,nc)] = False
        dfs(0, 0)
        if not target:
            return -1
        from collections import deque
        q = deque([(0, 0, 0)])
        visited = {(0,0)}
        while q:
            r, c, dist = q.popleft()
            if (r,c) == target:
                return dist
            for dr, dc in dirs.values():
                nr, nc = r+dr, c+dc
                if (nr,nc) in grid and grid[(nr,nc)] and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    q.append((nr, nc, dist+1))
        return -1

