        last_pos = {}
        for i, c in enumerate(secondString):
            last_pos[c] = i
        min_diff = float('inf')
        count = 0
        for c in first_pos:
            if c in last_pos:
                diff = first_pos[c] - last_pos[c]
                if diff < min_diff:
