        n = len(nums)
        left, right = [-1]*n, [n]*n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] >= nums[i]:
                right[stack.pop()] = i
            if stack: left[i] = stack[-1]
            stack.append(i)
        prefix = [0] * (n + 1)
