        start = int(loginTime[:2]) * 60 + int(loginTime[3:])
        end = int(logoutTime[:2]) * 60 + int(logoutTime[3:])
        if end < start:
            end += 24 * 60
        start = -(-start // 15)
        end = end // 15
        return max(0, end - start)

class Solution:
    def countSubIslands(self, grid1: List[List[int]], grid2: List[List[int]]) -> int:
        m, n = len(grid1), len(grid1[0])
        def dfs(i, j):
            if i < 0 or i >= m or j < 0 or j >= n or grid2[i][j] == 0:
                return True
            grid2[i][j] = 0
            res = grid1[i][j] == 1
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                if not dfs(i+di, j+dj):
                    res = False
            return res
        count = 0
        for i in range(m):
            for j in range(n):
                if grid2[i][j] == 1:
                    if dfs(i, j):
                        count += 1
        return count

class Solution:
    def minDifference(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        prefix = [[0]*101 for _ in range(n+1)]
        for i in range(n):
            for v in range(101):
                prefix[i+1][v] = prefix[i][v]
            prefix[i+1][nums[i]] += 1
        res = []
        for l, r in queries:
            prev = -1
            min_diff = float('inf')
            for v in range(1, 101):
                if prefix[r+1][v] - prefix[l][v] > 0:
                    if prev != -1:
                        min_diff = min(min_diff, v - prev)
                    prev = v
            res.append(min_diff if min_diff != float('inf') else -1)
        return res

