class Solution:
    def countSpecialSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp0 = dp1 = dp2 = 0
        for x in nums:
            if x == 0:
                dp0 = (dp0 * 2 + 1) % MOD
            elif x == 1:
                dp1 = (dp1 * 2 + dp0) % MOD
            else:
                dp2 = (dp2 * 2 + dp1) % MOD
        return dp2

class Solution:
    def minDayskVariants(self, points: List[List[int]], k: int) -> int:
        def check(t):
            # Manhattan to Chebyshev: (x,y) -> (x+y, x-y)
            rects = [(x+y-t, x-y-t, x+y+t, x-y+t) for x,y in points]
            # Check if any point covered by >= k rectangles
            xs = sorted(set(x for r in rects for x in [r[0], r[2]]))
            for x in xs:
                ys = []
                for x1,y1,x2,y2 in rects:
                    if x1 <= x <= x2:
                        ys.append((y1, 1))
                        ys.append((y2 + 1, -1))
                ys.sort()
                cnt = 0
                for _, d in ys:
                    cnt += d
                    if cnt >= k:
                        return True
            return False
        lo, hi = 0, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if check(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

