class Solution:
    def latestDayToCross(self, row: int, col: int, cells: List[List[int]]) -> int:
        from collections import deque
        def canCross(day):
            grid = [[0]*col for _ in range(row)]
            for i in range(day):
                r, c = cells[i]
                grid[r-1][c-1] = 1
            q = deque()
            for j in range(col):
                if grid[0][j] == 0:
                    q.append((0, j))
                    grid[0][j] = 1
            while q:
                r, c = q.popleft()
                if r == row - 1:
                    return True
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < row and 0 <= nc < col and grid[nr][nc] == 0:
                        grid[nr][nc] = 1
                        q.append((nr, nc))
            return False
        lo, hi = 1, len(cells)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if canCross(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def validPath(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:
        from collections import defaultdict, deque
        if source == destination: return True
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        visited = {source}
        q = deque([source])
        while q:
            node = q.popleft()
            for nei in graph[node]:
                if nei == destination:
                    return True
                if nei not in visited:
                    visited.add(nei)
                    q.append(nei)
        return False

class Solution:
    def equalToDescendants(self, root: Optional[TreeNode]) -> int:
        self.count = 0
        def dfs(node):
            if not node: return 0
            left = dfs(node.left)
            right = dfs(node.right)
            if node.val == left + right and (node.left or node.right):
                self.count += 1
            return node.val + left + right
        dfs(root)
        return self.count

