class Solution:
    def firstDayBeenInAllRooms(self, nextVisit: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nextVisit)
        dp = [0] * n
        for i in range(1, n):
            dp[i] = (2 * dp[i-1] - dp[nextVisit[i-1]] + 2) % MOD
        return dp[n-1]

class Solution:
    def gcdSort(self, nums: List[int]) -> bool:
        parent = {}
        def find(x):
            while parent.setdefault(x, x) != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            parent[find(x)] = find(y)
        for num in nums:
            x = num
            d = 2
            while d * d <= x:
                if x % d == 0:
                    union(num, d)
                    while x % d == 0:
                        x //= d
                d += 1
            if x > 1:
                union(num, x)
        sorted_nums = sorted(nums)
        return all(find(a) == find(b) for a, b in zip(nums, sorted_nums))

class Solution:
    def findInteger(self, k: int, digit1: int, digit2: int) -> int:
        from collections import deque
        if digit1 == 0 and digit2 == 0:
            return -1
        q = deque()
        if digit1 > 0: q.append(digit1)
        if digit2 > 0 and digit2 != digit1: q.append(digit2)
        if not q:
            return -1
        visited = set()
        while q:
            num = q.popleft()
            if num > k and num % k == 0:
                return num
            if num > 2 * 10**9:
                continue
            for d in [digit1, digit2]:
                nxt = num * 10 + d
                if nxt not in visited:
                    visited.add(nxt)
                    q.append(nxt)
        return -1

