class Solution:
    def interchangeableRectangles(self, rectangles: List[List[int]]) -> int:
        from math import gcd
        from collections import Counter
        cnt = Counter()
        for w, h in rectangles:
            g = gcd(w, h)
            cnt[(w // g, h // g)] += 1
        return sum(c * (c - 1) // 2 for c in cnt.values())

class Solution:
    def maxProduct(self, s: str) -> int:
        n = len(s)
        # precompute palindrome length for each mask
        pal = {}
        for mask in range(1, 1 << n):
            subseq = [s[i] for i in range(n) if mask & (1 << i)]
            if subseq == subseq[::-1]:
                pal[mask] = len(subseq)
        res = 0
        masks = list(pal.keys())
        for m1 in masks:
            complement = ((1 << n) - 1) ^ m1
            m2 = complement
            while m2:
                if m2 in pal:
                    res = max(res, pal[m1] * pal[m2])
                m2 = (m2 - 1) & complement
        return res

