class Solution:
    def maxTaxiEarnings(self, n: int, rides: List[List[int]]) -> int:
        from collections import defaultdict
        rides_at = defaultdict(list)
        for s, e, t in rides:
            rides_at[e].append((s, e - s + t))
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i - 1]
            for s, earn in rides_at[i]:
                dp[i] = max(dp[i], dp[s] + earn)
        return dp[n]

