class Solution:
    def sumOfBeauties(self, nums: List[int]) -> int:
        n = len(nums)
        left_max = [0] * n
        right_min = [0] * n
        left_max[0] = nums[0]
        for i in range(1, n):
            left_max[i] = max(left_max[i-1], nums[i])
        right_min[n-1] = nums[n-1]
        for i in range(n-2, -1, -1):
            right_min[i] = min(right_min[i+1], nums[i])
        res = 0
        for i in range(1, n-1):
            if left_max[i-1] < nums[i] < right_min[i+1]:
                res += 2
            elif nums[i-1] < nums[i] < nums[i+1]:
                res += 1
        return res

class DetectSquares:
    def __init__(self):
        from collections import Counter
        self.cnt = Counter()
        self.points = []

    def add(self, point: List[int]) -> None:
        self.cnt[tuple(point)] += 1
        self.points.append(point)

    def count(self, point: List[int]) -> int:
        x1, y1 = point
        res = 0
        for x2, y2 in self.points:
            if abs(x2 - x1) == 0 or abs(x2 - x1) != abs(y2 - y1):
                continue
            res += self.cnt[(x1, y2)] * self.cnt[(x2, y1)]
        return res

class Solution:
    def longestSubsequenceRepeatedK(self, s: str, k: int) -> str:
        from collections import Counter
        cnt = Counter(s)
        chars = sorted([c for c in cnt if cnt[c] >= k], reverse=True)

        def is_subseq(sub, s, k):
            # check if sub repeated k times is a subsequence of s
            idx = 0
            for _ in range(k):
                for c in sub:
                    idx = s.find(c, idx)
                    if idx == -1: return False
                    idx += 1
            return True

        from collections import deque
        q = deque([''])
        res = ''
        while q:
            cur = q.popleft()
            for c in chars:
                nxt = cur + c
                if is_subseq(nxt, s, k):
                    if len(nxt) > len(res) or (len(nxt) == len(res) and nxt > res):
                        res = nxt
                    q.append(nxt)
        return res

