            if len(segment) != len(word):
                return False
            return all(s == ' ' or s == w for s, w in zip(segment, word))

        m, n = len(board), len(board[0])
        wlen = len(word)
        # check horizontal
        for i in range(m):
            seg = []
            for j in range(n + 1):
                if j < n and board[i][j] != '#':
                    seg.append(board[i][j])
                else:
                    if seg:
                        if check(seg, word) or check(seg, word[::-1]):
                            return True
                        seg = []
        # check vertical
        for j in range(n):
            seg = []
            for i in range(m + 1):
                if i < m and board[i][j] != '#':
                    seg.append(board[i][j])
                else:
                    if seg:
                        if check(seg, word) or check(seg, word[::-1]):
                            return True
                        seg = []
        return False

class Solution:
    def scoreOfStudents(self, s: str, answers: List[int]) -> int:
        # parse numbers and operators
        nums, ops = [], []
        i = 0
        while i < len(s):
            if s[i].isdigit():
                nums.append(int(s[i]))
            else:
                ops.append(s[i])
            i += 1
        n = len(nums)
        # interval DP: dp[i][j] = set of possible values for nums[i..j]
        dp = [[set() for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i] = {nums[i]}
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for k in range(i, j):
                    for a in dp[i][k]:
                        for b in dp[k+1][j]:
                            val = a * b if ops[k] == '*' else a + b
                            if val <= 1000:
                                dp[i][j].add(val)
        # correct answer
        correct = eval(s)
        possible = dp[0][n-1]
        res = 0
        for ans in answers:
            if ans == correct:
                res += 5
            elif ans in possible:
                res += 2
        return res

