        def maxLen(char):
            left = res = count = 0
            for right in range(len(answerKey)):
                if answerKey[right] != char:
                    count += 1
                while count > k:
                    if answerKey[left] != char:
                        count -= 1
                    left += 1
                res = max(res, right - left + 1)
            return res
        return max(maxLen('T'), maxLen('F'))

