        return n

class Solution:
    def countHighestScoreNodes(self, parents):
        from collections import defaultdict
        n = len(parents)
        children = defaultdict(list)
        for i in range(1, n):
            children[parents[i]].append(i)
        size = [0] * n
        def dfs(u):
            size[u] = 1
            for v in children[u]:
                dfs(v)
                size[u] += size[v]
        dfs(0)
        max_score = 0
        count = 0
        for i in range(n):
            score = 1
            remain = n - 1
            for c in children[i]:
                score *= size[c]
                remain -= size[c]
            if remain > 0:
                score *= remain
            if score > max_score:
                max_score = score
                count = 1
            elif score == max_score:
                count += 1
        return count

class Solution:
    def minimumTime(self, n, relations, time):
        from collections import deque, defaultdict
        g = defaultdict(list)
        indeg = [0] * (n+1)
        for u, v in relations:
            g[u].append(v)
            indeg[v] += 1
        dist = [0] * (n+1)
        q = deque()
        for i in range(1, n+1):
            if indeg[i] == 0:
                q.append(i)
                dist[i] = time[i-1]
        while q:
            u = q.popleft()
            for v in g[u]:
                dist[v] = max(dist[v], dist[u] + time[v-1])
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        return max(dist)

class Solution:
    def minimumCost(self, sentence: str, k: int) -> int:
        words = sentence.split()
        n = len(words)
        dp = [float('inf')] * (n+1)
        dp[0] = 0
        for i in range(1, n+1):
            length = 0
            for j in range(i, 0, -1):
                length += len(words[j-1])
                if length > k: break
                if j < i: length += 1
                if length > k: break
                if i == n:
                    dp[i] = min(dp[i], dp[j-1])
                else:
                    dp[i] = min(dp[i], dp[j-1] + (k - length)**2)
        return dp[n]

