class Solution:
    def minimumOperations(self, nums, start, goal):
        from collections import deque
        visited = [False]*1001
        q = deque([(start, 0)])
        visited[start] = True
        while q:
            x, d = q.popleft()
            for num in nums:
                for nx in [x+num, x-num, x^num]:
                    if nx == goal: return d+1
                    if 0 <= nx <= 1000 and not visited[nx]:
                        visited[nx] = True
                        q.append((nx, d+1))
        return -1

class Solution:
    def possiblyEquals(self, s1: str, s2: str) -> bool:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i, j, diff):
            if i == len(s1) and j == len(s2):
                return diff == 0
            if i < len(s1) and s1[i].isdigit():
                k, val = i, 0
                while k < len(s1) and s1[k].isdigit():
                    val = val*10 + int(s1[k])
                    if dp(k+1, j, diff+val): return True
                    k += 1
                return False
            if j < len(s2) and s2[j].isdigit():
                k, val = j, 0
                while k < len(s2) and s2[k].isdigit():
                    val = val*10 + int(s2[k])
                    if dp(i, k+1, diff-val): return True
                    k += 1
                return False
            if diff > 0:
                return j < len(s2) and dp(i, j+1, diff-1)
            if diff < 0:
                return i < len(s1) and dp(i+1, j, diff+1)
            if i < len(s1) and j < len(s2) and s1[i] == s2[j]:
                return dp(i+1, j+1, 0)
            return False
        return dp(0, 0, 0)

class Solution:
    def numberOfCleanRooms(self, room):
        m, n = len(room), len(room[0])
        dirs = [(0,1),(1,0),(0,-1),(-1,0)]
        visited = set()
        cleaned = set()
        r, c, d = 0, 0, 0
        while (r, c, d) not in visited:
            visited.add((r, c, d))
            cleaned.add((r, c))
            nr, nc = r+dirs[d][0], c+dirs[d][1]
            if 0<=nr<m and 0<=nc<n and room[nr][nc]==0:
                r, c = nr, nc
            else:
                d = (d+1) % 4
        return len(cleaned)

