class Solution:
    def reverseEvenLengthGroups(self, head):
        curr = head
        group = 1
        while curr:
            nodes = []
            temp = curr
            for _ in range(group):
                if not temp: break
                nodes.append(temp)
                temp = temp.next
            actual_len = len(nodes)
            if actual_len % 2 == 0:
                vals = [n.val for n in nodes][::-1]
                for i, n in enumerate(nodes):
                    n.val = vals[i]
            curr = nodes[-1].next if nodes else None
            group += 1
        return head

class Solution:
    def decodeCiphertext(self, encodedText: str, rows: int) -> str:
        if rows == 1: return encodedText
        cols = len(encodedText) // rows
        grid = [encodedText[i*cols:(i+1)*cols] for i in range(rows)]
        res = []
        for start in range(cols):
            r, c = 0, start
            while r < rows and c < cols:
                res.append(grid[r][c])
                r += 1
                c += 1
        return ''.join(res).rstrip()

class Solution:
    def friendRequests(self, n, restrictions, requests):
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        ans = []
        for u, v in requests:
            pu, pv = find(u), find(v)
            if pu == pv:
                ans.append(True)
                continue
            ok = True
            for a, b in restrictions:
                pa, pb = find(a), find(b)
                if (pa == pu and pb == pv) or (pa == pv and pb == pu):
                    ok = False
                    break
            if ok:
                parent[pu] = pv
            ans.append(ok)
        return ans

