class Solution:
    def goodDaysToRobBank(self, security, time):
        n = len(security)
        left = [0]*n
        right = [0]*n
        for i in range(1, n):
            if security[i] <= security[i-1]:
                left[i] = left[i-1] + 1
        for i in range(n-2, -1, -1):
            if security[i] <= security[i+1]:
                right[i] = right[i+1] + 1
        return [i for i in range(n) if left[i] >= time and right[i] >= time]

class Solution:
    def maximumDetonation(self, bombs: List[List[int]]) -> int:
        n = len(bombs)
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    dx = bombs[i][0] - bombs[j][0]
                    dy = bombs[i][1] - bombs[j][1]
                    if dx*dx + dy*dy <= bombs[i][2]**2:
                        graph[i].append(j)
        res = 0
        for i in range(n):
            visited = set([i])
            queue = [i]
            while queue:
                node = queue.pop()
                for nei in graph[node]:
                    if nei not in visited:
                        visited.add(nei)
                        queue.append(nei)
            res = max(res, len(visited))
        return res

