class Solution:
    def subArrayRanges(self, nums: List[int]) -> int:
        n = len(nums)
        # sum of subarray maximums
        def sumOfMax():
            left, right = [0]*n, [0]*n
            stack = []
            for i in range(n):
                while stack and nums[stack[-1]] <= nums[i]:
                    stack.pop()
                left[i] = i - stack[-1] if stack else i + 1
                stack.append(i)
            stack = []
            for i in range(n-1, -1, -1):
                while stack and nums[stack[-1]] < nums[i]:
                    stack.pop()
                right[i] = stack[-1] - i if stack else n - i
                stack.append(i)
            return sum(nums[i]*left[i]*right[i] for i in range(n))
        def sumOfMin():
            left, right = [0]*n, [0]*n
            stack = []
            for i in range(n):
                while stack and nums[stack[-1]] >= nums[i]:
                    stack.pop()
                left[i] = i - stack[-1] if stack else i + 1
                stack.append(i)
            stack = []
            for i in range(n-1, -1, -1):
                while stack and nums[stack[-1]] > nums[i]:
                    stack.pop()
                right[i] = stack[-1] - i if stack else n - i
                stack.append(i)
            return sum(nums[i]*left[i]*right[i] for i in range(n))
        return sumOfMax() - sumOfMin()

class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        n = len(plants)
        left, right = 0, n - 1
        a, b = capacityA, capacityB
        refills = 0
        while left < right:
            if a < plants[left]:
                refills += 1
                a = capacityA
            a -= plants[left]
            if b < plants[right]:
                refills += 1
                b = capacityB
            b -= plants[right]
            left += 1
            right -= 1
        if left == right:
            if max(a, b) < plants[left]:
                refills += 1
        return refills

class Solution:
    def shareCandies(self, candies: List[int], k: int) -> int:
        from collections import Counter
        if k == 0:
            return len(set(candies))
        n = len(candies)
        total = Counter(candies)
        # remove first k elements from outside
        for i in range(k):
            total[candies[i]] -= 1
            if total[candies[i]] == 0:
                del total[candies[i]]
        res = len(total)
        for i in range(k, n):
            # add candies[i] to window (remove from outside)
            total[candies[i]] -= 1
            if total[candies[i]] == 0:
                del total[candies[i]]
            # remove candies[i-k] from window (add back to outside)
            total[candies[i-k]] = total.get(candies[i-k], 0) + 1
            res = max(res, len(total))
        return res

