    def elementInNums(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        res = []
        for t, idx in queries:
            t = t % (2 * n)
            if t < n:
                # removing phase: array is nums[t:]
                arr = nums[t:]
            else:
                # replacing phase: array is nums[:t-n]
                arr = nums[:t-n]
            if idx < len(arr):
                res.append(arr[idx])
            else:
                res.append(-1)
        return res

