class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        from collections import deque, defaultdict
        indegree = {}
        graph = defaultdict(list)
        recipe_set = set(recipes)
        for i, r in enumerate(recipes):
            indegree[r] = len(ingredients[i])
            for ing in ingredients[i]:
                graph[ing].append(r)
        queue = deque(supplies)
        res = []
        while queue:
            item = queue.popleft()
            for r in graph[item]:
                indegree[r] -= 1
                if indegree[r] == 0:
                    res.append(r)
                    queue.append(r)
        return res

class Solution:
    def canBeValid(self, s: str, locked: str) -> bool:
        n = len(s)
        if n % 2 == 1:
            return False
        # left to right: ensure ')' never exceeds available '(' + flexible
        balance = 0
        for i in range(n):
            if locked[i] == '0' or s[i] == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        # right to left
        balance = 0
        for i in range(n-1, -1, -1):
            if locked[i] == '0' or s[i] == ')':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return True

