class Solution:
    def maximumInvitations(self, favorite: List[int]) -> int:
        from collections import deque
        n = len(favorite)
        indegree = [0] * n
        for f in favorite:
            indegree[f] += 1
        # Topological sort to find chains
        queue = deque()
        for i in range(n):
            if indegree[i] == 0:
                queue.append(i)
        depth = [0] * n
        while queue:
            u = queue.popleft()
            v = favorite[u]
            depth[v] = max(depth[v], depth[u] + 1)
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
        # Find cycles
        visited = [False] * n
        max_cycle = 0
        two_cycle_sum = 0
        for i in range(n):
            if visited[i] or indegree[i] == 0:
                continue
            cycle_len = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = favorite[j]
                cycle_len += 1
            if cycle_len == 2:
                two_cycle_sum += 2 + depth[i] + depth[favorite[i]]
            else:
                max_cycle = max(max_cycle, cycle_len)
        return max(max_cycle, two_cycle_sum)

