        start_masks = set()
        for w in startWords:
            mask = 0
            for c in w:
                mask |= 1 << (ord(c) - ord('a'))
            start_masks.add(mask)
        res = 0
        for w in targetWords:
            mask = 0
            for c in w:
                mask |= 1 << (ord(c) - ord('a'))
            for c in w:
                bit = 1 << (ord(c) - ord('a'))
                if (mask ^ bit) in start_masks:
                    res += 1
                    break
        return res

