class Solution:
    def maximumGood(self, statements: List[List[int]]) -> int:
        n = len(statements)
        res = 0
        for mask in range(1, 1 << n):
            valid = True
            for i in range(n):
                if not (mask >> i & 1):
                    continue
                for j in range(n):
                    if statements[i][j] == 0 and (mask >> j & 1):
                        valid = False
                        break
                    if statements[i][j] == 1 and not (mask >> j & 1):
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                res = max(res, bin(mask).count('1'))
        return res

class Solution:
    def minimumLines(self, points: List[List[int]]) -> int:
        n = len(points)
        if n <= 2:
            return 1
        # precompute line masks
        lines = set()
        for i in range(n):
            for j in range(i+1, n):
                mask = 0
                for k in range(n):
                    # check if point k is on line (i,j)
                    dx1 = points[j][0]-points[i][0]
                    dy1 = points[j][1]-points[i][1]
                    dx2 = points[k][0]-points[i][0]
                    dy2 = points[k][1]-points[i][1]
                    if dx1*dy2 == dy1*dx2:
                        mask |= (1<<k)
                lines.add(mask)
        lines = list(lines)
        full = (1<<n)-1
        # BFS/DFS for min lines
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(covered):
            if covered == full:
                return 0
            # find first uncovered point
            for i in range(n):
                if not (covered >> i & 1):
                    break
            res = float('inf')
            for line in lines:
                if line >> i & 1:
                    res = min(res, 1 + dp(covered | line))
            return res
        return dp(0)

