        for i in range(len(nums) + 1):
            score = zeros + ones_right
            scores.append(score)
            max_score = max(max_score, score)
            if i < len(nums):
                if nums[i] == 0:
                    zeros += 1
                else:
                    ones_right -= 1
        return [i for i, s in enumerate(scores) if s == max_score]

class Solution:
    def subStrHash(self, s: str, power: int, modulo: int, k: int, hashValue: int) -> str:
        n = len(s)
        # compute from right to left
        h = 0
        pk = pow(power, k, modulo)
        ans_idx = 0
        for i in range(n-1, -1, -1):
            h = (h * power + (ord(s[i]) - ord('a') + 1)) % modulo
            if i + k < n:
                h = (h - (ord(s[i+k]) - ord('a') + 1) * pk) % modulo
            if h == hashValue:
                ans_idx = i
        return s[ans_idx:ans_idx+k]

class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        parent = {}
        size = {}
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px == py: return
            if size[px] < size[py]: px, py = py, px
            parent[py] = px
            size[px] += size[py]
        masks = []
        mask_map = {}  # mask -> first index representative
        for w in words:
            mask = 0
            for c in w:
                mask |= 1 << (ord(c)-ord('a'))
            masks.append(mask)
            if mask not in parent:
                parent[mask] = mask
                size[mask] = 0
            size[mask] = size.get(mask, 0) + 1
            # Fix: initialize properly
        # reinitialize
        parent = {}
        size = {}
        for mask in masks:
            if mask not in parent:
                parent[mask] = mask
                size[mask] = 1
            else:
                size[find(mask)] = size.get(find(mask), 0)  # already counted
        # Actually let's use index-based UF
        n = len(words)
        par = list(range(n))
        sz = [1]*n
        def find2(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        def union2(x, y):
            px, py = find2(x), find2(y)
            if px == py: return
            if sz[px] < sz[py]: px, py = py, px
            par[py] = px
            sz[px] += sz[py]
        from collections import defaultdict
        mask_to_idx = defaultdict(list)
        word_masks = []
        for i, w in enumerate(words):
            mask = 0
            for c in w:
                mask |= 1 << (ord(c)-ord('a'))
            word_masks.append(mask)
            mask_to_idx[mask].append(i)
        # union same masks
        for indices in mask_to_idx.values():
            for i in range(1, len(indices)):
                union2(indices[0], indices[i])
        # union by delete one bit
        del_map = {}
        for mask, indices in mask_to_idx.items():
            rep = indices[0]
            for bit in range(26):
                if mask >> bit & 1:
                    new_mask = mask ^ (1 << bit)
                    if new_mask in mask_to_idx:
                        union2(rep, mask_to_idx[new_mask][0])
                    if new_mask in del_map:
                        union2(rep, del_map[new_mask])
                    else:
                        del_map[new_mask] = rep
        groups = set()
        max_size = 0
        for i in range(n):
            r = find2(i)
            groups.add(r)
            max_size = max(max_size, sz[r])
        return [len(groups), max_size]

