class Bitset:
    def __init__(self, size):
        self.arr = [0] * size
        self.ones = 0
        self.flipped = False
        self.size = size
    def fix(self, idx):
        if not self.flipped:
            if self.arr[idx] == 0: self.ones += 1
            self.arr[idx] = 1
        else:
            if self.arr[idx] == 1: self.ones += 1
            self.arr[idx] = 0
    def unfix(self, idx):
        if not self.flipped:
            if self.arr[idx] == 1: self.ones -= 1
            self.arr[idx] = 0
        else:
            if self.arr[idx] == 0: self.ones -= 1
            self.arr[idx] = 1
    def flip(self):
        self.flipped = not self.flipped
        self.ones = self.size - self.ones
    def all(self): return self.ones == self.size
    def one(self): return self.ones > 0
    def count(self): return self.ones
    def toString(self):
        if not self.flipped:
            return ''.join(map(str, self.arr))
        return ''.join('1' if x == 0 else '0' for x in self.arr)

class Solution:
    def minimumTime(self, s):
        n = len(s)
        left = [0] * (n + 1)
        for i in range(n):
            if s[i] == '1':
                left[i+1] = min(left[i] + 2, i + 1)
            else:
                left[i+1] = left[i]
        ans = left[n]
        right = 0
        for i in range(n-1, -1, -1):
            if s[i] == '1':
                right = min(right + 2, n - i)
            ans = min(ans, left[i] + right)
        return ans

