from collections import Counter
class Solution:
    def minimumOperations(self, nums):
        n = len(nums)
        def top2(indices):
            cnt = Counter(nums[i] for i in indices)
            items = cnt.most_common(2)
            while len(items) < 2:
                items.append((None, 0))
            return items
        even_idx = range(0, n, 2)
        odd_idx = range(1, n, 2)
        e = top2(even_idx)
        o = top2(odd_idx)
        le = len(range(0, n, 2))
        lo = len(range(1, n, 2))
        if e[0][0] != o[0][0]:
            return (le - e[0][1]) + (lo - o[0][1])
        else:
            return min((le - e[0][1]) + (lo - o[1][1]),
                       (le - e[1][1]) + (lo - o[0][1]))

