from functools import lru_cache
class Solution:
    def maximumANDSum(self, nums, numSlots):
        @lru_cache(maxsize=None)
        def dp(i, mask):
            if i == len(nums): return 0
            res = 0
            for slot in range(1, numSlots + 1):
                b = (mask // (3 ** (slot-1))) % 3
                if b < 2:
                    new_mask = mask + 3 ** (slot-1)
                    res = max(res, (nums[i] & slot) + dp(i+1, new_mask))
            return res
        return dp(0, 0)

from functools import lru_cache
class Solution:
    def removeOnes(self, grid):
        m, n = len(grid), len(grid[0])
        ones = []
        for i in range(m):
            for j in range(n):
                if grid[i][j]: ones.append((i,j))
        k = len(ones)
        if k == 0: return 0
        row_masks = {}
        col_masks = {}
        for i in range(m):
            mask = 0
            for idx, (r,c) in enumerate(ones):
                if r == i: mask |= (1 << idx)
            row_masks[i] = mask
        for j in range(n):
            mask = 0
            for idx, (r,c) in enumerate(ones):
                if c == j: mask |= (1 << idx)
            col_masks[j] = mask
        full = (1 << k) - 1
        @lru_cache(maxsize=None)
        def dp(state):
            if state == 0: return 0
            res = float('inf')
            for idx in range(k):
                if state & (1 << idx):
                    r, c = ones[idx]
                    res = min(res, 1 + dp(state & ~row_masks[r]))
                    res = min(res, 1 + dp(state & ~col_masks[c]))
                    break
            return res
        return dp(full)

