from collections import Counter
class Solution:
    def countPairs(self, nums, k):
        gcds = Counter()
        for num in nums:
            gcds[gcd(num, k)] += 1
        ans = 0
        keys = list(gcds.keys())
        for i in range(len(keys)):
            for j in range(i, len(keys)):
                if (keys[i] * keys[j]) % k == 0:
                    if i == j:
                        ans += gcds[keys[i]] * (gcds[keys[i]] - 1) // 2
                    else:
                        ans += gcds[keys[i]] * gcds[keys[j]]
        return ans

class Solution:
    def buildWall(self, height, width, bricks):
        patterns = []
        def gen(pos, splits):
            if pos == width:
                patterns.append(frozenset(splits))
                return
            for b in bricks:
                if pos + b <= width:
                    if pos + b < width:
                        gen(pos + b, splits | {pos + b})
                    else:
                        gen(pos + b, splits)
        gen(0, set())
        n = len(patterns)
        compat = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if not patterns[i] & patterns[j]:
                    compat[i].append(j)
        MOD = 10**9 + 7
        dp = [1] * n
        for _ in range(height - 1):
            ndp = [0] * n
            for i in range(n):
                for j in compat[i]:
                    ndp[j] = (ndp[j] + dp[i]) % MOD
            dp = ndp
        return sum(dp) % MOD

