class Solution:
    def replaceNonCoprimes(self, nums):
        stack = []
        for num in nums:
            stack.append(num)
            while len(stack) >= 2:
                a, b = stack[-2], stack[-1]
                g = gcd(a, b)
                if g == 1:
                    break
                stack.pop()
                stack.pop()
                stack.append(a * b // g)
        return stack

