from collections import deque, defaultdict
class Solution:
    def distanceToCycle(self, n, edges):
        graph = defaultdict(set)
        degree = [0] * n
        for u, v in edges:
            graph[u].add(v)
            graph[v].add(u)
            degree[u] += 1
            degree[v] += 1
        # remove leaves iteratively
        queue = deque(i for i in range(n) if degree[i] == 1)
        removed = [False] * n
        while queue:
            node = queue.popleft()
            removed[node] = True
            for nei in graph[node]:
                degree[nei] -= 1
                if degree[nei] == 1:
                    queue.append(nei)
        # BFS from cycle nodes
        ans = [0] * n
        queue = deque()
        for i in range(n):
            if not removed[i]:
                queue.append(i)
        visited = [not removed[i] for i in range(n)]
        while queue:
            node = queue.popleft()
            for nei in graph[node]:
                if not visited[nei]:
                    visited[nei] = True
                    ans[nei] = ans[node] + 1
                    queue.append(nei)
        return ans

