class Solution:
    def maximumBobPoints(self, numArrows, aliceArrows):
        best_score = 0
        best_mask = 0
        for mask in range(1 << 12):
            score = 0
            arrows_needed = 0
            for i in range(12):
                if mask & (1 << i):
                    score += i
                    arrows_needed += aliceArrows[i] + 1
            if arrows_needed <= numArrows and score > best_score:
                best_score = score
                best_mask = mask
        res = [0] * 12
        remaining = numArrows
        for i in range(12):
            if best_mask & (1 << i):
                res[i] = aliceArrows[i] + 1
                remaining -= res[i]
        res[0] += remaining
        return res

