        for i in range(5):
            self.bills[i] += banknotesCount[i]

    def withdraw(self, amount):
        take = [0] * 5
        for i in range(4, -1, -1):
            take[i] = min(self.bills[i], amount // self.denoms[i])
            amount -= take[i] * self.denoms[i]
