    def maximumScore(self, scores, edges):
        from collections import defaultdict
        import heapq
        n = len(scores)
        # Keep top 3 neighbors by score for each node
        top = [[] for _ in range(n)]
        for u, v in edges:
            heapq.heappush(top[u], (scores[v], v))
            if len(top[u]) > 3:
                heapq.heappop(top[u])
            heapq.heappush(top[v], (scores[u], u))
            if len(top[v]) > 3:
                heapq.heappop(top[v])
        ans = -1
        for u, v in edges:
            for su, nu in top[u]:
                for sv, nv in top[v]:
                    if nu != v and nv != u and nu != nv:
                        ans = max(ans, scores[u] + scores[v] + su + sv)
        return ans

