class Solution:
    def longestPath(self, parent, s):
        from collections import defaultdict
        n = len(parent)
        children = defaultdict(list)
        for i in range(1, n):
            children[parent[i]].append(i)
        self.ans = 1
        def dfs(node):
            top1 = top2 = 0
            for child in children[node]:
                child_len = dfs(child)
                if s[child] != s[node]:
                    if child_len > top1:
                        top2 = top1
                        top1 = child_len
                    elif child_len > top2:
                        top2 = child_len
            self.ans = max(self.ans, top1 + top2 + 1)
            return top1 + 1
        dfs(0)
        return self.ans

class Solution:
    def maximumCost(self, n, highways, k):
        if k + 1 > n:
            return -1
        adj = [[] for _ in range(n)]
        for u, v, w in highways:
            adj[u].append((v, w))
            adj[v].append((u, w))
        dp = [[-1]*n for _ in range(1<<n)]
        for i in range(n):
            dp[1<<i][i] = 0
        ans = -1
        for mask in range(1<<n):
            if bin(mask).count('1') > k + 1:
                continue
            for u in range(n):
                if dp[mask][u] < 0:
                    continue
                if bin(mask).count('1') == k + 1:
                    ans = max(ans, dp[mask][u])
                for v, w in adj[u]:
                    if mask & (1<<v) == 0:
                        nmask = mask | (1<<v)
                        dp[nmask][v] = max(dp[nmask][v], dp[mask][u] + w)
        return ans

