        for r, c in walls:
            grid[r][c] = 3  # wall
        for r, c in guards:
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                while 0<=nr<m and 0<=nc<n and grid[nr][nc] < 2:
