from collections import deque
class Solution:
    def maximumMinutes(self, grid):
        m, n = len(grid), len(grid[0])
        # BFS to compute fire arrival time
        fire_time = [[float('inf')]*n for _ in range(m)]
        q = deque()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    fire_time[i][j] = 0
                    q.append((i, j, 0))
        while q:
            r, c, t = q.popleft()
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and grid[nr][nc]!=2 and fire_time[nr][nc]>t+1:
                    fire_time[nr][nc] = t+1
                    q.append((nr, nc, t+1))
        def can_escape(wait):
            visited = [[False]*n for _ in range(m)]
            q = deque([(0, 0, wait)])
            visited[0][0] = True
            while q:
                r, c, t = q.popleft()
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<m and 0<=nc<n and not visited[nr][nc] and grid[nr][nc]!=2:
                        nt = t + 1
                        if nr==m-1 and nc==n-1:
                            if nt <= fire_time[nr][nc]:
                                return True
                        elif nt < fire_time[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc, nt))
            return False
        lo, hi = 0, m*n
        if not can_escape(0):
            return -1
        ans = 0
        while lo <= hi:
            mid = (lo+hi)//2
            if can_escape(mid):
                ans = mid
                lo = mid+1
            else:
                hi = mid-1
        return ans if ans < m*n else 10**9

