class Solution:
    def hasValidPath(self, grid):
        m, n = len(grid), len(grid[0])
        if (m + n) % 2 == 0:
            return False
        memo = [[set() for _ in range(n)] for _ in range(m)]
        def dfs(i, j, bal):
            if bal < 0 or bal > (m - i - 1 + n - j - 1):
                return False
            if i == m - 1 and j == n - 1:
                return bal == 0
            if bal in memo[i][j]:
                return False
            memo[i][j].add(bal)
            if i + 1 < m:
                nb = bal + (1 if grid[i+1][j] == '(' else -1)
                if dfs(i+1, j, nb):
                    return True
            if j + 1 < n:
                nb = bal + (1 if grid[i][j+1] == '(' else -1)
                if dfs(i, j+1, nb):
                    return True
            return False
        return dfs(0, 0, 1 if grid[0][0] == '(' else -1)

