class Solution:
    def minimumObstacles(self, grid):
        m, n = len(grid), len(grid[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        dq = deque([(0, 0, 0)])
        while dq:
            d, x, y = dq.popleft()
            if d > dist[x][y]:
                continue
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n:
                    nd = d + grid[nx][ny]
                    if nd < dist[nx][ny]:
                        dist[nx][ny] = nd
                        if grid[nx][ny] == 0:
                            dq.appendleft((nd, nx, ny))
                        else:
                            dq.append((nd, nx, ny))
        return dist[m-1][n-1]

