            self.left.pop()
        return deleted

    def cursorLeft(self, k):
        for _ in range(min(k, len(self.left))):
            self.right.append(self.left.pop())
        return ''.join(self.left[-10:])

    def cursorRight(self, k):
        for _ in range(min(k, len(self.right))):
            self.left.append(self.right.pop())
        return ''.join(self.left[-10:])

class Solution:
    def minCost(self, nums, costs):
        n = len(nums)
        dp = [float('inf')] * n
        dp[0] = 0
        stk1 = []  # increasing: next >= current
        stk2 = []  # decreasing: next < current
        for i in range(n):
            while stk1 and nums[stk1[-1]] <= nums[i]:
                dp[i] = min(dp[i], dp[stk1.pop()] + costs[i])
            while stk2 and nums[stk2[-1]] > nums[i]:
                dp[i] = min(dp[i], dp[stk2.pop()] + costs[i])
            stk1.append(i)
            stk2.append(i)
        return dp[n-1]

