        zeros = s.count('0')
        val = 0
        ones = 0
        power = 0
        for i in range(len(s)-1, -1, -1):
            if s[i] == '0':
                power += 1
            else:
                if val + (1 << power) <= k:
                    val += (1 << power)
                    ones += 1
                power += 1
        return zeros + ones

