        for i in range(1, m+1):
            for j in range(1, n+1):
                dp[i][j] = price.get((i, j), 0)
                for k in range(1, i):
                    dp[i][j] = max(dp[i][j], dp[k][j] + dp[i-k][j])
                for k in range(1, j):
                    dp[i][j] = max(dp[i][j], dp[i][k] + dp[i][j-k])
