class Solution:
    def minimumFlips(self, root, result):
        # dp returns (cost_to_make_0, cost_to_make_1)
        def dfs(node):
            if not node:
                return (0, 0)
            if not node.left and not node.right:
                # leaf
                val = node.val
                return (0, 1) if val == 0 else (1, 0)
            l = dfs(node.left)
            r = dfs(node.right)
            if node.val == 2:  # OR
                make0 = l[0] + r[0]
                make1 = min(l[1] + r[0], l[0] + r[1], l[1] + r[1])
            elif node.val == 3:  # AND
                make0 = min(l[0] + r[0], l[0] + r[1], l[1] + r[0])
                make1 = l[1] + r[1]
            elif node.val == 4:  # XOR
                make0 = min(l[0] + r[0], l[1] + r[1])
                make1 = min(l[0] + r[1], l[1] + r[0])
            else:  # NOT (node.val == 5)
                if node.left:
                    make0, make1 = l[1], l[0]
                else:
                    make0, make1 = r[1], r[0]
            return (make0, make1)
        res = dfs(root)
        return res[result]

