        left = [-1] * n
        right = [n] * n
        stk = []
        for i in range(n):
            while stk and nums[stk[-1]] >= nums[i]:
                right[stk.pop()] = i
            left[i] = stk[-1] if stk else -1
            stk.append(i)
        for i in range(n):
            k = right[i] - left[i] - 1
            if nums[i] > threshold / k:
                return k
        return -1

