class NumberContainers:
    def __init__(self):
        self.idx_to_num = {}
        self.num_to_idx = {}
    def change(self, index, number):
        if index in self.idx_to_num:
            old = self.idx_to_num[index]
            self.num_to_idx[old].discard(index)
            if not self.num_to_idx[old]:
                del self.num_to_idx[old]
        self.idx_to_num[index] = number
        if number not in self.num_to_idx:
            self.num_to_idx[number] = SortedList()
        self.num_to_idx[number].add(index)
