class Solution:
    def closestMeetingNode(self, edges, node1, node2):
        n = len(edges)
        def dist(start):
            d = [-1] * n
            d[start] = 0
            cur = start
            while edges[cur] != -1 and d[edges[cur]] == -1:
                d[edges[cur]] = d[cur] + 1
                cur = edges[cur]
            return d
        d1, d2 = dist(node1), dist(node2)
        ans, best = -1, float('inf')
        for i in range(n):
            if d1[i] != -1 and d2[i] != -1:
                m = max(d1[i], d2[i])
                if m < best:
                    best = m
                    ans = i
        return ans

class Solution:
    def longestCycle(self, edges):
        n = len(edges)
        visited = [0] * n
        ans = -1
        time = [0] * n
        clock = [1]
        for i in range(n):
            if visited[i]:
                continue
            start_time = clock[0]
            cur = i
            while cur != -1 and not visited[cur]:
                visited[cur] = 1
                time[cur] = clock[0]
                clock[0] += 1
                nxt = edges[cur]
                if nxt != -1 and visited[nxt] and time[nxt] >= start_time:
                    ans = max(ans, clock[0] - time[nxt])
                cur = nxt if nxt != -1 and not visited[nxt] else -1
        # Cleaner approach
        ans = -1
        visited = [False] * n
        for i in range(n):
            if visited[i]:
                continue
            cur = i
            path = {}
            step = 0
            while cur != -1 and cur not in path and not visited[cur]:
                path[cur] = step
                step += 1
                cur = edges[cur]
            if cur is not None and cur != -1 and cur in path:
                ans = max(ans, step - path[cur])
            for node in path:
                visited[node] = True
        return ans

