class Solution:
    def minimumReplacement(self, nums):
        n = len(nums)
        ans = 0
        right = nums[-1]
        for i in range(n-2, -1, -1):
            if nums[i] <= right:
                right = nums[i]
            else:
                parts = (nums[i] + right - 1) // right
                ans += parts - 1
                right = nums[i] // parts
        return ans

