            if nums[i-1] == nums[i-2]:
                dp[i] = dp[i] or dp[i-2]
            if i >= 3:
                if nums[i-1] == nums[i-2] == nums[i-3]:
                    dp[i] = dp[i] or dp[i-3]
                if nums[i-1] == nums[i-2] + 1 == nums[i-3] + 2:
