def lengthOfLIS(self, nums, k):
    MAX_VAL = max(nums)
    tree = [0] * (4 * (MAX_VAL + 1))
    def update(node, start, end, idx, val):
        if start == end:
            tree[node] = val
            return
        mid = (start + end) // 2
        if idx <= mid:
            update(2*node, start, mid, idx, val)
        else:
            update(2*node+1, mid+1, end, idx, val)
        tree[node] = max(tree[2*node], tree[2*node+1])
    def query(node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return tree[node]
        mid = (start + end) // 2
        return max(query(2*node, start, mid, l, r), query(2*node+1, mid+1, end, l, r))
    res = 0
    for x in nums:
        best = query(1, 0, MAX_VAL, max(0, x-k), x-1)
        update(1, 0, MAX_VAL, x, best + 1)
        res = max(res, best + 1)
    return res

class SQL:
    def __init__(self, names, columns):
        self.tables = {name: {} for name in names}
        self.ids = {name: 0 for name in names}
    def insertRow(self, name, row):
        self.ids[name] += 1
        self.tables[name][self.ids[name]] = row
    def deleteRow(self, name, rowId):
        if rowId in self.tables[name]:
            del self.tables[name][rowId]
    def selectCell(self, name, rowId, columnId):
        return self.tables[name][rowId][columnId - 1]

def countDaysTogether(self, arriveAlice, leaveAlice, arriveBob, leaveBob):
    days = [31,28,31,30,31,30,31,31,30,31,30,31]
    def to_day(s):
        m, d = int(s[:2]), int(s[3:])
        return sum(days[:m-1]) + d
    a1, a2 = to_day(arriveAlice), to_day(leaveAlice)
    b1, b2 = to_day(arriveBob), to_day(leaveBob)
    overlap = min(a2, b2) - max(a1, b1) + 1
    return max(0, overlap)

