    cnt = Counter(word)
    for c in word:
        cnt[c] -= 1
        if cnt[c] == 0:
            del cnt[c]
        if len(set(cnt.values())) <= 1:
            return True
        cnt[c] = cnt.get(c, 0) + 1
    return False

