def numberOfPairs(self, nums1, nums2, diff):
    arr = [a - b for a, b in zip(nums1, nums2)]
    self.count = 0
    def merge_sort(a):
        if len(a) <= 1:
            return a
        mid = len(a) // 2
        left = merge_sort(a[:mid])
        right = merge_sort(a[mid:])
        j = 0
        for l in left:
            while j < len(right) and l - right[j] > diff:
                j += 1
            self.count += len(right) - j
        return sorted(left + right)
    merge_sort(arr)
    return self.count

