def minimizeXor(self, num1, num2):
    bits_needed = bin(num2).count('1')
    res = 0
    for i in range(29, -1, -1):
        if bits_needed == 0:
            break
        if num1 >> i & 1:
            res |= 1 << i
            bits_needed -= 1
    for i in range(30):
        if bits_needed == 0:
            break
        if not (res >> i & 1):
            res |= 1 << i
            bits_needed -= 1
    return res

def deleteString(self, s):
    n = len(s)
    lcp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if s[i] == s[j]:
                lcp[i][j] = lcp[i+1][j+1] + 1
    dp = [1] * n
    for i in range(n - 1, -1, -1):
        for l in range(1, (n - i) // 2 + 1):
            if lcp[i][i+l] >= l:
                dp[i] = max(dp[i], dp[i+l] + 1)
    return dp[0]

def maxTastiness(self, price, tastiness, maxAmount, maxCoupons):
    n = len(price)
    dp = [[-1] * (maxCoupons + 1) for _ in range(maxAmount + 1)]
    dp[0][0] = 0
    for i in range(n):
        for j in range(maxAmount, -1, -1):
            for k in range(maxCoupons, -1, -1):
                if dp[j][k] < 0:
                    continue
                if j + price[i] <= maxAmount:
                    dp[j + price[i]][k] = max(dp[j + price[i]][k], dp[j][k] + tastiness[i])
                half = price[i] // 2
                if k + 1 <= maxCoupons and j + half <= maxAmount:
                    dp[j + half][k + 1] = max(dp[j + half][k + 1], dp[j][k] + tastiness[i])
    return max(dp[j][k] for j in range(maxAmount + 1) for k in range(maxCoupons + 1) if dp[j][k] >= 0)

def hardestWorker(self, n, logs):
    longest = logs[0][1]
    ans = logs[0][0]
    for i in range(1, len(logs)):
        duration = logs[i][1] - logs[i-1][1]
        if duration > longest or (duration == longest and logs[i][0] < ans):
            longest = duration
            ans = logs[i][0]
    return ans

