def productQueries(self, n, queries):
    MOD = 10**9+7
    powers = []
    bit = 0
    while n:
        if n & 1:
            powers.append(1 << bit)
        n >>= 1
        bit += 1
    res = []
    for l, r in queries:
        prod = 1
        for i in range(l, r+1):
            prod = prod * powers[i] % MOD
        res.append(prod)
    return res

def componentValue(self, nums, edges):
    from collections import defaultdict
    n = len(nums)
    total = sum(nums)
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    def dfs(node, parent, target):
        cur = nums[node]
        for nei in adj[node]:
            if nei == parent:
                continue
            sub = dfs(nei, node, target)
            if sub < 0:
                return -1
            cur += sub
        if cur == target:
            return 0
        if cur > target:
            return -1
        return cur
    for k in range(n, 0, -1):
        if total % k == 0:
            target = total // k
            if dfs(0, -1, target) == 0:
                return k - 1
    return 0

