    for i, x in enumerate(nums):
        if x < minK or x > maxK:
            lastBad = i
        if x == minK:
            lastMin = i
        if x == maxK:
            lastMax = i
        ans += max(0, min(lastMin, lastMax) - lastBad)
    return ans

def numberOfNodes(self, n, queries):
