    for i in range(1, high + 1):
        if i >= zero:
            dp[i] += dp[i - zero]
        if i >= one:
            dp[i] += dp[i - one]
        dp[i] %= MOD
        if i >= low:
            res = (res + dp[i]) % MOD
    return res

def mostProfitablePath(self, edges, bob, amount):
    from collections import defaultdict, deque
    n = len(amount)
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    # Find Bob's path to 0
    parent = [-1] * n
    visited = [False] * n
    visited[bob] = True
    q = deque([bob])
    while q:
        node = q.popleft()
        for nei in g[node]:
            if not visited[nei]:
                visited[nei] = True
                parent[nei] = node
                q.append(nei)
    bob_time = {}
    cur, t = bob, 0
    while cur != -1:
        bob_time[cur] = t
        cur = parent[cur] if cur != 0 else -1
        t += 1
    # DFS for Alice
    res = float('-inf')
    stack = [(0, -1, 0, 0)]  # node, parent, time, income
    while stack:
        node, par, time, income = stack.pop()
        if node in bob_time:
            if time < bob_time[node]:
                income += amount[node]
            elif time == bob_time[node]:
                income += amount[node] // 2
        else:
            income += amount[node]
        children = [nei for nei in g[node] if nei != par]
        if not children:
            res = max(res, income)
        for nei in children:
            stack.append((nei, node, time + 1, income))
    return res

def splitMessage(self, message, limit):
    def digits(x):
        return len(str(x))
    n = len(message)
    for k in range(1, n + 1):
        dk = digits(k)
        overhead = sum(digits(i) + dk + 3 for i in range(1, k + 1))
        if overhead + n <= k * limit:
            # Build result
            res = []
            idx = 0
            for i in range(1, k + 1):
                suffix = f'<{i}/{k}>'
                take = limit - len(suffix)
                res.append(message[idx:idx+take] + suffix)
                idx += take
            return res
    return []

def subarrayLCM(self, nums, k):
