class Allocator:
    def __init__(self, n):
        self.mem = [0] * n
        self.n = n
    def allocate(self, size, mID):
        count = 0
        for i in range(self.n):
            if self.mem[i] == 0:
                count += 1
                if count == size:
                    for j in range(i - size + 1, i + 1):
                        self.mem[j] = mID
                    return i - size + 1
            else:
                count = 0
        return -1
    def freeMemory(self, mID):
        count = 0
        for i in range(self.n):
            if self.mem[i] == mID:
                self.mem[i] = 0
                count += 1
        return count

def similarPairs(self, words):
    from collections import Counter
    masks = []
    for w in words:
        mask = 0
        for c in w:
            mask |= (1 << (ord(c) - ord('a')))
        masks.append(mask)
    cnt = Counter(masks)
    return sum(v * (v-1) // 2 for v in cnt.values())

def smallestValue(self, n):
    while True:
        s = 0
        temp = n
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                s += d
                temp //= d
            d += 1
        if temp > 1:
            s += temp
        if s == n:
            return n
        n = s

def isPossible(self, n, edges):
    from collections import defaultdict
    g = defaultdict(set)
    for u, v in edges:
        g[u].add(v)
        g[v].add(u)
    odd = [node for node in range(1, n+1) if len(g[node]) % 2 == 1]
    if len(odd) == 0:
        return True
    if len(odd) == 2:
        a, b = odd
        if b not in g[a]:
            return True
        for c in range(1, n+1):
            if c != a and c != b and a not in g[c] and b not in g[c]:
                return True
        return False
    if len(odd) == 4:
        a, b, c, d = odd
        # Try all 3 pairings
        if b not in g[a] and d not in g[c]:
            return True
        if c not in g[a] and d not in g[b]:
            return True
        if d not in g[a] and c not in g[b]:
            return True
        return False
    return False

def cycleLengthQueries(self, n, queries):
    res = []
    for a, b in queries:
        length = 1
        while a != b:
            if a > b:
