def maximumTastiness(self, price, k):
    price.sort()
    def can(mid):
        count = 1
        prev = price[0]
        for i in range(1, len(price)):
            if price[i] - prev >= mid:
                count += 1
                prev = price[i]
        return count >= k
    lo, hi = 0, price[-1] - price[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

def countPartitions(self, nums, k):
    MOD = 10**9 + 7
    if sum(nums) < 2 * k:
        return 0
    # Count subsets with sum < k
    dp = [0] * k
    dp[0] = 1
    for x in nums:
        for j in range(k-1, x-1, -1):
            dp[j] = (dp[j] + dp[j-x]) % MOD
    bad = sum(dp) * 2 % MOD
    total = pow(2, len(nums), MOD)
    return (total - bad) % MOD

def distinctPrimeFactors(self, nums):
