    res = 0
    for i in range(maxLength + 1):
        if dp[i] == 0:
            continue
        if i + zeroGroup <= maxLength:
            dp[i + zeroGroup] = (dp[i + zeroGroup] + dp[i]) % MOD
        if i + oneGroup <= maxLength:
            dp[i + oneGroup] = (dp[i + oneGroup] + dp[i]) % MOD
        if i >= minLength:
            res = (res + dp[i]) % MOD
