def timeTaken(self, arrival, state):
    n = len(arrival)
    enter_q = []
    exit_q = []
    ans = [0] * n
    i = 0
    t = 0
    last_used = -1  # -1: not used, 0: enter, 1: exit
    while i < n or enter_q or exit_q:
        while i < n and arrival[i] <= t:
            if state[i] == 1:
                exit_q.append(i)
            else:
                enter_q.append(i)
            i += 1
        if not enter_q and not exit_q:
            t = arrival[i]
            last_used = -1
            continue
        if last_used == -1 or last_used == 1:
            if exit_q:
                ans[exit_q.pop(0)] = t
                last_used = 1
            else:
                ans[enter_q.pop(0)] = t
                last_used = 0
        else:
            if enter_q:
                ans[enter_q.pop(0)] = t
                last_used = 0
            else:
                ans[exit_q.pop(0)] = t
                last_used = 1
        t += 1
    return ans

