        diff[r1][c2+1] -= 1
        diff[r2+1][c1] -= 1
        diff[r2+1][c2+1] += 1
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            diff[i][j] += (diff[i-1][j] if i > 0 else 0) + (diff[i][j-1] if j > 0 else 0) - (diff[i-1][j-1] if i > 0 and j > 0 else 0)
            res[i][j] = diff[i][j]
    return res

