        importance = 0
        for j in range(i, 0, -1):
            x = nums[j-1]
            cnt[x] = cnt.get(x, 0) + 1
            if cnt[x] == 2:
                importance += 2
            elif cnt[x] > 2:
                importance += 1
            dp[i] = min(dp[i], dp[j-1] + importance + k)
    return dp[n]

