    return ''.join(s)

def minimumTime(self, grid):
    import heapq
    if grid[0][1] > 1 and grid[1][0] > 1:
        return -1
    m, n = len(grid), len(grid[0])
    dist = [[float('inf')] * n for _ in range(m)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]
    while heap:
        d, i, j = heapq.heappop(heap)
        if i == m-1 and j == n-1:
            return d
        if d > dist[i][j]:
            continue
        for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < m and 0 <= nj < n:
                wait = 0
                if grid[ni][nj] > d + 1:
                    wait = (grid[ni][nj] - d) % 2
                nd = max(d + 1, grid[ni][nj] + wait)
                if nd < dist[ni][nj]:
                    dist[ni][nj] = nd
                    heapq.heappush(heap, (nd, ni, nj))
    return -1

