def rootCount(self, edges, guesses, k):
    from collections import defaultdict
    n = len(edges) + 1
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    guess_set = set(map(tuple, guesses))
    cnt = [0]
    def dfs(u, parent):
        for v in g[u]:
            if v != parent:
                if (u, v) in guess_set:
                    cnt[0] += 1
                dfs(v, u)
    dfs(0, -1)
    res = [0]
    def reroot(u, parent, cur):
        if cur >= k:
            res[0] += 1
        for v in g[u]:
            if v != parent:
                new_cur = cur - ((u, v) in guess_set) + ((v, u) in guess_set)
                reroot(v, u, new_cur)
    reroot(0, -1, cnt[0])
    return res[0]

def passThePillow(self, n, time):
