def kthLargestLevelSum(self, root, k):
    from collections import deque
    if not root:
        return -1
    q = deque([root])
    sums = []
    while q:
        level_sum = 0
        for _ in range(len(q)):
            node = q.popleft()
            level_sum += node.val
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        sums.append(level_sum)
    if k > len(sums):
        return -1
    sums.sort(reverse=True)
    return sums[k - 1]

def findValidSplit(self, nums):
    from collections import defaultdict
    n = len(nums)
    first = {}
    last = {}
    def factorize(x):
        factors = []
        d = 2
        while d * d <= x:
            if x % d == 0:
                factors.append(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            factors.append(x)
        return factors
    for i, num in enumerate(nums):
        for p in factorize(num):
            if p not in first:
                first[p] = i
            last[p] = i
    # sweep line: for each prime, cover [first[p], last[p]]
    right_max = 0
    diff = [0] * (n + 1)
    for p in first:
        l, r = first[p], last[p]
        if l < r:
            diff[l] += 1
            diff[r] -= 1
    cur = 0
    for i in range(n - 1):
        cur += diff[i]
        if cur == 0:
            return i
    return -1

def waysToReachTarget(self, target, types):
