def findMinimumTime(self, tasks):
    tasks.sort(key=lambda x: x[1])
    max_end = max(t[1] for t in tasks)
    run = [False] * (max_end + 1)
    for start, end, duration in tasks:
        # count already running slots in [start, end]
        already = sum(run[start:end+1])
        need = duration - already
        if need > 0:
            for t in range(end, start - 1, -1):
                if not run[t]:
                    run[t] = True
                    need -= 1
                    if need == 0:
                        break
    return sum(run)

class TodoList:
    def __init__(self):
        self.tasks = {}
        self.task_id = 0
    def addTask(self, userId, taskDescription, dueDate, tags):
        self.task_id += 1
        if userId not in self.tasks:
            self.tasks[userId] = []
        self.tasks[userId].append({'id': self.task_id, 'desc': taskDescription, 'due': dueDate, 'tags': tags, 'done': False})
        return self.task_id
    def getAllTasks(self, userId):
        if userId not in self.tasks:
            return []
        pending = [t for t in self.tasks[userId] if not t['done']]
        pending.sort(key=lambda x: x['due'])
        return [t['desc'] for t in pending]
    def getTasksForTag(self, userId, tag):
        if userId not in self.tasks:
            return []
        pending = [t for t in self.tasks[userId] if not t['done'] and tag in t['tags']]
        pending.sort(key=lambda x: x['due'])
        return [t['desc'] for t in pending]
    def completeTask(self, userId, taskId):
        if userId in self.tasks:
            for t in self.tasks[userId]:
                if t['id'] == taskId:
                    t['done'] = True

def distMoney(self, money, children):
    if money < children:
        return -1
    money -= children  # give 1 to each
    # give 7 more to make 8
    full = min(money // 7, children)
