def minimumCost(self, start, target, specialRoads):
    import heapq
    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])
    nodes = [tuple(start), tuple(target)]
    roads = []
    for x1,y1,x2,y2,c in specialRoads:
        roads.append(((x1,y1),(x2,y2),c))
        nodes.append((x1,y1))
        nodes.append((x2,y2))
    nodes = list(set(nodes))
    best = {node: float('inf') for node in nodes}
    best[tuple(start)] = 0
    heap = [(0, tuple(start))]
    while heap:
        d, u = heapq.heappop(heap)
        if u == tuple(target):
            return d
        if d > best[u]:
            continue
        for v in nodes:
            nd = d + dist(u, v)
            if nd < best[v]:
                best[v] = nd
                heapq.heappush(heap, (nd, v))
        for (s, e, c) in roads:
            nd = d + dist(u, s) + c
            if nd < best[e]:
                best[e] = nd
                heapq.heappush(heap, (nd, e))
    return best[tuple(target)]

