    count = 0
    res = []
    for idx, color in queries:
        old = colors[idx]
        if old != 0:
            if idx > 0 and colors[idx-1] == old:
                count -= 1
            if idx < n-1 and colors[idx+1] == old:
                count -= 1
        colors[idx] = color
        if idx > 0 and colors[idx-1] == color:
            count += 1
        if idx < n-1 and colors[idx+1] == color:
            count += 1
        res.append(count)
    return res

def matrixSum(self, nums):
    for row in nums:
        row.sort()
    return sum(max(col) for col in zip(*nums))

def doesValidArrayExist(self, derived):
    xor = 0
    for d in derived:
        xor ^= d
    return xor == 0

def maxMoves(self, grid):
    m, n = len(grid), len(grid[0])
    curr = set(range(m))
    for j in range(n - 1):
        nxt = set()
        for i in curr:
            for di in (-1, 0, 1):
                ni = i + di
                if 0 <= ni < m and grid[ni][j+1] > grid[i][j]:
                    nxt.add(ni)
        if not nxt:
            return j
        curr = nxt
    return n - 1

def countCompleteComponents(self, n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * n
    res = 0
    for i in range(n):
        if visited[i]:
            continue
        # BFS
        queue = [i]
        visited[i] = True
        comp = []
        while queue:
            node = queue.pop()
            comp.append(node)
            for nei in adj[node]:
                if not visited[nei]:
                    visited[nei] = True
                    queue.append(nei)
        v = len(comp)
        e = sum(len(adj[x]) for x in comp) // 2
        if e == v * (v - 1) // 2:
            res += 1
    return res

def getKthCharacter(self, root, k):
    # Rope tree: left subtree chars come before right
    def dfs(node):
        if not node:
            return ''
        if node.val:
            return node.val
        return dfs(node.left) + dfs(node.right)
    s = dfs(root)
    return s[k - 1]

# JavaScript problem - Event Emitter pattern
# Python equivalent:
class EventEmitter:
    def __init__(self):
        self.events = {}
    def subscribe(self, event, cb):
        if event not in self.events:
            self.events[event] = []
        self.events[event].append(cb)
        return lambda: self.events[event].remove(cb)
    def emit(self, event, args=None):
        if args is None:
            args = []
        return [cb(*args) for cb in self.events.get(event, [])]

