def minLength(self, s):
    stack = []
    for c in s:
        if stack and ((stack[-1] == 'A' and c == 'B') or (stack[-1] == 'C' and c == 'D')):
            stack.pop()
        else:
            stack.append(c)
    return len(stack)

def makeSmallestPalindrome(self, s):
    s = list(s)
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            s[l] = s[r] = min(s[l], s[r])
        l += 1
        r -= 1
    return ''.join(s)

def punishmentNumber(self, n):
    def check(s, target):
        if not s and target == 0:
            return True
        for i in range(1, len(s) + 1):
            if int(s[:i]) > target:
                break
            if check(s[i:], target - int(s[:i])):
                return True
        return False
    res = 0
    for i in range(1, n + 1):
        if check(str(i * i), i):
            res += i * i
    return res

class Solution:
    def minOperations(self, nums: list[int], x: int, y: int) -> int:
        def check(ops):
            budget = ops
            for num in nums:
                need = num - ops * y
                if need > 0:
                    budget -= (need + (x - y) - 1) // (x - y)
            return budget >= 0
        lo, hi = 0, max(nums) // y + 1
        while lo < hi:
            mid = (lo + hi) // 2
            if check(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

