def compact_object(obj):
    if isinstance(obj, list):
        return [compact_object(item) for item in obj if item]
    elif isinstance(obj, dict):
        return {k: compact_object(v) for k, v in obj.items() if v}
    return obj

class Solution:
    def buyChoco(self, prices: list[int], money: int) -> int:
        min1 = min2 = float('inf')
        for p in prices:
            if p < min1:
                min2 = min1
                min1 = p
            elif p < min2:
                min2 = p
        cost = min1 + min2
        return money - cost if cost <= money else money

class Solution:
    def minExtraChar(self, s: str, dictionary: list[str]) -> int:
        n = len(s)
        word_set = set(dictionary)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1
            for j in range(i):
                if s[j:i] in word_set:
                    dp[i] = min(dp[i], dp[j])
        return dp[n]

class Solution:
    def maxStrength(self, nums: list[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        nums.sort()
        result = 1
        neg_count = sum(1 for x in nums if x < 0)
        pos_count = sum(1 for x in nums if x > 0)
        if pos_count == 0 and neg_count <= 1:
            return 0
        for x in nums:
            if x > 0:
                result *= x
        negs = sorted([x for x in nums if x < 0])
        for i in range(0, len(negs) - 1, 2):
            result *= negs[i] * negs[i + 1]
        return result

class Solution:
    def canTraverseAllPairs(self, nums: list[int]) -> bool:
        if len(nums) == 1:
            return True
        if 1 in nums:
            return False
        n = len(nums)
        parent = list(range(n + 100001))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py
        for i, num in enumerate(nums):
            d = 2
            while d * d <= num:
                if num % d == 0:
                    union(i, n + d)
                    while num % d == 0:
                        num //= d
                d += 1
            if num > 1:
                union(i, n + num)
        return len(set(find(i) for i in range(n))) == 1

