class Solution:
    def differenceOfDistinctValues(self, grid: list[list[int]]) -> list[list[int]]:
        m, n = len(grid), len(grid[0])
        ans = [[0] * n for _ in range(m)]
        for d in range(-(m-1), n):
            cells = []
            for i in range(m):
                j = i + d
                if 0 <= j < n:
                    cells.append((i, j))
            seen = set()
            tl = []
            for i, j in cells:
                tl.append(len(seen))
                seen.add(grid[i][j])
            seen = set()
            br = []
            for i, j in reversed(cells):
                br.append(len(seen))
                seen.add(grid[i][j])
            br.reverse()
            for k, (i, j) in enumerate(cells):
                ans[i][j] = abs(tl[k] - br[k])
        return ans

