class Solution:
    def maxIncreasingCells(self, mat: list[list[int]]) -> int:
        from collections import defaultdict
        m, n = len(mat), len(mat[0])
        cells = defaultdict(list)
        for i in range(m):
            for j in range(n):
                cells[mat[i][j]].append((i, j))
        row_max = [0] * m
        col_max = [0] * n
        result = 0
        for val in sorted(cells.keys()):
            updates = []
            for i, j in cells[val]:
                cur = max(row_max[i], col_max[j]) + 1
                updates.append((i, j, cur))
                result = max(result, cur)
            for i, j, cur in updates:
                row_max[i] = max(row_max[i], cur)
                col_max[j] = max(col_max[j], cur)
        return result

import heapq
class Solution:
    def shortestPathWithHops(self, n: int, edges: list[list[int]], s: int, d: int, k: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        dist = [[float('inf')] * (k + 1) for _ in range(n)]
        dist[s][0] = 0
        pq = [(0, s, 0)]
        while pq:
            d_cur, u, hops = heapq.heappop(pq)
            if d_cur > dist[u][hops]:
                continue
            if u == d:
                return d_cur
            for v, w in graph[u]:
                if d_cur + w < dist[v][hops]:
                    dist[v][hops] = d_cur + w
                    heapq.heappush(pq, (d_cur + w, v, hops))
                if hops < k and d_cur < dist[v][hops + 1]:
                    dist[v][hops + 1] = d_cur
                    heapq.heappush(pq, (d_cur, v, hops + 1))
        return min(dist[d])

