class Solution:
    def matrixSumQueries(self, n: int, queries: list[list[int]]) -> int:
        row_set = set()
        col_set = set()
        ans = 0
        for typ, idx, val in reversed(queries):
            if typ == 0:
                if idx not in row_set:
                    ans += val * (n - len(col_set))
                    row_set.add(idx)
            else:
                if idx not in col_set:
                    ans += val * (n - len(row_set))
                    col_set.add(idx)
        return ans

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7
        def calc(num, min_s, max_s):
            from functools import lru_cache
            @lru_cache(maxsize=None)
            def dp(pos, s, tight):
                if s > max_s:
                    return 0
                if pos == len(num):
                    return 1 if s >= min_s else 0
                limit = int(num[pos]) if tight else 9
                res = 0
                for d in range(limit + 1):
                    res += dp(pos + 1, s + d, tight and d == limit)
                return res % MOD
            return dp(0, 0, True)
        ans = (calc(num2, min_sum, max_sum) - calc(num1, min_sum, max_sum)) % MOD
        s = sum(int(c) for c in num1)
        if min_sum <= s <= max_sum:
            ans = (ans + 1) % MOD
        return ans

import asyncio
async def promise_all(functions):
