def join_by_id(arr1, arr2):
    merged = {}
    for obj in arr1:
        merged[obj['id']] = obj.copy()
    for obj in arr2:
        if obj['id'] in merged:
            merged[obj['id']].update(obj)
        else:
            merged[obj['id']] = obj.copy()
    return [merged[k] for k in sorted(merged.keys())]

import threading
def set_interval(fn, args, t):
    cancelled = threading.Event()
    def run():
        while not cancelled.is_set():
            fn(*args)
            cancelled.wait(t / 1000)
    thread = threading.Thread(target=run, daemon=True)
    thread.start()
    return cancelled.set

