class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        left = 0
        pairs = 0
        ans = 1
        for right in range(1, n):
            if s[right] == s[right - 1]:
                pairs += 1
            while pairs > 1:
                left += 1
                if s[left] == s[left - 1]:
                    pairs -= 1
            ans = max(ans, right - left + 1)
        return ans

class Solution:
    def sumDistance(self, nums: list[int], s: str, d: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        pos = []
        for i in range(n):
            if s[i] == 'R':
                pos.append(nums[i] + d)
            else:
                pos.append(nums[i] - d)
        pos.sort()
        ans = 0
        prefix = 0
        for i in range(n):
            ans = (ans + pos[i] * i - prefix) % MOD
            prefix += pos[i]
        return ans

class Solution:
    def goodSubsetofBinaryMatrix(self, grid: list[list[int]]) -> list[int]:
        m = len(grid[0])
        seen = {}
        for i, row in enumerate(grid):
            mask = 0
            for j in range(m):
                if row[j]:
                    mask |= (1 << j)
            if mask == 0:
                return [i]
            seen[mask] = i
        for m1, i1 in seen.items():
            for m2, i2 in seen.items():
                if m1 & m2 == 0:
                    return sorted([i1, i2])
        return []

