class Solution:
    def minCost(self, nums: list[int], x: int) -> int:
        n = len(nums)
        min_cost = nums[:]
        ans = sum(nums)
        for rot in range(1, n):
            for i in range(n):
                min_cost[i] = min(min_cost[i], nums[(i + rot) % n])
            ans = min(ans, rot * x + sum(min_cost))
        return ans

from bisect import bisect_left
class Solution:
    def maximumSumQueries(self, nums1: list[int], nums2: list[int], queries: list[list[int]]) -> list[int]:
        n = len(nums1)
        pairs = sorted(zip(nums1, nums2), key=lambda x: -x[0])
        q_sorted = sorted(range(len(queries)), key=lambda i: -queries[i][0])
        ans = [-1] * len(queries)
        stack = []  # monotonic stack of (y, x+y), y increasing, x+y decreasing
        j = 0
        for qi in q_sorted:
            xi, yi = queries[qi]
            while j < n and pairs[j][0] >= xi:
                x, y = pairs[j]
                s = x + y
                while stack and stack[-1][1] <= s:
                    stack.pop()
                if not stack or y > stack[-1][0]:
                    stack.append((y, s))
                j += 1
            idx = bisect_left(stack, (yi,))
            if idx < len(stack):
                ans[qi] = stack[idx][1]
        return ans

import heapq
class Solution:
    def minimumDistance(self, n: int, edges: list[list[int]], s: int, marked: list[int]) -> int:
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        dist = [float('inf')] * n
        dist[s] = 0
        pq = [(0, s)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(pq, (dist[v], v))
        ans = min(dist[m] for m in marked)
        return ans if ans != float('inf') else -1

class Solution:
    def distanceTraveled(self, mainTank: int, additionalTank: int) -> int:
        distance = 0
        while mainTank >= 5:
            consumed = mainTank // 5
            distance += consumed * 5 * 10
            mainTank = mainTank % 5 + min(consumed, additionalTank)
            additionalTank -= min(consumed, additionalTank)
        distance += mainTank * 10
        return distance

