class Solution:
    def makeTheIntegerZero(self, num1: int, num2: int) -> int:
        for k in range(1, 61):
            remain = num1 - k * num2
            if remain < 0:
                continue
            if bin(remain).count('1') <= k <= remain:
                return k
        return -1

class Solution:
    def numberOfGoodSubarraySplits(self, nums: list[int]) -> int:
        MOD = 10**9 + 7
        ones = [i for i, x in enumerate(nums) if x == 1]
        if not ones:
            return 0
        ans = 1
        for i in range(1, len(ones)):
            ans = ans * (ones[i] - ones[i-1]) % MOD
        return ans

class Solution:
    def survivedRobotsHealths(self, positions: list[int], healths: list[int], directions: str) -> list[int]:
        n = len(positions)
        indices = sorted(range(n), key=lambda i: positions[i])
        stack = []
        result = [0] * n
        for i in indices:
            if directions[i] == 'R':
                stack.append(i)
            else:
                while stack and healths[i] > 0:
                    top = stack[-1]
                    if healths[top] < healths[i]:
                        stack.pop()
                        healths[i] -= 1
                    elif healths[top] > healths[i]:
                        healths[top] -= 1
                        healths[i] = 0
                    else:
                        stack.pop()
                        healths[i] = 0
                if healths[i] > 0:
                    result[i] = healths[i]
        for i in stack:
            result[i] = healths[i]
        return [result[i] for i in range(n) if result[i] > 0]

