from functools import partial
def bind_context(fn, obj):
    def bound(*args, **kwargs):
        return fn(obj, *args, **kwargs)
    return bound

def deep_merge(obj1, obj2):
    if isinstance(obj1, dict) and isinstance(obj2, dict):
        result = obj1.copy()
        for key in obj2:
            if key in result:
                result[key] = deep_merge(result[key], obj2[key])
            else:
                result[key] = obj2[key]
        return result
    return obj2

class Solution:
    def circularPermutation(self, n: int, start: int) -> list[int]:
        result = []
        for i in range(1 << n):
            result.append(start ^ i ^ (i >> 1))
        return result

