    def longestAlternatingSubarray(self, nums: list[int], threshold: int) -> int:
        n = len(nums)
        ans = 0
        i = 0
        while i < n:
            if nums[i] % 2 == 0 and nums[i] <= threshold:
                j = i + 1
                while j < n and nums[j] % 2 != nums[j-1] % 2 and nums[j] <= threshold:
                    j += 1
                ans = max(ans, j - i)
                i = j
            else:
                i += 1
        return ans

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        sieve = [True] * (n + 1)
        sieve[0] = sieve[1] = False
        for i in range(2, int(n**0.5) + 1):
            if sieve[i]:
                for j in range(i*i, n + 1, i):
                    sieve[j] = False
        res = []
        for i in range(2, n // 2 + 1):
            if sieve[i] and sieve[n - i]:
                res.append([i, n - i])
        return res

class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        from collections import deque
        n = len(nums)
        maxq, minq = deque(), deque()
        left = 0
        res = 0
        for right in range(n):
            while maxq and nums[maxq[-1]] <= nums[right]:
                maxq.pop()
            maxq.append(right)
            while minq and nums[minq[-1]] >= nums[right]:
                minq.pop()
            minq.append(right)
            while nums[maxq[0]] - nums[minq[0]] > 2:
                left += 1
                if maxq[0] < left:
                    maxq.popleft()
                if minq[0] < left:
                    minq.popleft()
            res += right - left + 1
        return res

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        from sortedcontainers import SortedList
        n = len(nums)
        res = 0
        for i in range(n):
            sl = SortedList()
            imbalance = 0
            for j in range(i, n):
                pos = sl.bisect_left(nums[j])
                # Check neighbors
                inc = 0
                if pos < len(sl) and sl[pos] - nums[j] > 1:
                    inc += 1
                if pos > 0 and nums[j] - sl[pos-1] > 1:
                    inc += 1
                if pos > 0 and pos < len(sl) and sl[pos] - sl[pos-1] > 1:
                    inc -= 1
                if nums[j] in sl:
                    inc -= 1  # duplicate doesn't add imbalance
                    inc = 0
                    # recalculate
                else:
                    imbalance += inc
                sl.add(nums[j])
                res += imbalance
        return res

class Solution:
    def isPreorder(self, nodes: List[List[int]]) -> bool:
        stack = [nodes[0][0]]
        parent = {nodes[0][0]: -1}
        for i in range(1, len(nodes)):
            node, par = nodes[i]
            while stack and stack[-1] != par:
                stack.pop()
            if not stack:
                return False
            stack.append(node)
        return True

