class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        powers = set()
        p = 1
        while p < (1 << len(s)):
            powers.add(bin(p)[2:])
            p *= 5
        n = len(s)
        res = float('inf')
        def dfs(i, cnt):
            nonlocal res
            if i == n:
                res = min(res, cnt)
                return
            if s[i] == '0':
                return
            for j in range(i+1, n+1):
                if s[i:j] in powers:
                    dfs(j, cnt + 1)
        dfs(0, 0)
        return res if res != float('inf') else -1

class Solution:
