        from collections import Counter
        block_count = Counter()
        for r, c in coordinates:
            for dr in range(2):
                for dc in range(2):
                    br, bc = r - dr, c - dc
                    if 0 <= br < m - 1 and 0 <= bc < n - 1:
                        block_count[(br, bc)] += 1
        res = [0] * 5
        for cnt in block_count.values():
            res[cnt] += 1
        res[0] = (m - 1) * (n - 1) - sum(res[1:])
