class Solution:
    def numberOfCategories(self, n: int, categoryHandler) -> int:
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py
        for i in range(n):
            for j in range(i+1, n):
                if categoryHandler.haveSameCategory(i, j):
                    union(i, j)
        return len(set(find(i) for i in range(n)))

