        # dp[0] = max score ending with even, dp[1] = max score ending with odd
        dp = [-float('inf')] * 2
        dp[nums[0] % 2] = nums[0]
        for i in range(1, len(nums)):
            parity = nums[i] % 2
            dp[parity] = max(dp[parity] + nums[i], dp[1 - parity] + nums[i] - x)
