class Solution:
    def maximumSafenessFactor(self, grid):
        from collections import deque
        n = len(grid)
        dist = [[float('inf')] * n for _ in range(n)]
        q = deque()
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    dist[i][j] = 0
                    q.append((i, j))
        while q:
            x, y = q.popleft()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < n and dist[nx][ny] > dist[x][y] + 1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))
        def check(mid):
            if dist[0][0] < mid or dist[n-1][n-1] < mid:
                return False
            visited = [[False]*n for _ in range(n)]
            dq = deque([(0, 0)])
            visited[0][0] = True
            while dq:
                x, y = dq.popleft()
                if x == n-1 and y == n-1:
                    return True
                for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny] and dist[nx][ny] >= mid:
                        visited[nx][ny] = True
                        dq.append((nx, ny))
            return False
        lo, hi = 0, n * 2
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def findMaximumElegance(self, items, k):
        items.sort(key=lambda x: -x[0])
        total_profit = 0
        categories = set()
        duplicates = []  # stack of duplicate profits
        for i in range(k):
            total_profit += items[i][0]
            if items[i][1] in categories:
                duplicates.append(items[i][0])
            categories.add(items[i][1])
        ans = total_profit + len(categories) ** 2
        for i in range(k, len(items)):
            if items[i][1] not in categories and duplicates:
                total_profit -= duplicates.pop()
                total_profit += items[i][0]
                categories.add(items[i][1])
                ans = max(ans, total_profit + len(categories) ** 2)
        return ans

class Solution:
    def minimumTime(self, grid):
        from collections import deque
        m, n = len(grid), len(grid[0])
        flood_time = [[float('inf')] * n for _ in range(m)]
        q = deque()
        start = end = None
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '*':
                    flood_time[i][j] = 0
                    q.append((i, j))
                elif grid[i][j] == 'S':
                    start = (i, j)
                elif grid[i][j] == 'D':
                    end = (i, j)
        while q:
            x, y = q.popleft()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0<=nx<m and 0<=ny<n and flood_time[nx][ny]==float('inf') and grid[nx][ny]!='X' and grid[nx][ny]!='D':
                    flood_time[nx][ny] = flood_time[x][y] + 1
                    q.append((nx, ny))
        dist = [[float('inf')]*n for _ in range(m)]
        dist[start[0]][start[1]] = 0
        q = deque([start])
        while q:
            x, y = q.popleft()
            if (x, y) == end:
                return dist[x][y]
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0<=nx<m and 0<=ny<n and dist[nx][ny]==float('inf') and grid[nx][ny]!='X':
                    if dist[x][y]+1 < flood_time[nx][ny] or (nx,ny)==end:
                        dist[nx][ny] = dist[x][y]+1
                        q.append((nx, ny))
        return -1

