class Solution:
    def doubleIt(self, head):
        def reverse(node):
            prev = None
            while node:
                nxt = node.next
                node.next = prev
                prev = node
                node = nxt
            return prev
        head = reverse(head)
        curr = head
        carry = 0
        prev = None
        while curr:
            val = curr.val * 2 + carry
            curr.val = val % 10
            carry = val // 10
            prev = curr
            curr = curr.next
        if carry:
            prev.next = ListNode(carry)
