class Solution:
    def maximumScore(self, nums, k):
        MOD = 10**9 + 7
        n = len(nums)
        def prime_score(x):
            count = 0
            d = 2
            while d * d <= x:
                if x % d == 0:
                    count += 1
                    while x % d == 0:
                        x //= d
                d += 1
            if x > 1:
                count += 1
            return count
        scores = [prime_score(x) for x in nums]
        left = [-1] * n
        right = [n] * n
        stack = []
        for i in range(n):
            while stack and scores[stack[-1]] < scores[i]:
                right[stack.pop()] = i
            left[i] = stack[-1] if stack else -1
            stack.append(i)
        pairs = sorted(range(n), key=lambda i: -nums[i])
        ans = 1
        for i in pairs:
            cnt = (i - left[i]) * (right[i] - i)
            use = min(cnt, k)
            ans = ans * pow(nums[i], use, MOD) % MOD
            k -= use
            if k == 0:
                break
        return ans

class Solution:
    def minimumRelativeLosses(self, prices, queries):
        prices.sort()
        n = len(prices)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + prices[i]
        ans = []
        for budget, k in queries:
            lo, hi = 0, k
            while lo < hi:
                mid = (lo + hi) // 2
                # mid items from front, k-mid from back
                if prices[mid] <= 2 * budget - prices[n - (k - mid)]:
                    lo = mid + 1
                else:
                    hi = mid
            front = lo
            back = k - front
            loss = prefix[front] + (2 * budget * back - (prefix[n] - prefix[n - back]))
            ans.append(loss)
        return ans

# JavaScript problem - Python equivalent:
def invert_object(obj):
    res = {}
    for k, v in obj.items():
        v_str = str(v)
        if v_str in res:
            if isinstance(res[v_str], list):
                res[v_str].append(k)
            else:
                res[v_str] = [res[v_str], k]
        else:
            res[v_str] = k
    return res

# JavaScript problem - Python equivalent:
def deep_filter(obj, fn):
    if isinstance(obj, dict):
        res = {}
        for k, v in obj.items():
            filtered = deep_filter(v, fn)
            if filtered is not None:
                res[k] = filtered
        return res if res else None
    elif isinstance(obj, list):
        res = [deep_filter(x, fn) for x in obj]
        res = [x for x in res if x is not None]
        return res if res else None
    else:
        return obj if fn(obj) else None

def countPairs(self, nums, target):
    nums.sort()
    left, right = 0, len(nums) - 1
    count = 0
    while left < right:
        if nums[left] + nums[right] < target:
            count += right - left
            left += 1
        else:
            right -= 1
    return count

def canMakeSubsequence(self, str1, str2):
    j = 0
    for c in str1:
        if j < len(str2):
            next_c = chr((ord(c) - ord('a') + 1) % 26 + ord('a'))
            if c == str2[j] or next_c == str2[j]:
                j += 1
    return j == len(str2)

def numberOfBeautifulIntegers(self, low, high, k):
    def count(num):
        s = str(num)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(pos, rem, diff, tight, started):
            if pos == len(s):
                return 1 if started and rem == 0 and diff == 0 else 0
            limit = int(s[pos]) if tight else 9
            res = 0
            for d in range(0, limit + 1):
                new_tight = tight and (d == limit)
                new_started = started or (d > 0)
                new_rem = (rem * 10 + d) % k if new_started else 0
                new_diff = diff
                if new_started:
                    if not started and d > 0:
                        new_diff = -1 if d % 2 == 1 else 1
                    elif started:
                        new_diff = diff + (-1 if d % 2 == 1 else 1)
                res += dp(pos + 1, new_rem, new_diff, new_tight, new_started)
            return res
        return dp(0, 0, 0, True, False)
    return count(high) - count(low - 1)

def minimumSum(self, n, k):
    half = k // 2
    if n <= half:
        return n * (n + 1) // 2
    else:
        # take 1..half, then take k, k+1, ..., k + (n - half - 1)
        remain = n - half
        return half * (half + 1) // 2 + remain * k + remain * (remain - 1) // 2

def maximizeTheProfit(self, n, offers):
    from collections import defaultdict
    end_map = defaultdict(list)
    for s, e, gold in offers:
        end_map[e].append((s, gold))
    dp = [0] * (n + 1)
    for i in range(n):
        dp[i + 1] = dp[i]
        for s, gold in end_map[i]:
            dp[i + 1] = max(dp[i + 1], dp[s] + gold)
    return dp[n]

def longestEqualSubarray(self, nums, k):
    from collections import defaultdict
    groups = defaultdict(list)
    for i, v in enumerate(nums):
        groups[v].append(i)
    ans = 0
    for indices in groups.values():
        left = 0
        for right in range(len(indices)):
            # window length in original array
            while indices[right] - indices[left] + 1 - (right - left + 1) > k:
                left += 1
            ans = max(ans, right - left + 1)
    return ans

def minimumPossibleSum(self, n, target):
    MOD = 10**9 + 7
    half = target // 2
    if n <= half:
        return n * (n + 1) // 2 % MOD
    else:
        remain = n - half
        return (half * (half + 1) // 2 + remain * target + remain * (remain - 1) // 2) % MOD

def minOperations(self, nums, target):
    if sum(nums) < target:
        return -1
    cnt = [0] * 32
    for x in nums:
        cnt[x.bit_length() - 1] += 1
    ops = 0
    for i in range(31):
        if target >> i & 1:
            if cnt[i] > 0:
                cnt[i] -= 1
            else:
                # find smallest j > i with cnt[j] > 0
                j = i + 1
                while j < 32 and cnt[j] == 0:
                    j += 1
                if j == 32:
                    return -1
                # split from j down to i
                while j > i:
                    cnt[j] -= 1
                    cnt[j-1] += 2
                    ops += 1
                    j -= 1
                cnt[i] -= 1
        # carry: merge pairs
        cnt[i+1] += cnt[i] // 2 if i + 1 < 32 else 0
    return ops

def countSymmetricIntegers(self, low, high):
    count = 0
    for x in range(low, high + 1):
        s = str(x)
        n = len(s)
        if n % 2 == 0:
            half = n // 2
            if sum(int(c) for c in s[:half]) == sum(int(c) for c in s[half:]):
                count += 1
    return count

def minimumOperations(self, num):
    n = len(num)
    ans = n  # delete all (leaving 0 if original has 0, else n)
    # check if contains '0' -> can delete all others to get '0'
    if '0' in num:
        ans = n - 1
    for target in ['00', '25', '50', '75']:
        j = len(target) - 1
        i = n - 1
        while i >= 0 and j >= 0:
            if num[i] == target[j]:
                j -= 1
            i -= 1
        if j < 0:
            # found: deletions = chars after the matched subsequence positions
            ans = min(ans, n - (i + 1) - len(target))
    return ans

def minOperationsQueries(self, n, edges, queries):
    from collections import defaultdict
    LOG = n.bit_length()
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    depth = [0] * n
    parent = [[0]*n for _ in range(LOG)]
    freq = [[[0]*27 for _ in range(n)] for _ in range(LOG)]
    # BFS to set up
    from collections import deque
    visited = [False] * n
    visited[0] = True
    queue = deque([0])
    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                parent[0][v] = u
                freq[0][v][w] = 1
                queue.append(v)
    for j in range(1, LOG):
        for i in range(n):
            parent[j][i] = parent[j-1][parent[j-1][i]]
            for w in range(1, 27):
                freq[j][i][w] = freq[j-1][i][w] + freq[j-1][parent[j-1][i]][w]
    def lca_query(u, v):
        if depth[u] < depth[v]: u, v = v, u
        diff = depth[u] - depth[v]
        cnt = [0] * 27
        for j in range(LOG):
            if diff >> j & 1:
                for w in range(1, 27):
                    cnt[w] += freq[j][u][w]
                u = parent[j][u]
        if u == v:
            path_len = sum(cnt[1:])
            return path_len - max(cnt[1:]) if path_len > 0 else 0
        for j in range(LOG-1, -1, -1):
            if parent[j][u] != parent[j][v]:
                for w in range(1, 27):
                    cnt[w] += freq[j][u][w] + freq[j][v][w]
                u = parent[j][u]
                v = parent[j][v]
        for w in range(1, 27):
            cnt[w] += freq[0][u][w] + freq[0][v][w]
        path_len = sum(cnt[1:])
        return path_len - max(cnt[1:]) if path_len > 0 else 0
    return [lca_query(u, v) for u, v in queries]

def smallestNumber(self, n):
    if n == 1:
        return '1'
    digits = []
    for d in range(9, 1, -1):
        while n % d == 0:
            digits.append(d)
            n //= d
    if n > 1:
        return '-1'
    digits.sort()
    return ''.join(map(str, digits))

def numberOfPoints(self, nums):
    nums.sort()
    merged = []
    for s, e in nums:
        if merged and s <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return sum(e - s + 1 for s, e in merged)

def isReachableAtTime(self, sx, sy, fx, fy, t):
    dx = abs(sx - fx)
    dy = abs(sy - fy)
    if dx == 0 and dy == 0:
        return t != 1
    return t >= max(dx, dy)

def minimumMoves(self, grid):
    from itertools import permutations
    excess = []
    deficit = []
    for i in range(3):
        for j in range(3):
            if grid[i][j] > 1:
                for _ in range(grid[i][j] - 1):
                    excess.append((i, j))
            elif grid[i][j] == 0:
                deficit.append((i, j))
    ans = float('inf')
    for perm in permutations(range(len(excess))):
        cost = sum(abs(excess[perm[i]][0] - deficit[i][0]) + abs(excess[perm[i]][1] - deficit[i][1]) for i in range(len(deficit)))
        ans = min(ans, cost)
    return ans

def numberOfWays(self, s, t, k):
    MOD = 10**9 + 7
    n = len(s)
    # Find number of valid rotations using KMP on t + s + s
    def kmp_count(text, pattern):
        lps = [0] * len(pattern)
        j = 0
        for i in range(1, len(pattern)):
            while j and pattern[i] != pattern[j]:
                j = lps[j-1]
            if pattern[i] == pattern[j]:
                j += 1
            lps[i] = j
        count = 0
        j = 0
        for i in range(len(text)):
            while j and text[i] != pattern[j]:
                j = lps[j-1]
            if text[i] == pattern[j]:
                j += 1
            if j == len(pattern):
                count += 1
                j = lps[j-1]
        return count
    m = kmp_count((s + s)[1:], t)  # rotations that match (excluding 0)
    has_zero = 1 if s == t else 0
    m_match = m + has_zero  # total rotations matching (0..n-1)
    # Matrix exponent: states = {match, no_match}
    # transition: from match, choose one of m_match-1 matches or n-m_match non-matches
    # Actually use formula: f(k) for number of ways
    def mat_mul(A, B):
        return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % MOD, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % MOD],
                [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % MOD, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % MOD]]
    def mat_pow(M, p):
        result = [[1,0],[0,1]]
        while p:
            if p & 1:
                result = mat_mul(result, M)
            M = mat_mul(M, M)
            p >>= 1
        return result
    # Transition matrix: from state match/non-match
    # match -> match: m_match - 1 choices, match -> non: n - m_match
    # non -> match: m_match choices, non -> non: n - m_match - 1
    M = [[m_match - 1, n - m_match], [m_match, n - m_match - 1]]
    res = mat_pow(M, k)
    # initial state: s == t -> start in match state
    if s == t:
        return res[0][0] % MOD
    else:
        return res[1][0] % MOD

def sumRemoteness(self, grid):
    n, m = len(grid), len(grid[0])
    total = 0
    cells = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != -1:
                total += grid[i][j]
                cells += 1
    visited = [[False]*m for _ in range(n)]
    ans = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != -1 and not visited[i][j]:
                # BFS to find component
                comp_sum = 0
                comp_size = 0
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    comp_sum += grid[x][y]
                    comp_size += 1
                    for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nx, ny = x+dx, y+dy
                        if 0<=nx<n and 0<=ny<m and not visited[nx][ny] and grid[nx][ny]!=-1:
                            visited[nx][ny] = True
                            stack.append((nx, ny))
                # each cell in this component contributes (total - comp_sum) to remoteness
                ans += comp_size * (total - comp_sum)
    return ans

def minimumRightShifts(self, nums):
    n = len(nums)
    drops = 0
    drop_idx = 0
    for i in range(n):
        if nums[i] > nums[(i + 1) % n]:
            drops += 1
            drop_idx = (i + 1) % n
    if drops == 0:
        return 0
    if drops == 1:
        return n - drop_idx
    return -1

def minEdgeReversals(self, n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append((v, 0))  # forward edge, no reversal needed
        adj[v].append((u, 1))  # backward edge, reversal needed
    # DFS from 0 to count reversals
    ans = [0] * n
    def dfs(u, parent):
        for v, cost in adj[u]:
            if v != parent:
                ans[0] += cost
                dfs(v, u)
    dfs(0, -1)
    # Reroot
    def reroot(u, parent):
        for v, cost in adj[u]:
            if v != parent:
                # edge u->v: cost=0 means forward, moving root to v means we now need to reverse it: +1
                # edge v->u: cost=1 means we reversed it for root=0, now it's free: -1
                ans[v] = ans[u] + (1 if cost == 0 else -1)
                reroot(v, u)
    reroot(0, -1)
    return ans

def countWays(self, nums):
    nums.sort()
    n = len(nums)
    ans = 0
    # select 0 students
    if nums[0] > 0:
        ans += 1
    for i in range(n):
        selected = i + 1
        # nums[i] < selected (current student happy to be selected)
        if nums[i] < selected:
            # next student (if exists) must have threshold > selected
            if i == n - 1 or nums[i + 1] > selected:
                ans += 1
    return ans

def maxNumberOfAlloys(self, n, k, budget, composition, stock, cost):
    def can_make(target):
        for machine in range(k):
            total_cost = 0
            for j in range(n):
                need = max(0, composition[machine][j] * target - stock[j])
                total_cost += need * cost[j]
                if total_cost > budget:
                    break
            if total_cost <= budget:
                return True
        return False
    lo, hi = 0, 10**9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_make(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

def maximumSum(self, nums):
    from collections import defaultdict
    n = len(nums)
    def square_free(x):
        res = 1
        d = 2
        while d * d <= x:
            cnt = 0
            while x % d == 0:
                x //= d
                cnt += 1
            if cnt % 2 == 1:
                res *= d
            d += 1
        if x > 1:
            res *= x
        return res
    groups = defaultdict(int)
    for i in range(1, n + 1):
        groups[square_free(i)] += nums[i - 1]
    return max(groups.values())

def maximumSumOfHeights(self, maxHeights):
    n = len(maxHeights)
    # left[i] = max sum of mountain left side ending at i
    left = [0] * n
    stack = []
    for i in range(n):
        while stack and maxHeights[stack[-1]] >= maxHeights[i]:
            stack.pop()
        if not stack:
            left[i] = maxHeights[i] * (i + 1)
        else:
            left[i] = left[stack[-1]] + maxHeights[i] * (i - stack[-1])
        stack.append(i)
    right = [0] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and maxHeights[stack[-1]] >= maxHeights[i]:
            stack.pop()
        if not stack:
            right[i] = maxHeights[i] * (n - i)
        else:
            right[i] = right[stack[-1]] + maxHeights[i] * (stack[-1] - i)
        stack.append(i)
    return max(left[i] + right[i] - maxHeights[i] for i in range(n))

def maximumSumOfHeights(self, maxHeights):
    n = len(maxHeights)
    left = [0] * n
    stack = []
    for i in range(n):
        while stack and maxHeights[stack[-1]] >= maxHeights[i]:
            stack.pop()
        if not stack:
            left[i] = maxHeights[i] * (i + 1)
        else:
            left[i] = left[stack[-1]] + maxHeights[i] * (i - stack[-1])
        stack.append(i)
    right = [0] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and maxHeights[stack[-1]] >= maxHeights[i]:
            stack.pop()
        if not stack:
            right[i] = maxHeights[i] * (n - i)
        else:
            right[i] = right[stack[-1]] + maxHeights[i] * (stack[-1] - i)
        stack.append(i)
    return max(left[i] + right[i] - maxHeights[i] for i in range(n))

def countPaths(self, n, edges):
    # Sieve of primes up to n
    is_prime = [False] * (n + 1)
    for i in range(2, n + 1):
        is_prime[i] = True
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n+1, i):
                is_prime[j] = False
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    # Union-Find for non-prime components
    parent = list(range(n + 1))
    size = [1] * (n + 1)
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        px, py = find(x), find(y)
        if px == py: return
        if size[px] < size[py]: px, py = py, px
        parent[py] = px
        size[px] += size[py]
    for u, v in edges:
        if not is_prime[u] and not is_prime[v]:
            union(u, v)
    ans = 0
    for u in range(1, n + 1):
        if not is_prime[u]:
            continue
        # u is prime, look at adjacent non-prime components
        components = []
        for v in adj[u]:
            if not is_prime[v]:
                components.append(size[find(v)])
        # paths through u with exactly one prime (u itself)
        total = 0
        for sz in components:
            ans += sz + total * sz
            total += sz
        ans += 1  # path of just u? No, path needs length >= 1
        # actually single edges from u to non-prime are counted in sz
    # But we also count paths that are just u to a non-prime neighbor
    # The formula: for each prime u, paths = sum(sz_i) + sum(sz_i * sz_j for i<j)
    # Let me fix
    ans = 0
    for u in range(1, n + 1):
        if not is_prime[u]: continue
        components = []
        for v in adj[u]:
            if not is_prime[v]:
                components.append(size[find(v)])
        s = sum(components)
        ans += s  # paths: non-prime -> prime u
        # paths through u between two different components
        for sz in components:
            ans += sz * (s - sz) // 1
        # but double counted pairs
    # Fix: use prefix sum approach
    ans = 0
    for u in range(1, n + 1):
        if not is_prime[u]: continue
        prev = 0
        for v in adj[u]:
            if not is_prime[v]:
                sz = size[find(v)]
                ans += sz * (prev + 1)
                prev += sz
    return ans

def canAliceWin(self, a, b):
    # Alice plays from a, Bob from b
    # Each player must play word > last word (by first char comparison)
    i, j = 0, 0
    last = ''
    alice_turn = True
    while True:
        if alice_turn:
            # find next playable word in a
            while i < len(a) and a[i] <= last:
                i += 1
            if i >= len(a):
                return False
            last = a[i]
            i += 1
        else:
            while j < len(b) and b[j] <= last:
                j += 1
            if j >= len(b):
                return True
            last = b[j]
            j += 1
        alice_turn = not alice_turn

def minOperations(self, nums, k):
    seen = set()
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] <= k:
            seen.add(nums[i])
        if len(seen) == k:
            return len(nums) - i
    return len(nums)

def minOperations(self, nums):
    from collections import Counter
    freq = Counter(nums)
    ops = 0
    for f in freq.values():
        if f == 1:
            return -1
        ops += (f + 2) // 3
    return ops

def maxSubarrays(self, nums):
    total_and = nums[0]
    for x in nums:
        total_and &= x
    if total_and != 0:
        return 1
    count = 0
    running = -1  # all bits set
    for x in nums:
        running &= x
        if running == 0:
            count += 1
            running = -1
    return max(count, 1)

def maxKDivisibleComponents(self, n, edges, values, k):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    ans = 0
    def dfs(u, parent):
        nonlocal ans
        total = values[u]
        for v in adj[u]:
            if v != parent:
                total += dfs(v, u)
        if total % k == 0:
            ans += 1
            return 0
        return total
    dfs(0, -1)
    return ans

def countVisitedNodes(self, edges):
    n = len(edges)
    ans = [0] * n
    visited = [0] * n  # 0=unvisited, 1=in progress, 2=done
    def process(start):
        path = []
        node = start
        while visited[node] == 0:
            visited[node] = 1
            path.append(node)
            node = edges[node]
        if visited[node] == 1:
            # found cycle
            cycle_start = path.index(node)
            cycle_len = len(path) - cycle_start
            for i in range(cycle_start, len(path)):
                ans[path[i]] = cycle_len
                visited[path[i]] = 2
            for i in range(cycle_start - 1, -1, -1):
                ans[path[i]] = ans[path[i+1]] + 1
                visited[path[i]] = 2
        else:
            # node already processed
            for i in range(len(path) - 1, -1, -1):
                ans[path[i]] = ans[node] + (len(path) - i)
                visited[path[i]] = 2
    for i in range(n):
        if visited[i] == 0:
            process(i)
