def minOperations(self, s1, s2, x):
    diffs = [i for i in range(len(s1)) if s1[i] != s2[i]]
    n = len(diffs)
    if n % 2 == 1:
        return -1
    if n == 0:
        return 0
    dp = [0.0] * (n + 1)
    dp[1] = x / 2
    for i in range(2, n + 1):
        dp[i] = min(dp[i-1] + x / 2, dp[i-2] + diffs[i-1] - diffs[i-2])
    return int(dp[n])

def maxSum(self, nums, k):
    MOD = 10**9 + 7
    bits = [0] * 30
    for x in nums:
        for i in range(30):
            if x >> i & 1:
                bits[i] += 1
    res = 0
    for _ in range(k):
        val = 0
        for i in range(30):
            if bits[i] > 0:
                val |= (1 << i)
                bits[i] -= 1
        res = (res + val * val) % MOD
    return res

