def minGroupsForValidAssignment(self, nums):
    from collections import Counter
    freq = Counter(nums)
    counts = list(freq.values())
    min_cnt = min(counts)
    for k in range(min_cnt, 0, -1):
        total = 0
        valid = True
        for c in counts:
            # c = a*(k+1) + b*k, need a+b groups, a>=0, b>=0
            q, r = divmod(c, k + 1)
            if r == 0:
                total += q
            elif q >= k - r:
                total += q + 1
            else:
                valid = False
                break
        if valid:
            return total
    return len(nums)

def minimumChanges(self, s, k):
    n = len(s)
    def semi_cost(l, r):
        length = r - l + 1
        best = length
        for d in range(1, length):
            if length % d == 0:
                c = 0
                for start in range(d):
                    lo, hi = start, start + length - d
                    while lo < hi:
                        if s[l+lo] != s[l+hi]:
                            c += 1
                        lo += d
                        hi -= d
                best = min(best, c)
        return best
    cost = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            cost[i][j] = semi_cost(i, j)
    INF = float('inf')
    dp = [[INF]*(k+1) for _ in range(n)]
    for i in range(1, n):
        dp[i][1] = cost[0][i]
    for p in range(2, k+1):
        for i in range(2*p-1, n):
            for m in range(2*p-3, i):
                dp[i][p] = min(dp[i][p], dp[m][p-1] + cost[m+1][i])
    return dp[n-1][k]

def numberOfWays(self, n, m, k):
    MOD = 10**9 + 7
    # 4 states: (same_row, same_col), (same_row, diff_col), (diff_row, same_col), (diff_row, diff_col)
    # Matrix exponentiation on 4x4 transition matrix
    def mat_mul(A, B):
        size = len(A)
        C = [[0]*size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                for p in range(size):
                    C[i][j] = (C[i][j] + A[i][p]*B[p][j]) % MOD
        return C
    def mat_pow(M, exp):
        size = len(M)
        result = [[int(i==j) for j in range(size)] for i in range(size)]
        while exp:
            if exp & 1:
                result = mat_mul(result, M)
            M = mat_mul(M, M)
            exp >>= 1
        return result
    # Transitions: from any cell, move to any cell in same row or same col (excluding self)
    T = [
        [0, m-1, n-1, 0],
        [1, m-2, 0, n-1],
        [1, 0, n-2, m-1],
        [0, 1, 1, n+m-4]
    ]
    res = mat_pow(T, k)
    return res[3][0]  # start at diff_row, diff_col -> reach same_row, same_col

