def maximumPoints(self, edges, coins, k):
    from functools import lru_cache
    n = len(coins)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    @lru_cache(maxsize=None)
    def dfs(node, parent, halves):
        val = coins[node] >> halves
        # Option 1: collect val - k
        opt1 = val - k
        for child in adj[node]:
            if child != parent:
                opt1 += dfs(child, node, halves)
        # Option 2: collect val // 2, children get extra halve
        opt2 = val >> 1
        if halves < 13:
            for child in adj[node]:
                if child != parent:
                    opt2 += dfs(child, node, halves + 1)
        return max(opt1, opt2)
    return dfs(0, -1, 0)

def maxProfit(self, prices, profits):
    n = len(prices)
    MAX_P = max(prices) + 2
    # BIT for prefix max
    left_max = [0] * MAX_P
    right_max = [0] * MAX_P
    def update(bit, i, val):
        while i < len(bit):
            bit[i] = max(bit[i], val)
            i += i & (-i)
    def query(bit, i):
        res = 0
        while i > 0:
            res = max(res, bit[i])
            i -= i & (-i)
        return res
    # suffix max for right side using reversed BIT
    def update_suffix(bit, i, val):
        i = MAX_P - 1 - i
        update(bit, i, val)
    def query_suffix(bit, i):
        i = MAX_P - 1 - i
        return query(bit, i)
    left_best = [0] * n
    for i in range(n):
        left_best[i] = query(left_max, prices[i] - 1)
        update(left_max, prices[i], profits[i])
    right_best = [0] * n
    for i in range(n-1, -1, -1):
        right_best[i] = query_suffix(right_max, prices[i] + 1)
        update_suffix(right_max, prices[i], profits[i])
    res = -1
    for j in range(n):
        if left_best[j] > 0 and right_best[j] > 0:
            res = max(res, left_best[j] + profits[j] + right_best[j])
    return res

