        adj[u].append(v)
        adj[v].append(u)
    total = sum(values)
    def dfs(node, parent):
        children = [c for c in adj[node] if c != parent]
        if not children:
            return values[node]  # must keep leaf
        child_sum = sum(dfs(c, node) for c in children)
        return min(values[node], child_sum)  # keep self or keep children
    return total - dfs(0, -1)

def distributeCandies(self, n, limit):
    def C2(x):
        return x * (x - 1) // 2 if x >= 2 else 0
    def at_least(k):
        # at least k children exceed limit
        rem = n - k * (limit + 1)
        if rem < 0:
            return 0
        from math import comb
        return comb(3, k) * C2(rem + 2)
    return at_least(0) - at_least(1) + at_least(2) - at_least(3)

