def maximumStrongPairXor(self, nums):
    nums.sort()
    # Trie approach with sliding window
    trie = {}
    def insert(x):
        node = trie
        for i in range(19, -1, -1):
            bit = (x >> i) & 1
            if bit not in node:
                node[bit] = {'cnt': 0}
            node = node[bit]
            node['cnt'] += 1
    def remove(x):
        node = trie
        for i in range(19, -1, -1):
            bit = (x >> i) & 1
            node = node[bit]
            node['cnt'] -= 1
    def query(x):
        node = trie
        res = 0
        for i in range(19, -1, -1):
            bit = (x >> i) & 1
            want = 1 - bit
            if want in node and node[want].get('cnt', 0) > 0:
                res |= (1 << i)
                node = node[want]
            elif bit in node and node[bit].get('cnt', 0) > 0:
                node = node[bit]
            else:
                break
        return res
    ans = 0
    left = 0
    for right in range(len(nums)):
        insert(nums[right])
        while nums[right] - nums[left] > nums[left]:
            remove(nums[left])
            left += 1
        ans = max(ans, query(nums[right]))
    return ans

