            for i in range(1,len(bars)):
                cur = cur+1 if bars[i]==bars[i-1]+1 else 1
                mx=max(mx,cur)
            return mx
        h = maxC(hBars)+1 if hBars else 2
        v = maxC(vBars)+1 if vBars else 2
