    def findMaximumLength(self, nums: list[int]) -> int:
        from collections import deque
        n=len(nums); prefix=[0]*(n+1)
        for i in range(n): prefix[i+1]=prefix[i]+nums[i]
        dp=[0]*(n+1); last=[0]*(n+1); dq=deque([0])
        for i in range(1,n+1):
            while len(dq)>1 and prefix[dq[1]]+last[dq[1]]<=prefix[i]: dq.popleft()
            j=dq[0]; dp[i]=dp[j]+1; last[i]=prefix[i]-prefix[j]
            while dq and prefix[dq[-1]]+last[dq[-1]]>=prefix[i]+last[i]: dq.pop()
            dq.append(i)
        return dp[n]

