    def minimumAddedCoins(self, coins: list[int], target: int) -> int:
        coins.sort(); reach=added=i=0
        while reach<target:
            if i<len(coins) and coins[i]<=reach+1: reach+=coins[i]; i+=1
            else: reach+=reach+1; added+=1
        return added

class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        def f(seg):
            r=0
            for m in range(1,27):
                w=m*k
                if w>len(seg): break
                freq=[0]*26
                for i in range(len(seg)):
                    freq[ord(seg[i])-97]+=1
                    if i>=w: freq[ord(seg[i-w])-97]-=1
                    if i>=w-1 and all(c==0 or c==k for c in freq): r+=1
            return r
        res=0; st=0
        for i in range(1,len(word)):
            if abs(ord(word[i])-ord(word[i-1]))>2: res+=f(word[st:i]); st=i
        return res+f(word[st:])

class Solution:
    def numberOfSequence(self, n: int, sick: list[int]) -> int:
        MOD=10**9+7; gaps=[]
        if sick[0]>0: gaps.append(sick[0])
        for i in range(1,len(sick)):
            g=sick[i]-sick[i-1]-1
            if g>0: gaps.append(g)
        if sick[-1]<n-1: gaps.append(n-1-sick[-1])
        total=sum(gaps)
        fact=[1]*(total+1)
        for i in range(1,total+1): fact[i]=fact[i-1]*i%MOD
        inv_f=[1]*(total+1); inv_f[total]=pow(fact[total],MOD-2,MOD)
        for i in range(total-1,-1,-1): inv_f[i]=inv_f[i+1]*(i+1)%MOD
        res=fact[total]
        for g in gaps: res=res*inv_f[g]%MOD
        for i in range(1,len(sick)):
            g=sick[i]-sick[i-1]-1
            if g>0: res=res*pow(2,g-1,MOD)%MOD
        return res

class Solution:
    def sameEndSubstringCount(self, s: str, queries: list[list[int]]) -> list[int]:
        n=len(s); pre=[[0]*(n+1) for _ in range(26)]
        for i in range(n):
            for c in range(26): pre[c][i+1]=pre[c][i]
            pre[ord(s[i])-97][i+1]+=1
        res=[]
        for l,r in queries:
            t=0
            for c in range(26): f=pre[c][r+1]-pre[c][l]; t+=f*(f+1)//2
            res.append(t)
        return res

