class Solution:
    def maxSubarrayLength(self, nums: list[int], k: int) -> int:
        from collections import defaultdict
        freq=defaultdict(int); left=res=0
        for right in range(len(nums)):
            freq[nums[right]]+=1
            while freq[nums[right]]>k: freq[nums[left]]-=1; left+=1
            res=max(res,right-left+1)
        return res

class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: list[list[int]]) -> int:
        res=0
        for mask in range(1<<n):
            d=[[float('inf')]*n for _ in range(n)]
            for i in range(n): d[i][i]=0
            for u,v,w in roads:
                if mask>>u&1 and mask>>v&1: d[u][v]=min(d[u][v],w); d[v][u]=min(d[v][u],w)
            for k2 in range(n):
                if not mask>>k2&1: continue
                for i in range(n):
                    if not mask>>i&1: continue
                    for j in range(n):
                        if not mask>>j&1: continue
                        d[i][j]=min(d[i][j],d[i][k2]+d[k2][j])
            if all(d[i][j]<=maxDistance for i in range(n) if mask>>i&1 for j in range(i+1,n) if mask>>j&1): res+=1
        return res

