class Solution:
    def countSubarrays(self, nums: list[int], k: int) -> int:
        mx=max(nums); n=len(nums); left=count=res=0
        for right in range(n):
            if nums[right]==mx: count+=1
            while count>=k:
                res+=n-right
                if nums[left]==mx: count-=1
                left+=1
        return res

class Solution:
    def numberOfGoodPartitions(self, nums: list[int]) -> int:
        MOD=10**9+7; last={v:i for i,v in enumerate(nums)}
        cuts=0; mx=0
        for i in range(len(nums)-1):
            mx=max(mx,last[nums[i]])
            if mx==i: cuts+=1
        return pow(2,cuts,MOD)

class Solution:
    def divisibleTripletCount(self, nums: list[int], d: int) -> int:
        from collections import defaultdict
        n=len(nums); res=0
        for k in range(2,n):
            cnt=defaultdict(int)
            for i in range(k):
                cnt[(nums[i])%d]+=1
            # Rebuild: for each k, check all pairs before it
        # O(n^2) correct
        res=0; n=len(nums)
        from collections import defaultdict
        for j in range(n):
            cnt=defaultdict(int)
            for i in range(j):
                cnt[(nums[i]+nums[j])%d]+=1
        # Actually need i<j<k
        cnt=defaultdict(int)
        res=0
        for j in range(n):
            for k2 in range(j+1,n):
                need=(d-(nums[j]+nums[k2])%d)%d
                # no, need prefix
        # Simplest correct O(n^2)
        cnt=defaultdict(int)
        res=0
        for k2 in range(n):
            for j in range(k2):
                if (nums[j]+nums[k2])%d==0:
                    pass
        # Direct approach
        res=0
        pair_cnt=defaultdict(int)
        for k2 in range(n):
            need=(d-nums[k2]%d)%d
            res+=pair_cnt[need]
            for j in range(k2):
                pair_cnt[(nums[j]+nums[k2])%d]+=1
        return res

class Solution:
    def findMissingAndRepeatedValues(self, grid: list[list[int]]) -> list[int]:
