class Solution:
    def minimumCost(self, nums: list[int]) -> int:
        def gen_palindromes():
            pals=[]
            for length in range(1,11):
                half_len=(length+1)//2
                start=10**(half_len-1) if half_len>1 else 1
                end=10**half_len
                for h in range(start,end):
                    s=str(h)
                    if length%2==0: pal=s+s[::-1]
                    else: pal=s+s[-2::-1]
                    pals.append(int(pal))
            return sorted(pals)
        pals=gen_palindromes()
        nums.sort(); n=len(nums); median=nums[n//2]
        import bisect
        idx=bisect.bisect_left(pals,median)
        best=float('inf')
        for i in range(max(0,idx-1),min(len(pals),idx+2)):
            cost=sum(abs(x-pals[i]) for x in nums)
            best=min(best,cost)
        return best

class Solution:
    def maxFrequencyScore(self, nums: list[int], k: int) -> int:
        nums.sort(); n=len(nums)
        prefix=[0]*(n+1)
        for i in range(n): prefix[i+1]=prefix[i]+nums[i]
        def cost(l,r):
            mid=(l+r)//2
            left_cost=nums[mid]*(mid-l)-(prefix[mid]-prefix[l])
            right_cost=(prefix[r+1]-prefix[mid+1])-nums[mid]*(r-mid)
            return left_cost+right_cost
        def check(m):
            for i in range(n-m+1):
                if cost(i,i+m-1)<=k: return True
            return False
        lo,hi=1,n
        while lo<hi:
            mid2=(lo+hi+1)//2
            if check(mid2): lo=mid2
            else: hi=mid2-1
        return lo

class Solution:
    def minimumCoins(self, prices: list[int]) -> int:
        from collections import deque
        n=len(prices); dp=[0]*(n+1); dq=deque()
        for i in range(n,0,-1):
            while dq and dq[0]>2*i: dq.popleft()
            if 2*i>=n: dp[i]=prices[i-1]
            else: dp[i]=prices[i-1]+dp[dq[0]]
            while dq and dp[i]<=dp[dq[-1]]: dq.pop()
            dq.append(i)
        return dp[1]

